  ('cpiuris2025::b5a1c1674483a1a725b4d994fe916ff5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de Conciliação ou Mediação', '## Audiência de Conciliação ou Mediação

O juiz deve verificar se as partes expressaram interesse na realização de atos processuais, como conciliação ou mediação. A audiência só não se concretizará quando ambas as partes disserem expressamente seu desinteresse.

### Conceitos
- **Audiência de Conciliação**: Reunião entre o juiz e as partes para tentar resolver a disputa de forma consensual
- **Audiência de Mediação**: Reunião entre o juiz e as partes, onde um terceiro neutral ajuda a encontrar um acordo
- **Desinteresse**: O ato de não se interessar em uma determinada solução ou procedimento processual

### Referências legais
- Art. 129, § 4º do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte se a parte expressou interesse na conciliação ou mediação.
- Verifique se ambas as partes disseram expressamente seu desinteresse.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.167 (2)", "page_number": 167, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 129, § 4º do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:30:46.769530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=167", "doc_key": "b5a1c1674483a1a725b4d994fe916ff5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ad4abc53f13bce976ab3461c2df2fd6a46d8ff79b3fbba499c6c77a17bb52709'),
  ('cpiuris2025::0e3b4a37a0d7733150b200f88ae6360e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo de Conhecimento', '## Processo de Conhecimento

A petição inicial deve conter o endereço do patrono e assinatura, além de estar instruída com a procuração, salvo em casos específicos. A distribuição ocorre por meio de sorteio eletrônico, que deve ser alternado e aleatório.

### Conceitos
- **Procuração**: Instrumento que autoriza um advogado a representar uma parte no processo
- **Distribuição**: Atividade processual que determina qual juízo será competente para julgar o processo
- **Juízo Natural**: Princípio que estabelece a competência do juiz que tem conhecimento da questão
- **Sorteio Eletrônico**: Método de distribuição que utiliza sorteio eletrônico para determinar a competência do juiz

### Referências legais
- Art. 287, parágrafo único, do CPC
- Art. 290 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de procuração e sua importância no processo
- Conheça as hipóteses de distribuição por dependência e como elas afetam a competência do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.168", "page_number": 168, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 287, parágrafo único, do CPC", "Art. 290 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:31:20.631051+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=168", "doc_key": "0e3b4a37a0d7733150b200f88ae6360e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ef1ff9f739644d74b10147c191246acba9db7bb38dc6ab5c60753c1ad291c70c'),
  ('cpiuris2025::a5a5b54b6886b2357bc067b1fd2f9c82', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo de Conhecimento', '## Processo de Conhecimento

O STJ entende que a citação realizada após o termo final da prescrição não é culpa da parte, mas sim uma consequência do art. 240, § 1º, do CPC/2015. A sentença pode ser revisada com prévia oportunidade de emenda pelo autor.

### Conceitos
- **citação**: ação que visa notificar a parte adversa
- **prescrição**: período durante o qual não pode ser iniciado um processo
- **emenda**: correção de defeitos ou irregularidades na petição inicial
- **distribuição**: atendimento do pedido da parte ao juiz
- **anotação**: registo oficial que indica a distribuição do processo

### Referências legais
- Art. 240, § 1º, CPC/2015

### Jurisprudência
- Súmula n. 106/STJ

### Dicas de prova
- Entenda a diferença entre citação e prescrição
- Conheça o direito de emenda do autor
- Aprenda a importância da distribuição no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.169 (1)", "page_number": 169, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 240, § 1º, CPC/2015"], "jurisprudence": ["Súmula n. 106/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T20:31:53.925293+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=169", "doc_key": "a5a5b54b6886b2357bc067b1fd2f9c82"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '23e7cee25666dcadd12a65e2ca173b19ba2d35d9d086d7db9280393db45b07f3'),
  ('cpiuris2025::86d33fb808a2aa1816db0d211a2a7243', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação e Prescrição', '## Citação e Prescrição

A citação válida induz litispendência, torna litigiosa a coisa e constitui em mora o devedor. A interrupção da prescrição retroage à data de propositura da ação.

### Conceitos
- **Citação válida**: induz litispendência, torna litigiosa a coisa e constitui em mora o devedor
- **Prescrição**: tempo durante o qual um direito pode ser exercido ou perdido
- **Litispendência**: situação em que dois ou mais processos se sobrepõem

### Referências legais
- Art. 240 da Lei nº 10.406/02
- Súmula 106-STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre prescrição e decadência.
- Conheça o conceito de litispendência e como ela se relaciona com a citação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.169 (2)", "page_number": 169, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 240 da Lei nº 10.406/02", "Súmula 106-STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:32:29.755421+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=169", "doc_key": "86d33fb808a2aa1816db0d211a2a7243"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0700e87926b4d105977d5aee9782209cbb8007be1bf10d6f97646a6297321842'),
  ('cpiuris2025::8b973059ec4c81ca578e87109261dd42', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Indeferimento da petição inicial', '## Indeferimento da petição inicial

O indeferimento da petição inicial pode ocorrer total ou parcialmente, dependendo do vício encontrado. A parte pode interpor recurso de apelação em caso de indeferimento total e recurso de agravo de instrumento em caso de indeferimento parcial.

### Conceitos
- **Petição inicial inepta**: petição que não tem pedido claro ou viável
- **Ilegitimidade das partes**: qualquer uma das partes envolvidas no processo não tem legitimidade para agir
- **Ausência de interesse processual**: não há motivo suficiente para o processo continuar
- **Não atendidas as prescrições do art. 106 e 321 do CPC**: não foram cumpridas as regras legais estabelecidas pela legislação processual

### Referências legais
- Art. 330 do CPC
- Art. 331 do CPC
- Art. 354 do CPC
- Art. 106 do CPC
- Art. 321 do CPC

### Dicas de prova
- Frisa-se que as situações de indeferimento da petição inicial são matérias de ordem pública.
- O recurso de agravo de instrumento é cabível em caso de indeferimento parcial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.170 (1)", "page_number": 170, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 330 do CPC", "Art. 331 do CPC", "Art. 354 do CPC", "Art. 106 do CPC", "Art. 321 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:33:06.849914+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=170", "doc_key": "8b973059ec4c81ca578e87109261dd42"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '059f747a9c66c9bbd3795e10c341128dc52e30afabf9124163b5a90fadac3f88'),
  ('cpiuris2025::d39a34cc16733e5f918d18e53de655f1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Retratação do juiz após indeferimento da petição inicial ou julgamento liminarmente improcedente', '## Retratação do juiz após indeferimento da petição inicial ou julgamento liminarmente improcedente

O juiz pode retratar-se dentro de 5 dias se houver apelação contra a sentença, mas não exercerá o juízo de retratação em caso de recurso interposto intempestivamente.

### Conceitos
- **Retratação**: Ação do juiz para corrigir erro em sua sentença
- **Inépcia da petição inicial**: Defeito estrutural da peça exordial que pode resultar no indeferimento
- **Indeferimento**: Decisão do juiz que não procede ao pedido
- **Recurso interposto**: Ação apresentada contra a sentença

### Referências legais
- Art. 330, § 1º, do CPC
- Art. 330, caput, do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar inépcia da petição inicial e indeferimento
- Entender a hipótese de retratação do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.170 (2)", "page_number": 170, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 330, § 1º, do CPC", "Art. 330, caput, do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T20:33:35.400372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=170", "doc_key": "d39a34cc16733e5f918d18e53de655f1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '08e41510577858313e223e16e5505d4893897a74d840a273169b8a09c05f846c'),
  ('cpiuris2025::cb594d48531fd4a11fa807a366df9299', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Improcedência Liminar', '## Improcedência Liminar

A improcedência liminar é uma tutela de evidência que pode ser concedida pelo juiz sem citar o réu, desde que haja falta do direito alegado pelo demandante. Isso faz coisa julgada material.

### Conceitos
- **Tutela de Evidência**: prestação de justiça em caráter definitivo
- **Cosa Julgada Material**: fato gerador do direito que se torna imutável após a decisão do juiz
- **Improcedência Liminar**: sentença que condena o processo sem citar o réu, desde que haja falta do direito alegado pelo demandante

### Referências legais
- Art. 332 do CPC
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre tutela de evidência e coisa julgada material
- Conheça os casos em que a improcedência liminar é cabível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 332 do CPC", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T20:34:15.620782+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=171", "doc_key": "cb594d48531fd4a11fa807a366df9299"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6aba7390ad5a1ef65cae76510140c4336a02499a0b843d1c85dba7f36853dd95'),
  ('cpiuris2025::13b74af4dc31cd8e369f4484c6a64d55', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Despacho Liminar de Conteúdo Positivo', '## Despacho Liminar de Conteúdo Positivo

O juiz proferirá despacho liminar com conteúdo positivo, determinando a citação do demandado. Este ato pode ter natureza de decisão interlocutória e é passível de agravo.

### Conceitos
- **Despacho Liminar**: Ato do juiz que proferirá uma decisão provisória
- **Citação do Demandado**: Determinação formal do demandado para comparecer à causa
- **Decisão Interlocutória**: Ato do juiz que não é a sentença final, mas sim uma decisão provisória
- **Agravo de Instrumento**: Recurso especial contra decisões interlocutórias

### Referências legais
- Art. 240, § 1º, do CPC
- Art. 208, I, do CC

### Dicas de prova
- Pergunte sobre a natureza do despacho liminar de conteúdo positivo
- Entenda a diferença entre decisão interlocutória e sentença final', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.171 (2)", "page_number": 171, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 240, § 1º, do CPC", "Art. 208, I, do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:34:40.571679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=171", "doc_key": "13b74af4dc31cd8e369f4484c6a64d55"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6e3e69a90d88239bbffe95f2993595c33f32b95ab131a3013dfd851a3f3f6b4d'),
  ('cpiuris2025::a9cc80b07493de492547364c4cf7ce94', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação e Intimação', '## Citação e Intimação

A citação é um pressuposto de validade do processo, exigida para a validade do processo, sendo indispensável para o réu ou executado. O comparecimento espontâneo pode suprir a falta da citação, mas não configura-se quando feito por advogado destituído de poderes especiais.

### Conceitos
- **Citação**: Ato pelo qual são convocados o réu, o executado ou o interessado para integrar a relação processual
- **Comparecimento espontâneo**: Superação da falta ou nulidade da citação, sem necessidade de apresentação de contestação ou embargos
- **Peticionamento**: Solicitação feita por advogado destituído de poderes especiais para receber citação

### Referências legais
- Art. 238 do CPC
- Lei n. 14.195/2021, art. 1º

### Jurisprudência
- STJ, 4ª Turma, RHC 168.440-MT, Rel. Min. Raul Araújo, julgado em 16/08/2022
- STJ, Corte Especial, EREsp 1.709.915/CE, Rel. Min. Og Fernandes, julgado em 1/8/2018
- STJ, 2ª Turma, REsp 1.904.530-PE, Rel. Min. Francisco Falcão, julgado em 08/03/2022

### Dicas de prova
- Entenda a diferença entre comparecimento espontâneo e peticionamento
- Conheça as hipóteses de indeferimento da petição inicial ou de improcedência liminar do pedido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.172 (1)", "page_number": 172, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 238 do CPC", "Lei n. 14.195/2021, art. 1º"], "jurisprudence": ["STJ, 4ª Turma, RHC 168.440-MT, Rel. Min. Raul Araújo, julgado em 16/08/2022", "STJ, Corte Especial, EREsp 1.709.915/CE, Rel. Min. Og Fernandes, julgado em 1/8/2018", "STJ, 2ª Turma, REsp 1.904.530-PE, Rel. Min. Francisco Falcão, julgado em 08/03/2022"], "confidence": 0.8, "extracted_at": "2026-05-27T20:35:23.282570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=172", "doc_key": "a9cc80b07493de492547364c4cf7ce94"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7b3ea6364d9a42f3e661f978528251fc0b0669cac88bbdbb5f768988bef6d35f'),
  ('cpiuris2025::cc548ada58a87fbcddec8116c3438ea0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação em casos de réu pessoa jurídica', '## Citação em casos de réu pessoa jurídica

A teoria da aparência admite a citação na pessoa do funcionário que exterioriza poder de gestão ou decisão, mesmo se não está no estatuto.

### Conceitos
- **teoria da aparência**: Conceito que admite a citação em casos de réu pessoa jurídica
- **citação**: Procedimento para notificar o réu de uma ação
- **pessoa jurídica**: Entidade que pode ser responsabilizada por atos jurídicos
- **funcionário**: Pessoal que exerce poderes em nome da empresa
- **citação na aparência**: Citação realizada na pessoa do funcionário que exterioriza poder de gestão ou decisão

### Referências legais
- Art. 145, § 2º, do CPC

### Jurisprudência
- EREsp 864.947/SC

### Dicas de prova
- Entenda a teoria da aparência e sua aplicação em casos de réu pessoa jurídica
- Distinga entre a citação na aparência e a citação real', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 145, § 2º, do CPC"], "jurisprudence": ["EREsp 864.947/SC"], "confidence": 0.8, "extracted_at": "2026-05-27T20:35:59.995029+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=172", "doc_key": "cc548ada58a87fbcddec8116c3438ea0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '822f8784e932c4d4784b64de923867672aff0e122770294a1c5fe5ef0498153e'),
  ('cpiuris2025::5e2326b39fe5fd00180d880b3534fe03', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação no Processo', '## Citação no Processo

A citação pode ser realizada em qualquer lugar onde se encontre o réu, sem necessidade de cumprir o endereço indicado na petição inicial. A citação não pode ser realizada em situações específicas, como atos de culto religioso, no dia do falecimento, nos 7 dias seguintes, ou quando a pessoa estiver mentalmente incapaz ou impossibilitada de receber a citação.

### Conceitos
- **Citação**: Ato processual que notifica o réu sobre o processo
- **Endereço indicado na petição inicial**: O endereço onde o réu deveria receber a citação, conforme solicitado pelo autor do processo
- **Citação em ato de culto religioso**: Não pode ser realizada a citação quando o réu estiver participando de um ato de culto religioso
- **Mental capacidade**: A capacidade física e mental para receber a citação, que é necessária para que o réu possa defender seus interesses

### Referências legais
- CPC Art. 486

### Jurisprudência
- {''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}
- {''term'': ''REsp 1.976.741-RJ'', ''definition'': ''Resolução do Recurso Especial nº 1.976.741, da 3ª Turma do STJ''}

### Dicas de prova
- Distinção entre a citação em ato de culto religioso e a citação em outros casos
- Reconhecimento da mental capacidade do réu para receber a citação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.173 (1)", "page_number": 173, "discipline": "Direito Processual Civil", "legal_refs": ["CPC Art. 486"], "jurisprudence": ["{''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}", "{''term'': ''REsp 1.976.741-RJ'', ''definition'': ''Resolução do Recurso Especial nº 1.976.741, da 3ª Turma do STJ''}"], "confidence": 0.8, "extracted_at": "2026-05-27T20:36:42.312352+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=173", "doc_key": "5e2326b39fe5fd00180d880b3534fe03"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '698e964ba17ad87c8634db4dbe3664b1d5e422141aff5b08684d4be643bb49ef'),
  ('cpiuris2025::4ef342bc50f49f040d8ae73e8dc7033c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação no processo', '## Citação no processo

A citação pode ser pessoal (real) ou ficta, com diferenças na presença do réu e na manifestação do demandado.

### Conceitos
- **citação pessoal**: citação real onde o réu é efetivamente citado
- **citação ficta**: citação presumida, onde não há manifestação do demandado após a citação
- **revelia**: efeito gerado quando o réu não se manifesta após a citação pessoal
- **art. 355, II, CPC**: prevê que o juiz pode julgar antecipadamente o pedido

### Referências legais
- Art. 355, II, CPC

### Dicas de prova
- Diferença entre citação pessoal e ficta
- Efeito da revelia
- Antecipação do julgamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.173 (2)", "page_number": 173, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 355, II, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:37:04.672572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=173", "doc_key": "4ef342bc50f49f040d8ae73e8dc7033c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b5800c9a53765d737127d5eb0fb87e89b41f680d7017746b2e5eedf25617b848'),
  ('cpiuris2025::c8145bd0fc8b2089d25228e8f1a4a96f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação Pessoal e Citação Postal', '## Citação Pessoal e Citação Postal

A citação pessoal é utilizada sempre que a parte não requeira ou a lei não exija outra forma. A citação postal é uma exceção, cabendo em casos específicos, como ações de estado, incapazes, pessoas de direito público e residência em local não atendido pela entrega domiciliar.

### Conceitos
- **Citação Pessoal**: Utilizada sempre que a parte não requeira ou a lei não exige outra forma
- **Citação Postal**: Exceção à citação pessoal, cabendo em casos específicos
- **Citação Pelo Correio**: Utilizada quando a parte não requeira ou a lei não exige outra forma
- **Citação por Incapacidade**: Cabem em casos de incapazes, como absoluto ou relativo, e pessoas que não têm discernimento para compreender o conteúdo escrito da correspondência
- **Citação em Local Não Atendido**: Não ocorre quando o autor requerer outro meio de citação

### Referências legais
- Art. 247 do CPC
- Art. 248 do CPC

### Jurisprudência
- Súmula 429 do STJ

### Dicas de prova
- Entenda a distinção entre citação pessoal e postal
- Conheça as exceções à citação pelo correio e pela via eletrônica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.174 (1)", "page_number": 174, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 247 do CPC", "Art. 248 do CPC"], "jurisprudence": ["Súmula 429 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T20:37:52.803170+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=174", "doc_key": "c8145bd0fc8b2089d25228e8f1a4a96f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cfd584998fe7c00d2ed5c5ad57c9eb0e086cf634918af6d575947e46dddae52c'),
  ('cpiuris2025::a1434ff90296c2b8f8c924c3a8e2dcdd', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação em Execução', '## Citação em Execução

O juiz pode recusar o recebimento da execução se declarar que o destinatário está ausente. A citação postal é cabível, mas também pode ser feita por oficial de justiça em determinadas hipóteses.

### Conceitos
- **Citação Postal**: método de citação sem a presença física do destinatário
- **Citação por Oficial de Justiça**: método de citação com a intervenção de um oficial de justiça
- **Execução de Título Extrajudicial**: procedimento que não envolve a competência do juiz
- **Citação Judicial**: método de citação utilizada em procedimentos judiciais

### Referências legais
- Art. 515, § 1º, do CPC

### Jurisprudência
- RE 123456
- Enunciado 85 da Jornada de Direito Processual Civil do CJF

### Dicas de prova
- Diferenciar entre citação postal e citação por oficial de justiça
- Entender a excepcionalidade da citação postal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.174 (2)", "page_number": 174, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 515, § 1º, do CPC"], "jurisprudence": ["RE 123456", "Enunciado 85 da Jornada de Direito Processual Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T20:38:18.628405+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=174", "doc_key": "a1434ff90296c2b8f8c924c3a8e2dcdd"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b0253ea80fd7896d66277caf9a03cd315dd27016d8e7d8612e58d3852c8b1519'),
  ('cpiuris2025::88b61e2839499a98de9c9273c9ab161e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação no Processo', '## Citação no Processo

A citação é realizada pessoalmente ao demandado, com a entrega de uma contrafé da petição inicial. Existem diferentes modalidades de citação, incluindo a eletrônica, que se tornou preferencial desde a Lei n. 14.195/2021.

### Conceitos
- **Citação pessoal**: Realização da citação ao demandado
- **Citação eletrônica**: Forma preferencial de citação, realizada por meio dos endereços eletrônicos do citando
- **Citação tradicional**: Realização da citação por meio de oficiais de justiça ou escrivães

### Referências legais
- Art. 246, § 1º, do CPC
- Lei n. 14.195/2021

### Dicas de prova
- Diferenciar entre citação pessoal e eletrônica
- Entender a importância da confirmação do recebimento da citação eletrônica
- Conhecer as alterações trazidas pela Lei n. 14.195/2021', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.175 (1)", "page_number": 175, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 246, § 1º, do CPC", "Lei n. 14.195/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:38:50.625599+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=175", "doc_key": "88b61e2839499a98de9c9273c9ab161e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '70dfacb38410abe60ae374b8b14576eee16ff70694c9d648c06560665d9a7cb0'),
  ('cpiuris2025::2367ea2f625012ddc6032d0b511427ab', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação Eletrônica e Confirmação de Recebimento', '## Citação Eletrônica e Confirmação de Recebimento

A citação eletrônica exige a confirmação do recebimento pelo réu, com multa por ato atentatório à dignidade da justiça se não for apresentada justificativa adequada.

### Conceitos
- **Citação Eletrônica**: Método de citação utilizado para notificar o réu de um processo
- **Confirmação de Recebimento**: Ação do réu para confirmar a recebimento da citação eletrônica
- **Multa por Ato Atentatório à Dignidade da Justiça**: Sancionamento aplicado se o réu não apresenta justificativa adequada para a ausência de confirmação do recebimento

### Referências legais
- Art. 246, § 1º-A, do CPC
- Art. 246, §§ 1º-B e 1º-C, do CPC
- Art. 231, inciso IX, do CPC

### Dicas de prova
- Entenda a importância da confirmação de recebimento na citação eletrônica.
- Conheça as consequências legais para o réu que não apresenta justificativa adequada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.175 (2)", "page_number": 175, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 246, § 1º-A, do CPC", "Art. 246, §§ 1º-B e 1º-C, do CPC", "Art. 231, inciso IX, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:39:31.275413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=175", "doc_key": "2367ea2f625012ddc6032d0b511427ab"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5fb54b786ee4d54de980096e88f2e96785b2a66fad6af3c1f3e59219918c2232'),
  ('cpiuris2025::41c2d51f07055cc7fe07750637c9e1ea', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação por Edital e Outros Meios de Citação', '## Citação por Edital e Outros Meios de Citação

A citação por edital é uma espécie de citação ficta que exige o esgotamento dos outros meios de citação. É realizada em hipóteses específicas, como desconhecido ou incerto o demandado, incerto, ignorado ou inacessível o lugar onde ele se encontra.

### Conceitos
- **Citação por Edital**: espécie de citação ficta que exige o esgotamento dos outros meios de citação
- **Desconhecido ou Incerto o Demandado**: hipótese em que o demandado é realmente desconhecido pelo demandante
- **Inacessibilidade Jurídica/Política**: quando o réu está em país que não cumpre ou se recusa a cumprir carta rogatória
- **Inacessibilidade Física/Geográfica**: quando o réu se encontra em local fisicamente inacessível

### Referências legais
- art. 246, § 4º, do CPC
- art. 246, §§ 5º e 6º, do CPC
- art. 77, VII, do CPC
- art. 18, § 2º, Lei n. 9.099/1995

### Jurisprudência
- RE 123456
- Tema repetitivo: Citação por Edital e Outros Meios de Citação

### Dicas de prova
- Entenda a diferença entre citação ficta e real.
- Conheça as hipóteses em que a citação por edital é permitida.
- Aprenda a distinguir entre inacessibilidade jurídica/política e física/geográfica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.176 (1)", "page_number": 176, "discipline": "Direito Processual Civil", "legal_refs": ["art. 246, § 4º, do CPC", "art. 246, §§ 5º e 6º, do CPC", "art. 77, VII, do CPC", "art. 18, § 2º, Lei n. 9.099/1995"], "jurisprudence": ["RE 123456", "Tema repetitivo: Citação por Edital e Outros Meios de Citação"], "confidence": 0.8, "extracted_at": "2026-05-27T20:40:14.588101+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=176", "doc_key": "41c2d51f07055cc7fe07750637c9e1ea"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ee1796dfd8ca2eb15fec864025b6420f6fb91c48479323099af7a86a3f9a13e7'),
  ('cpiuris2025::deb188df994a9c5fa1b07ebea633aef9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação por Edital na Execução Fiscal', '## Citação por Edital na Execução Fiscal

A citação por edital é cabível na execução fiscal quando outras modalidades são frustradas, mas deve ser pessoal se o executado for sabido. É permitida a expedição de ofícios aos órgãos públicos com multa equivalente a 5 vezes o salário-mínimo.

### Conceitos
- **Citação por Edital**: procedimento de notificação do executado
- **Execução Fiscal**: processo que visa cobrar dívidas fiscais
- **Ampla Defesa e Contraditório**: direito do executado ser ouvido antes da decisão final
- **Ofícios aos Órgãos Públicos**: procedimento para obter informações sobre o endereço do demandado

### Referências legais
- Art. 484 do Código de Processo Civil
- Súmula 414 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Citação por Edital na Execução Fiscal

### Dicas de prova
- Pegar a diferença entre citação pessoal e edital
- Entender o papel da ampla defesa e do contraditório no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.176 (2)", "page_number": 176, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 484 do Código de Processo Civil", "Súmula 414 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Citação por Edital na Execução Fiscal"], "confidence": 0.8, "extracted_at": "2026-05-27T20:40:42.223559+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=176", "doc_key": "deb188df994a9c5fa1b07ebea633aef9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ce9746d1b78789230ca0206fd120fe8f1ef8395ec473d6593c879e7f4b5599e0'),
  ('cpiuris2025::459f8a5eb93c25937dc13b58ebbfcd7e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação por Edital', '## Citação por Edital

A citação por edital deve ser feita por meio da publicação do edital na rede mundial de computadores, no sítio do tribunal e na plataforma do Conselho Nacional de Justiça. O prazo dos editais varia entre 20 e 60 dias.

### Conceitos
- **Citação por Edital**: Procedimento pelo qual o oficial busca o réu pessoalmente
- **Prazo dos Editais**: Varia entre 20 e 60 dias
- **Citação Ficta**: Ocorre quando o réu não é encontrado após a citação por edital
- **Revelia**: Não ocorre quando o réu não se apresenta após a citação ficta

### Referências legais
- Art. 234 do Código de Processo Civil

### Jurisprudência
- STJ. 4ª Turma. REsp 2.152.938-DF
- STJ. 3ª Turma. REsp 1.971.968-DF
- STJ. 3ª Turma. REsp 2.145.294-SC

### Dicas de prova
- Diferenciar entre citação por edital e citação ficta
- Entender o prazo dos editais e suas implicações
- Conhecer as exceções à citação por edital, como a hora certa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.177 (1)", "page_number": 177, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 234 do Código de Processo Civil"], "jurisprudence": ["STJ. 4ª Turma. REsp 2.152.938-DF", "STJ. 3ª Turma. REsp 1.971.968-DF", "STJ. 3ª Turma. REsp 2.145.294-SC"], "confidence": 0.8, "extracted_at": "2026-05-27T20:41:28.283532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=177", "doc_key": "459f8a5eb93c25937dc13b58ebbfcd7e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ad0b05fdf6266379a920d814a5fe75b2d3f537f0a1c6a3ffeacb42484345f051'),
  ('cpiuris2025::0563c23641e0de38b03d606e48c91764', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação e Serviço do Mandado de Segurança', '## Citação e Serviço do Mandado de Segurança

A citação deve ser feita com a presença do oficial, anotando os dias e horários. Se citada por hora certa, o servidor deve enviar uma carta registrada ao citando.

### Conceitos
- **Citação**: Ato pelo qual a parte é notificada de que precisa comparecer à justiça
- **Serviço do Mandado de Segurança**: O oficial de justiça entrega o mandado ao demandado
- **Prazo para apresentação de resposta**: O primeiro dia útil seguinte à juntada do mandado cumprido pelo oficial de justiça
- **Citação ficta**: Situacao em que o demandado não apresentou resposta após ser citado por hora certa

### Referências legais
- Art. 240 do Código de Processo Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Serviço do Mandado de Segurança

### Dicas de prova
- Pergunte sobre a presença do oficial em relação ao mandado
- Entenda o prazo para apresentação de resposta após a juntada do mandado cumprido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.177 (2)", "page_number": 177, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 240 do Código de Processo Civil", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Serviço do Mandado de Segurança"], "confidence": 0.8, "extracted_at": "2026-05-27T20:41:56.751935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=177", "doc_key": "0563c23641e0de38b03d606e48c91764"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4f49680b90fa0747360e83d06f794b22d441f018fb7ea3e82f951a0372640a11'),
  ('cpiuris2025::4bbe280571e8f8146584e7c779e34f45', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeitos da Citação', '## Efeitos da Citação

A citação pode gerar efeitos processuais (litispendência) e materiais (tornar a coisa litigiosa, constituir o devedor em mora e interromper a prescrição), mesmo em juízos incompetentes.

### Conceitos
- **Litispendência**: Impossibilidade de coexistir processos com as mesmas partes, objeto e causa de pedir
- **Citação válida**: Produce a interrupção da prescrição e estabilização subjetiva da demanda
- **Falta de citação**: O caso em que o sujeito não foi citado
- **Nulidade da citação**: O caso em que o sujeito foi citado, mas o ato não foi válido

### Referências legais
- Art. 397 do CC
- Art. 398 do CC

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre falta de citação e nulidade da citação
- Efeitos da citação em processos com as mesmas partes, objeto e causa de pedir', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 397 do CC", "Art. 398 do CC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T20:42:28.727665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=178", "doc_key": "4bbe280571e8f8146584e7c779e34f45"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'da6148101673bafcf150290d69fc8f8cd4bff02fc64857316ce53dadaab6850c'),
  ('cpiuris2025::b515ea2e132486394f2dec8ebeac44da', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intimação no processo', '## Intimação no processo

A intimação é o ato pelo qual se dá ciência a alguém dos atos e termos do processo para que faça ou deixe de fazer alguma coisa.

### Conceitos
- **Intimação**: Ato pelo qual se dá ciência a alguém dos atos e termos do processo
- **Notificação**: Ciência de um ato que irá ocorrer

### Referências legais
- Art. 269 do CPC

### Dicas de prova
- Diferenciação entre intimação e notificação
- Objeto da intimação (atos e termos do processo)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 269 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:42:56.282748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=178", "doc_key": "b515ea2e132486394f2dec8ebeac44da"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '92d5335745ec4cdad47d669c7474f75975f58ef9398f66a245a84dc33707b5fa'),
  ('cpiuris2025::9c24b119f4401d4fb311508f66d9b144', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intimação Eletrônica', '## Intimação Eletrônica

A intimação eletrônica é considerada comunicação pessoal para todos os efeitos legais e dispensa outras formas de intimação em processos civis, penais e trabalhistas.

### Conceitos
- **Comunicação Pessoal**: Intimização realizada pela Justiça por meio eletrônico
- **Diário Eletrônico**: Meio de intimação eletrônica utilizado por Tribunais
- **Portal Eletrônico de Intimação**: Meio de intimação eletrônico utilizado pela Justiça
- **Intimação Pessoal**: Intimização realizada na presença das partes e dos respectivos advogados

### Referências legais
- Art. 272, § 1º, do CPC; Art. 183 e 269, § 3º, do CPC

### Jurisprudência
- RE 123456; Informativo n. 697, STJ

### Dicas de prova
- Diferenciar entre intimação eletrônica e comunicação pessoal
- Entender a importância da intimação pessoal na presença das partes e dos advogados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.179 (1)", "page_number": 179, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 272, § 1º, do CPC; Art. 183 e 269, § 3º, do CPC"], "jurisprudence": ["RE 123456; Informativo n. 697, STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T20:43:27.673633+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=179", "doc_key": "9c24b119f4401d4fb311508f66d9b144"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6a8bc855faf16a212a1d98bb636b36cf9e39e1d45cf4ccd76bf4b66c1fa78e30'),
  ('cpiuris2025::c67424395ff5cd1bb205dc2091d8123a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prerrogativa de intimação pessoal e formas de intimação', '## Prerrogativa de intimação pessoal e formas de intimação

A prerrogativa de intimação pessoal da Defensoria Pública se aplica a faculdades de Direito, sendo válida a intimação em nome de um advogado constituído nos autos, mesmo com reserva de poderes e sem pedido exclusivo.

### Conceitos
- **Prerrogativa de intimação pessoal**: direito da Defensoria Pública à intimação pessoal
- **Intimação eletrônica**: intimação realizada por meio de sistema eletrônico
- **Substabelecimento**: substituição do advogado constituido nos autos

### Referências legais
- Art. 85, § 3º, da Lei nº 9.514/1997
- ...

### Jurisprudência
- REsp 2.018.319-RJ
- STJ. 4ª Turma. REsp 1.829.747/AM
- AgInt no REsp 1.859.127/SC

### Dicas de prova
- Entenda a diferença entre intimação pessoal e eletrônica.
- Conheça o conceito de substabelecimento e sua aplicação na prática jurídica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.179 (2)", "page_number": 179, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 85, § 3º, da Lei nº 9.514/1997", "..."], "jurisprudence": ["REsp 2.018.319-RJ", "STJ. 4ª Turma. REsp 1.829.747/AM", "AgInt no REsp 1.859.127/SC"], "confidence": 0.8, "extracted_at": "2026-05-27T20:43:57.182179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=179", "doc_key": "c67424395ff5cd1bb205dc2091d8123a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9520bfd3c0ee74795c9d4d6ee82cd3f5dd5462494c1ee694e2bea66a45375080'),
  ('cpiuris2025::287315d64aac1aa14600075a8292843e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intimação e Comunicação em Processo', '## Intimação e Comunicação em Processo

A intimação é válida mesmo quando realizada em nome de advogado constituído nos autos, desde que os poderes a ele outorgados tenham sido substabelecidos com reserva. Além disso, a extensão da prerrogativa conferida à Defensoria Pública para requerer intimação pessoal é admissível em determinadas hipóteses.

### Conceitos
- **Prerrogativa de Intimação**: Direito do juiz ou da parte ser intimado pessoalmente sobre um ato processual
- **Intimação**: Ato pelo qual o juiz ou a parte é notificado sobre um ato processual
- **Carta Precedente**: Meio de comunicação de atos processuais que se estabelece entre os órgãos do Judiciário

### Referências legais
- Art. 183 do CPC
- Art. 1.050 do CPC
- Art. 186, §2º do CPC

### Jurisprudência
- STJ. 4ª Turma. AgInt no AREsp 2.098.573-GO
- STJ. 1ª Seção. AR 6.503-CE
- STJ. 3ª Turma. RMS 64.894-SP

### Dicas de prova
- Distinção entre intimação pessoal e intimação em nome de advogado
- Requisitos para a extensão da prerrogativa conferida à Defensoria Pública
- Diferenças entre as diferentes espécies de cartas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.180 (1)", "page_number": 180, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 183 do CPC", "Art. 1.050 do CPC", "Art. 186, §2º do CPC"], "jurisprudence": ["STJ. 4ª Turma. AgInt no AREsp 2.098.573-GO", "STJ. 1ª Seção. AR 6.503-CE", "STJ. 3ª Turma. RMS 64.894-SP"], "confidence": 0.8, "extracted_at": "2026-05-27T20:44:48.059004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=180", "doc_key": "287315d64aac1aa14600075a8292843e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '96e5d42783a7a25e9b18a3041c9c8c16d07c16337bd5dec6ac3550429b117636'),
  ('cpiuris2025::b253933ea6e632e5a590724fbe1fd6db', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sobrestamento do processo em decorrência de carta precatória', '## Sobrestamento do processo em decorrência de carta precatória

O juízo deprecante não pode julgar a causa sem o retorno da carta precatória, especialmente se for imprescindível para a resolução do mérito. O sobrestamento é permitido até 1 ano.

### Conceitos
- **Carta Prepectória**: Instrumento que autoriza o juízo deprecante a prover uma questão específica
- **Sobrestamento do processo**: Prorrogação do prazo do processo até a devolução da carta precatória
- **Competência**: A competência é do juízo deprecante, mas não o impede de decidir questões específicas

### Referências legais
- Art. 182 do Código de Processo Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre a competência e a decisão da causa
- Entender o papel da carta precatória no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.180 (2)", "page_number": 180, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 182 do Código de Processo Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:45:12.154780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=180", "doc_key": "b253933ea6e632e5a590724fbe1fd6db"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0be94ee350bb90f8c8a4c830b5a1ec623fc71fa1f1b8e94f1d07654d02bef9b9'),
  ('cpiuris2025::f7a7d7054015621b06e98fdb9704c90b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Carta Rogatória e Cooperação Internacional', '## Carta Rogatória e Cooperação Internacional

A carta rogatória é um pedido de cooperação jurídica internacional para que órgão jurisdicional estrangeiro pratique determinado ato processual. O auxílio direto ocorre quando o pedido não tem por objeto uma decisão judicial estrangeira sujeita a juízo de delibação brasileira.

### Conceitos
- **Carta Rogatória**: Pedido de cooperação jurídica internacional para que órgão jurisdicional estrangeiro pratique determinado ato processual
- **Auxílio Direto**: Ocorre quando o pedido de cooperação não tem por objeto uma decisão judicial estrangeira sujeita a juízo de delibação brasileira

### Referências legais
- Art. 27 do CPC

### Dicas de prova
- Entenda a diferença entre auxílio direto e carta rogatória
- Conheça as medidas que podem ser objeto de cooperação jurídica internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.181", "page_number": 181, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 27 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:45:40.351910+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=181", "doc_key": "f7a7d7054015621b06e98fdb9704c90b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b0ca1810b5d5f7c59153a7f38136b0de8572b6d90da7cb2280437e8cb3bc6943'),
  ('cpiuris2025::e7321bb74c209b19b6fcfdd6f6c2028c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Auxílio Direto e Carta Rogatória', '## Auxílio Direto e Carta Rogatória

O auxílio direto é uma medida processual que pode ser solicitada pelo Estado requerente para obter informações ou provas, desde que não esteja proibida pela lei brasileira. A carta rogatória, por outro lado, é um procedimento de jurisdição contenciosa que deve assegurar às partes as garantias do devido processo legal.

### Conceitos
- **Auxílio Direto**: Medida processual que permite ao Estado requerente obter informações ou provas em um país estrangeiro
- **Carta Rogatória**: Procedimento de jurisdição contenciosa que deve assegurar às partes as garantias do devido processo legal
- **Exequatur**: Julgamento que decide se um pronunciamento judicial estrangeiro produz efeitos no Brasil

### Referências legais
- Art. 29 do CPC
- Art. 30 do CPC
- Art. 334 do CPC

### Dicas de prova
- Entenda a diferença entre auxílio direto e carta rogatória
- Conheça os requisitos para o exequatur de uma carta rogatória
- Avalie as garantias do devido processo legal em procedimentos contenciosos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 29 do CPC", "Art. 30 do CPC", "Art. 334 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:46:24.956725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=182", "doc_key": "e7321bb74c209b19b6fcfdd6f6c2028c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ee73bf9ed6cc3650335d39864bac14331252222eade45a77ee56335a93df834f'),
  ('cpiuris2025::d720eab7b3ec4dbfc4cb13439b437ea6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiências de Conciliação e Mediação', '## Audiências de Conciliação e Mediação

O CPC estabelece a criação de centros judiciários para solução de conflitos, onde ocorrem audiências de conciliação e mediação.

### Conceitos
- **Conciliação**: Procedimento em que um terceiro conduz o diálogo entre as partes envolvidas
- **Mediação**: Procedimento em que um terceiro aparta o diálogo entre as partes envolvidas, sem conduzi-lo
- **Audiência de Conciliação**: Reunião formal onde as partes discutem suas demandas com a presença de um terceiro
- **Audiência de Mediação**: Reunião informal onde as partes discutem suas demandas com a presença de um terceiro, que apenas aparta o diálogo

### Referências legais
- Art. 165 do CPC

### Dicas de prova
- Diferenciar conciliação e mediação
- Entender a presença de um terceiro em ambas as audiências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.182 (2)", "page_number": 182, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 165 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:46:49.216622+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=182", "doc_key": "d720eab7b3ec4dbfc4cb13439b437ea6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c2c634b7a5f55fdd0b432362f356ae14b36dc44e7d93996535441aee54f318b3'),
  ('cpiuris2025::0102abd7e5266c22f5e33160c25e47bc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimento da Audiência de Conciliação e Mediação', '## Procedimento da Audiência de Conciliação e Mediação

Regra sobre a realização da audiência de conciliação e mediação, incluindo o desinteresse das partes e hipóteses de dispensa.

### Conceitos
- **Audiência de Conciliação e Mediação**: Procedimento em que as partes tentam resolver o conflito de forma consensual
- **Desinteresse das Partes**: Manifestação expressa de desinteresse por parte das partes, que impede a realização da audiência
- **Hipóteses de Dispensa**: Situações em que o direito material não admite autocomposição e, portanto, a audiência é dispensada

### Referências legais
- Art. 166 do CPC
- Art. 174 do CPC
- Art. 334 do CPC

### Dicas de prova
- Entenda a importância da manifestação de desinteresse das partes para evitar a realização da audiência.
- Conheça as hipóteses em que a audiência é dispensada, como o direito material que não admite autocomposição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 166 do CPC", "Art. 174 do CPC", "Art. 334 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:47:20.895029+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=183", "doc_key": "0102abd7e5266c22f5e33160c25e47bc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f246818939f5844afdf00085b3232e588039cb298b0390a8b32db5c684c91c7c'),
  ('cpiuris2025::760180adafff31db72e1f4ec2b223c16', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Atos atentatórios à dignidade da justiça e multas', '## Atos atentatórios à dignidade da justiça e multas

O não comparecimento pessoal a audiência de conciliação pode ser considerado ato atentatório à dignidade da justiça, passível de sanção processual. A multa é representada por 2% do valor da causa ou vantagem econômica pretendida.

### Conceitos
- **Atos atentatórios à dignidade da justiça**: Comportamento que prejudicar a integridade do processo
- **Multa processual**: Sanção imposta por não cumprir com determinadas obrigações processuais

### Referências legais
- Art. 334, § 8º, do CPC/2015

### Jurisprudência
- STJ. 1ª Turma. REsp 1.769.949-SP
- STJ. 4ª Turma. AgInt no RMS 56422-MS - Info 700 STJ

### Dicas de prova
- Distinção entre ato atentatório e não comparecimento pessoal à audiência de conciliação
- Importância da procuração específica para transigir em nome da parte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 334, § 8º, do CPC/2015"], "jurisprudence": ["STJ. 1ª Turma. REsp 1.769.949-SP", "STJ. 4ª Turma. AgInt no RMS 56422-MS - Info 700 STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T20:47:58.397513+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=183", "doc_key": "760180adafff31db72e1f4ec2b223c16"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '01cbd4e04406eda5541fc47a7ca244d2db54e72cd7fa68fb7ca5ebaaf851c087'),
  ('cpiuris2025::246971a2d9913ba5deaee83300f3add3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de Conciliação e Revelia', '## Audiência de Conciliação e Revelia

O artigo 334 do CPC estabelece que a parte pode constituir representante para negociar e transigir, com presença de advogados ou defensores públicos. A audiência de conciliação não é impedida pela presença do ente público em juízo. Se a solução for consensual, o processo será encaminhado ao juiz para prolatar sentença definitiva. Caso não haja composição, o demandado tem 15 dias para apresentar resposta. A revelia é considerada quando o demandado não apresenta resposta ou responde intempestivamente.

### Conceitos
- **Audiência de Conciliação**: Ato processual em que as partes tentam chegar a um acordo
- **Revelia**: Ausência jurídica de resposta na forma e tempo devidos
- **Procuração**: Documento que autoriza uma pessoa a agir em nome de outra
- **Advogado**: Pessoa qualificada para representar um cliente em um processo
- **Defensor Público**: Pessoa designada pelo Estado para defender um cliente em um processo

### Referências legais
- Art. 334 do CPC

### Dicas de prova
- Entenda a importância da audiência de conciliação e como ela pode afetar o processo.
- Conheça as consequências da revelia e como elas podem afetar o demandado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.184", "page_number": 184, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 334 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:48:35.588875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=184", "doc_key": "246971a2d9913ba5deaee83300f3add3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '87d2cd6a4b2d0cd9fcda1526d5bcbf6701110f6f9e9853ce9df16d694abbf868'),
  ('cpiuris2025::0f1ab1c9a141908d804be00163c8598a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeito Material da Revelia', '## Efeito Material da Revelia

O efeito material da revelia não se aplica quando há pluralidade de réus, litígio sobre direitos indisponíveis ou petição inicial sem instrumento de prova necessário.

### Conceitos
- **Pluralidade de Réus**: Ocorre quando há mais de um réu na ação
- **Direitos Indisponíveis**: Direitos que não podem ser alienados ou transferidos
- **Instrumento de Prova Necessário**: Objeto necessário à prova do ato, de acordo com a lei
- **Revelia**: Ocorre quando o réu não se faz representar nos autos

### Referências legais
- Art. 345 do CPC
- Art. 341 do CPC
- Art. 346 do CPC

### Jurisprudência
- STJ. 1ª Turma. REsp 2.106.717-PR
- Súmula N da STF

### Dicas de prova
- Distinção entre pluralidade de réus e litígio sobre direitos indisponíveis
- Importância do instrumento de prova necessário na revelia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.185 (1)", "page_number": 185, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 345 do CPC", "Art. 341 do CPC", "Art. 346 do CPC"], "jurisprudence": ["STJ. 1ª Turma. REsp 2.106.717-PR", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-27T20:49:07.673923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=185", "doc_key": "0f1ab1c9a141908d804be00163c8598a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ccfd370905c8c215c533c87e2b53553408b3f19b4e331424ee1d655d92ebc36f'),
  ('cpiuris2025::3d647852f92d5902a7fd4dd4b05968de', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Revelia e contumácia no processo', '## Revelia e contumácia no processo

A revelia não afeta a veracidade dos danos narrados na petição inicial, mas não define o quantum indenizatório. A contumácia é inércia de qualquer das partes que deveria atuar em algum momento procedimental.

### Conceitos
- **Revelia**: Omissão da defesa por uma das partes
- **Contumácia**: Inércia de qualquer das partes que deveria atuar em algum momento procedimental
- **Patrono**: Advogado designado pela parte para exercer atividade no processo
- **Impugnação**: Reclamação feita por uma das partes sobre a procedência de ato do juiz

### Referências legais
- Art. 346 da Lei nº X
- Parágrafo único do mesmo artigo

### Jurisprudência
- Informativo n. 574, STJ

### Dicas de prova
- Diferenciar revelia e contumácia
- Entender a diferença entre o quantum indenizatório e a veracidade dos danos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.185 (2)", "page_number": 185, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 346 da Lei nº X", "Parágrafo único do mesmo artigo"], "jurisprudence": ["Informativo n. 574, STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T20:49:44.501505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=185", "doc_key": "3d647852f92d5902a7fd4dd4b05968de"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4450e48369b6deefacce39a325a04b39074ff06195a5e735335d4f0527959a5b'),
  ('cpiuris2025::d16ca2291747feafc961fa714590019c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Revelia e Impugnação Específica', '## Revelia e Impugnação Específica

A revelia é uma espécie de contumácia do demandado que não apresenta sua contestação ou a faz de forma intempestiva. O ônus da impugnação específica recai sobre o dever de rebater todos os fatos afirmados pelo demandante.

### Conceitos
- **Revelia**: inércia do demandado que não apresenta sua contestação ou a faz de forma intempestiva
- **Impugnação Específica**: dever de rebater todos os fatos afirmados pelo demandante
- **Omnibus**: não se aplica ao advogado dativo, curador especial e ao defensor público

### Referências legais
- Art. 329 do Código de Processo Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre revelia e impugnação específica
- Prazo para apresentação da contestação
- Exceções à revelia (Fazenda Pública, embargos à execução)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.186 (1)", "page_number": 186, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 329 do Código de Processo Civil", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:50:16.444838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=186", "doc_key": "d16ca2291747feafc961fa714590019c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8228f29baa04197a37c0ff7b3cd646e459d061d2bea0689bf16b849b1a0a228b'),
  ('cpiuris2025::ba78afed6ecb58bf9a98ac2613df54d7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazos para Contestação e Resposta em Processo', '## Prazos para Contestação e Resposta em Processo

O prazo para apresentação da contestação de cada um terá início na data do respectivo protocolo da petição, com contagem do prazo conforme o art. 231 do CPC, salvo disposição em sentido diverso.

### Conceitos
- **Contestação**: Reclamação feita por uma das partes contra a decisão inicial do juiz
- **Prazo para apresentação da contestação**: Período durante o qual as partes podem se manifestar sobre a decisão inicial do juiz
- **Art. 231 do CPC**: Regra que estabelece como contagem do prazo será realizada, salvo disposição em sentido diverso

### Referências legais
- Art. 231 do CPC

### Dicas de prova
- Pegar a data do protocolo da petição para iniciar o prazo
- Atentar para o inciso IX da Lei nº 14.195/2021', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.186 (2)", "page_number": 186, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 231 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:50:39.254732+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=186", "doc_key": "ba78afed6ecb58bf9a98ac2613df54d7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3aeb21bdb97e077a082df81d74e21ea742698bd5b8b8327ab1fa699e84f8a710'),
  ('cpiuris2025::794feaf1ba2a62f9dcd6a71eab85787a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazo para apresentação de resposta e contestação', '## Prazo para apresentação de resposta e contestação

O prazo para apresentação de resposta e contestação é determinado pela mensagem de citação, recebimento da citação eletrônica ou última juntada do mandado de citação. Em casos de desistência de litisconsórcio, o prazo começa na data da intimação da decisão que homologa a desistência.

### Conceitos
- **Prazo para apresentação de resposta e contestação**: O prazo para apresentar resposta e contestação é determinado pela citação
- **Citação eletrônica**: A citação realizada por meio eletrônico
- **Litisconsórcio**: O estado em que mais de uma pessoa é citada no processo
- **Desistência de litisconsórcio**: A ação de um dos litigantes desistir do processo

### Referências legais
- Art. 335, § 2º, CPC
- Art. 306, CPC

### Dicas de prova
- Entenda a diferença entre prazo para apresentação de resposta e contestação
- Conheça as regras sobre citação eletrônica e litisconsórcio
- Aprenda a distinguir entre desistência de litisconsórcio e outros motivos que podem afetar o prazo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.187 (1)", "page_number": 187, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 335, § 2º, CPC", "Art. 306, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:51:26.555679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=187", "doc_key": "794feaf1ba2a62f9dcd6a71eab85787a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c83a26e10d81b7e4c8787ef28448927d694751ae34b5e0fa01d5eea2f5732956'),
  ('cpiuris2025::1512171104669acfff62e9e9d2cec28d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Questões Prejudiciais e Homogêneas/Heterogêneas', '## Questões Prejudiciais e Homogêneas/Heterogêneas

A questão prejudicial é uma medida processual que permite ao juiz analisar questões de direito antes da resolução do mérito da causa. Pode ocorrer em processo homogêneo (no mesmo processo) ou heterogêneo (em processo distinto). A questão prejudicial homogênea é analisada nos próprios autos, enquanto a heterogênea é analisada em outro processo.

### Conceitos
- **Questão Prejudicial**: Medida processual que permite ao juiz analisar questões de direito antes da resolução do mérito da causa.
- **Homogênea**: Ocorre em processo no mesmo processo
- **Heterogênea**: Ocorre em processo distinto

### Referências legais
- Art. 522 Código de Processo Civil
- Súmula 242 STF

### Jurisprudência
- RE 123456
- Questões prejudiciais e homogêneas/heterogêneas

### Dicas de prova
- Entenda a diferença entre questão prejudicial homogênea e heterogênea.
- Conheça as regras para a análise de questões prejudiciais nos próprios autos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.187 (2)", "page_number": 187, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522 Código de Processo Civil", "Súmula 242 STF"], "jurisprudence": ["RE 123456", "Questões prejudiciais e homogêneas/heterogêneas"], "confidence": 0.8, "extracted_at": "2026-05-27T20:51:56.920217+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=187", "doc_key": "1512171104669acfff62e9e9d2cec28d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e1015081702ecd95f18b44168747c99587d616b5bec0c3c30ed3f5a40b96bce1'),
  ('cpiuris2025::1529f8a3101ebae1ebe6a584324a29d1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio da eventualidade e Ônus da impugnação específica dos fatos', '## Princípio da eventualidade e Ônus da impugnação específica dos fatos

O princípio da eventualidade determina que o réu deve alegar todas as matérias de defesa na contestação, com exceções para questões de ordem pública, direitos supervenientes e autorização legal. O ônus da impugnação específica dos fatos é a responsabilidade do réu de rebater todos os fatos narrados na petição inicial, exceto em casos específicos.

### Conceitos
- **Princípio da eventualidade**: Regra que determina que o réu deve alegar todas as matérias de defesa na contestação
- **Ônus da impugnação específica dos fatos**: Responsabilidade do réu de rebater todos os fatos narrados na petição inicial
- **Exceções ao ônus da impugnação específica dos fatos**: Matérias de ordem pública, direitos supervenientes e autorização legal

### Referências legais
- Art. 336 do CPC
- Art. 341 do CPC

### Jurisprudência
- REsp 1.857.194-MT
- STJ. 4ª Turma

### Dicas de prova
- Distinção entre alegação de defesa e impugnação específica dos fatos
- Conhecimento do juiz de ofício em questões de ordem pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.188 (1)", "page_number": 188, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 336 do CPC", "Art. 341 do CPC"], "jurisprudence": ["REsp 1.857.194-MT", "STJ. 4ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-27T20:52:34.253183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=188", "doc_key": "1529f8a3101ebae1ebe6a584324a29d1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bb37a96160bc1f639222dc658ffceeb47e4f125df1dac3b73b18bb192b84ac64'),
  ('cpiuris2025::9af040c864e0af4a152a0e026ac8dd59', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconvenção', '## Reconvenção

A reconvenção é uma ação autônoma do réu contra o autor, com natureza jurídica de ação, que pleita um bem da vida e altera a posição passiva do réu.

### Conceitos
- **Reconvenção**: ação autônoma do réu contra o autor
- **Ação autônoma**: ação que não depende da demanda principal
- **Bem da vida**: objeto de pretensão do réu

### Referências legais
- Art. 343, § 2º, do CPC

### Dicas de prova
- Distinção entre ação principal e reconvenção
- Natureza jurídica da reconvenção como ação autônoma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.188 (2)", "page_number": 188, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 343, § 2º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:53:03.837231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=188", "doc_key": "9af040c864e0af4a152a0e026ac8dd59"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '09664f49cbcecd3fee51c7bb21e6542b0c6f8dc30b70b4092a656ddacbe50f3b'),
  ('cpiuris2025::52d0bbe70f04e70ce78b31f3df70c990', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconvenção e Ações Dúplicas', '## Reconvenção e Ações Dúplicas

A reconvenção é uma ação independente que pode ser apresentada mesmo após o desistimento do pedido inicial, mas não é acessória. Pode trazer novos fatos conexos à petição inicial ou contestação. As ações dúplicas são ações em que se o pedido for julgado improcedente, há um benefício para o réu.

### Conceitos
- **Reconvenção**: Ação independente que pode ser apresentada mesmo após o desistimento do pedido inicial
- **Ações Dúplicas**: Ações em que se o pedido for julgado improcedente, há um benefício para o réu
- **Pedido Contraposto**: Forma de exercício do direito de ação, mas com base nos mesmos fatos da petição inicial ou contestação

### Referências legais
- Art. 31 da Lei nº 9.099/1995

### Jurisprudência
- STJ. 3ª Turma. REsp 2.046.666-SP
- Súmula 702 do STJ

### Dicas de prova
- Distinção entre reconvenção e pedido contraposto
- Conexão entre alegações da petição inicial, contestação e reconvenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.189 (1)", "page_number": 189, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 31 da Lei nº 9.099/1995"], "jurisprudence": ["STJ. 3ª Turma. REsp 2.046.666-SP", "Súmula 702 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T20:53:37.338502+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=189", "doc_key": "52d0bbe70f04e70ce78b31f3df70c990"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5eca5c3f0c51264e1bfc6a77df05186b8ba91c63da5bc4f2e9af7f04382e59ab'),
  ('cpiuris2025::2f28e548c0dd43a999827858d906c732', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconvenção e Processos de Conhecimento', '## Reconvenção e Processos de Conhecimento

A reconvenção não impede o regular processamento da pretensão do réu contra o autor, desde que bem delimitada na contestação. A reconvenção é cabível em processos de conhecimento que observam o procedimento comum.

### Conceitos
- **Reconvenção**: instrumento utilizado apenas em processo de conhecimento
- **Procedimento comum**: procedimento adotado em processos de conhecimento
- **Rito comum**: procedimento que não é especializado

### Referências legais
- Art. 700, § 6º, do CPC

### Jurisprudência
- Súmula 292 do STJ

### Dicas de prova
- Entenda a diferença entre reconvenção e recurso de sentença.
- Conheça as hipóteses em que é cabível a reconvenção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.189 (2)", "page_number": 189, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 700, § 6º, do CPC"], "jurisprudence": ["Súmula 292 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T20:53:59.070509+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=189", "doc_key": "2f28e548c0dd43a999827858d906c732"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '90a4115710e8bcc5e4b70cdb5222132f36baf9acf138d65edc8e8d2e93183001'),
  ('cpiuris2025::0fa2bd7372474bb541869c02c8da0d5a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconvenção', '## Reconvenção

A reconvenção é um procedimento especial que admite conversão em procedimento comum. Pode ser apresentada pelo demandado originário, com legitimidade passiva para a reconvenção sendo do autor da demanda originária e legitimidade ativa do réu da ação originária.

### Conceitos
- **Legitimidade**: Direito de uma parte apresentar ação ou recurso em um processo
- **Reconvenção**: Procedimento especial que admite conversão em procedimento comum
- **Legitimidade Passiva**: Direito de uma parte ser processada em um processo
- **Legitimidade Ativa**: Direito de uma parte apresentar ação ou recurso em um processo

### Referências legais
- Art. 343, §3º do CPC
- Súmula 613/STJ

### Jurisprudência
- RE 123456
- Informativo n. 613/STJ
- Informativo n. 775/STJ

### Dicas de prova
- Diferenciar entre legitimidade passiva e legitimidade ativa
- Entender a autonomia e independência da reconvenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 343, §3º do CPC", "Súmula 613/STJ"], "jurisprudence": ["RE 123456", "Informativo n. 613/STJ", "Informativo n. 775/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T20:54:42.035812+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=190", "doc_key": "0fa2bd7372474bb541869c02c8da0d5a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '418d3bc1f875a74ec42dc298476982789829f0f782941ecefdb523ea29d9370e'),
  ('cpiuris2025::0b3dcfd97cf74334ea2ca348364fd30b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconvenção e Substituição Processual', '## Reconvenção e Substituição Processual

A reconvenção pode ser feita contra o substituído, não contra o substituto. O reconvinte deve afirmar ser titular de direito em face do substituído.

### Conceitos
- **Reconvenção**: ação processual que visa impugnar a pretensão principal da petição inicial
- **Substituição Processual**: substituição do autor ou réu pelo outro, em relação à mesma causa de ação

### Referências legais
- Art. 343, § 5º, do CPC

### Dicas de prova
- Diferença entre substituído e substituto processual
- Reconvenção: quando é feita e como é proposta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 343, § 5º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:55:01.591868+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=190", "doc_key": "0b3dcfd97cf74334ea2ca348364fd30b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a1a7b6d74159fcf938a3266a153b43c5e1d13b96d10bae85cf4956f289e34dce'),
  ('cpiuris2025::f7eb5c76782189037ddedca99316c434', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconvenção e Reconvencimento', '## Reconvenção e Reconvencimento

A reconvenção é uma ação que visa ao autor, além do pedido inicial, pedir o reconvenimento de um pedido feito pelo réu. A discussão é se a reconvenção da reconvenção é permitida ou não, com a opinião do STJ ser que ela não está vedada pelo sistema processual.

### Conceitos
- **Reconvenção**: Ação que visa ao autor, além do pedido inicial, pedir o reconvenimento de um pedido feito pelo réu.
- **Reconvencimento**: Pedidos feitos pelo réu contra o autor e terceiros
- **Procedimento Monitório**: Fase do processo em que o juiz verifica se é necessária a adoção de alguma providência preliminar.

### Referências legais
- Art. 702, § 6º, do CPC

### Jurisprudência
- Enunciado n. 680 do FPPC
- Enunciado n. 629 do FPPC

### Dicas de prova
- Distinção entre reconvenção e reconvencimento
- Fase procedimental da organizatória
- Procedimentos preliminares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.191 (1)", "page_number": 191, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 702, § 6º, do CPC"], "jurisprudence": ["Enunciado n. 680 do FPPC", "Enunciado n. 629 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-27T20:55:34.158355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=191", "doc_key": "f7eb5c76782189037ddedca99316c434"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '69f1bac79e0a610c6fbde8897921c37d6e761146ed43b4be0dda0b1a9424cc18'),
  ('cpiuris2025::6051f603efdb9cc513f1b98c474b3670', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimentos em Recursos e Contestações', '## Procedimentos em Recursos e Contestações

Descreve as providências a serem tomadas em casos de contestação do réu, incluindo alegações de fato impeditivo, modificativo ou extintivo do direito do autor, preliminares de mérito e verificações de vícios sanáveis.

### Conceitos
- **Contestação**: Ação apresentada pelo réu para contestar os fatos alegados pelo autor.
- **Alegação de fato impeditivo**: Alegação feita pelo réu para impedir o prosseguimento do processo.
- **Alegação de fato modificativo**: Alegação feita pelo réu para modificar os fatos alegados pelo autor.
- **Alegação de fato extintivo**: Alegação feita pelo réu para extinguir o direito do autor.
- **Preliminar de mérito**: Alegação feita pelo réu para questionar a procedência da ação do autor.
- **Vício sanável**: Erro ou irregularidade que pode ser corrigido com a intervenção da parte.

### Referências legais
- Art. 337 do CPC

### Dicas de prova
- Diferencie entre alegações de fato impeditivo, modificativo e extintivo.
- Entenda o conceito de preliminar de mérito e sua relação com a contestação.
- Conheça as regras para a correção de vícios sanáveis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.191 (2)", "page_number": 191, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 337 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:56:18.416420+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=191", "doc_key": "6051f603efdb9cc513f1b98c474b3670"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2c8a75bd89d22ebf1b0b2926794d1e5614069d21b629143ddfbbb3e5b9175420'),
  ('cpiuris2025::25f7e97918d14daadd45abe3edf017cf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Julgamento Conforme o Estado do Processo', '## Julgamento Conforme o Estado do Processo

O juiz analisa se é possível sentenciar o processo no estado em que se encontra, seguindo os arts. 485 e 487, incisos II e III, do CPC, para aplicar o princípio da economia processual.

### Conceitos
- **Economia Processual**: Princípio que busca simplificar o processo, evitando desnecessidades e reduzindo a duração do processo.
- **Julgamento Conforme o Estado do Processo**: Procedimento pelo qual o juiz analisa se é possível sentenciar o processo no estado em que se encontra.
- **Julgamento Antecipado do Mérito**: Procedimento que permite julgar procedente ou improcedente um pedido antes da citação do demandado.
- **Julgamento Parcial do Mérito**: Decisão interlocutória que decide parcialmente o mérito, quando há pedidos contrapostos e parcela incontroversa.
- **Revelia**: Omissão de testemunhas ou documentos por parte do réu, que pode ser produzido seu efeito material sem requerimento de prova.

### Referências legais
- Art. 485 do CPC
- Art. 487, incisos II e III do CPC

### Jurisprudência
- Enunciado 297 do FPPC

### Dicas de prova
- Diferenciar o julgamento conforme o estado do processo do julgamento antecipado do mérito.
- Entender a hipótese de revelia e sua produção como efeito material.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485 do CPC", "Art. 487, incisos II e III do CPC"], "jurisprudence": ["Enunciado 297 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-27T20:56:57.082149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=192", "doc_key": "25f7e97918d14daadd45abe3edf017cf"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd361d54a30b02348529136c4590e4817ca0adfb13682a008f24be249e0026d7b'),
  ('cpiuris2025::7fbc4d5487d4ee97a3c13583fb1bc35d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Decisões Interlocutórias e Causa Julgada Material', '## Decisões Interlocutórias e Causa Julgada Material

A decisão interlocutória de mérito, mesmo parcial, produz coisa julgada material e não pode ser modificada senão em decorrência do recurso que a impugna.

### Conceitos
- **Causa Julgada Material**: Conceito jurídico que se refere à decisão de um juiz que tem força de coisa julgada, mesmo que seja uma decisão interlocutória.
- **Decisão Interlocutória**: Decisão do juiz que não é final e que pode ser apelada.
- **Cognição Exauriente**: Método de julgamento que envolve a análise completa e detalhada dos fatos e da lei aplicável.
- **Recurso Interposto**: Ação apresentada por uma das partes para apelar uma decisão do juiz.
- **Modificação de Decisão**: Mudança feita em uma decisão anterior, geralmente com o objetivo de corrigir um erro ou ajustar a situação.

### Referências legais
- Art. 273 do CPC/2015
- Súmula 125 da Jornada de Direito Processual Civil do CJF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a coisa julgada material e sua produção em decisões interlocutórias.
- Entenda a diferença entre decisão interlocutória e decisão final.
- Conheça o conceito de cognição exauriente e como ela se aplica às decisões do juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.192 (2)", "page_number": 192, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do CPC/2015", "Súmula 125 da Jornada de Direito Processual Civil do CJF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:57:31.706034+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=192", "doc_key": "7fbc4d5487d4ee97a3c13583fb1bc35d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ecf0a206093078e987476143a3ef55c1c852c6043b40c8928e9f16a7c4d01106'),
  ('cpiuris2025::629c52be9d3069b1ad2c061c7bceb343', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Saneamento do processo', '## Saneamento do processo

O saneamento do processo envolve a resolução de questões pendentes, fixação de pontos controvertidos e definição da distribuição do ônus da prova.

### Conceitos
- **Fase postulatória**: Fase inicial do procedimento comum, na qual o Autor expõe sua causa de pedir
- **Fase ordinatória**: Segunda fase do procedimento comum, na qual são produzidas as provas
- **Audiência de saneamento compartilhado**: Momento em que o juiz e as partes deliberam sobre as especificidades do litígio coletivo
- **Saneamento consensual**: Proposta de saneamento feita pelas partes, que pode agregar questões de fato não deduzidas

### Referências legais
- Art. 273 do CPC/2015
- FPPC n. 298

### Jurisprudência
- RE 123456
- Tema repetitivo da prova recente (PGE/PA - 2023)

### Dicas de prova
- Entenda a diferença entre saneamento compartilhado e consensual
- Conheça as fases do procedimento comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.193 (1)", "page_number": 193, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do CPC/2015", "FPPC n. 298"], "jurisprudence": ["RE 123456", "Tema repetitivo da prova recente (PGE/PA - 2023)"], "confidence": 0.8, "extracted_at": "2026-05-27T20:58:16.321093+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=193", "doc_key": "629c52be9d3069b1ad2c061c7bceb343"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '530b847ea31b53891ad6d69465bcf58cf9b2f03cd84e30bd7f769886bb11f65d'),
  ('cpiuris2025::ea5f9e5f08145ed734254ea301a9bf92', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fases do procedimento', '## Fases do procedimento

As fases do procedimento são: instrutória, decisória e ordinária.

### Conceitos
- **fase do procedimento**: etapa do processo
- **instrutória**: fase de providências preliminares para julgamento
- **decisória**: fase da sentença proferida pelo juiz
- **ordinária**: fase na qual a contestação é peticionada antes das provas

### Referências legais
- Art. 319 do Código de Processo Civil

### Dicas de prova
- Distinguir entre as fases do procedimento
- Entender a importância da desistência na ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.193 (2)", "page_number": 193, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 319 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:58:34.649158+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=193", "doc_key": "ea5f9e5f08145ed734254ea301a9bf92"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '968f8314cb299a7350705050aa47c79456c37f344aca0c3eaa139b8c359deb4c'),
  ('cpiuris2025::dc18d57c2aeadd9cd8971e638d909aad', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo de Conhecimento e Fases do Processo', '## Processo de Conhecimento e Fases do Processo

O processo de conhecimento tem quatro fases: postulatória, saneamento, instrutória e decisória. A extinção do processo por abandono da causa pelo autor depende do requerimento do réu.

### Conceitos
- **Fase postulatória**: fase que começa com a petição inicial e termina com a apresentação da defesa do réu
- **Saneamento**: fase em que o juiz cumpre providências preliminares para encaminhar o feito à etapa de produção de provas
- **Instrutória**: fase de produção de provas
- **Decisória**: fase em que o juiz decide e proferir sentença
- **Abandono da causa**: conduzimento do autor a abandonar a ação
- **Extinção do processo**: fim do processo devido à ausência de uma das partes ou à falta de objeto do pleito

### Referências legais
- Art. 226, III
- Art. 366
- Art. 485, § 5º
- Art. 485, § 6º
- Art. 486

### Dicas de prova
- Entenda a estrutura do processo de conhecimento e as fases que o compõem
- Conheça as regras de abandono da causa e extinção do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.194", "page_number": 194, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 226, III", "Art. 366", "Art. 485, § 5º", "Art. 485, § 6º", "Art. 486"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:59:13.347647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=194", "doc_key": "dc18d57c2aeadd9cd8971e638d909aad"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '884cb339665d816242d612f1c75141a50b4b55865652a03f88b5da2595b1f5ed'),
  ('cpiuris2025::72f284a3e7840d7be18bb89cac23b07c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo de Conhecimento', '## Processo de Conhecimento

O juiz pode julgar liminarmente improcedente o pedido que contrariar súmula do STF, acórdão de STJ em recursos repetitivos ou entendimento firmado em incidente de resolução de demandas repetitivas.

### Conceitos
- **CPC**: Código de Processo Civil
- **Art. 332**: Disposição específica do CPC sobre a fase instrutória
- **Fase instrutória**: Fase do processo onde se analisam as provas e evidências
- **Súmula do STF**: Enunciado finalizado que estabelece regra jurídica
- **Acórdão de STJ**: Decisão final do Superior Tribunal de Justiça

### Referências legais
- Art. 332 do CPC

### Dicas de prova
- Entendimento firmado em incidente de resolução de demandas repetitivas é diferente de súmula.
- A citação do réu não é necessária para a fase instrutória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.195", "page_number": 195, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 332 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:59:49.701571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=195", "doc_key": "72f284a3e7840d7be18bb89cac23b07c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '94d4853138af04c72c1996ddcc61eaeee12a878a72be105789e3d5325af8d279'),
  ('cpiuris2025::cadb6dd37cf02d6711d52097e632a788', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prova em Processo', '## Prova em Processo

A prova é um elemento capaz de demonstrar a veracidade de fatos ou situações jurídicas que interessa à solução do litígio. Tem como finalidade influenciar a convicção do juiz e as partes envolvidas.

### Conceitos
- **Prova**: Elemento capaz de demonstrar a veracidade de fatos ou situações jurídicas
- **Princípio do Contraditório**: Garantia constitucional que inclui o direito de provar, conhecer, participar e influir
- **Prova Ilícita**: Prova produzida em violação ao ordenamento jurídico ou desconformidade com as normas constitucionais

### Referências legais
- Art. 369 do CPC
- Art. 5º, inciso LVI da CR

### Jurisprudência
- RE 123456
- Tema repetitivo sobre prova ilícita

### Dicas de prova
- Entenda a classificação das provas (típicas e atípicas, ilícitas, etc.)
- Conheça o princípio da atipicidade dos meios de prova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.197", "page_number": 197, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 369 do CPC", "Art. 5º, inciso LVI da CR"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre prova ilícita"], "confidence": 0.8, "extracted_at": "2026-05-27T21:00:21.327667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=197", "doc_key": "cadb6dd37cf02d6711d52097e632a788"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f6e856d8186adf0e2028fa7851f786e2eaa187900c495cb45b76e7e1b4b32618'),
  ('cpiuris2025::2720e4f5b2c629525f17b2095ae15384', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Provas Indiciárias e Indiretas', '## Provas Indiciárias e Indiretas

São provas não reguladas pelo CPC, obtidas por meio de indícios, que permitem ao juiz fazer um raciocínio indutivo para chegar à conclusão de que uma das partes está afirmando.

### Conceitos
- **Prova Indiciária**: Prova não regulada pelo CPC, obtida por meio de indícios
- **Prova Indireta**: Prova que não tem expressa previsão no CPC, mas permite ao juiz fazer um raciocínio indutivo
- **Contraditório**: O direito do contraditório deve ser observado tanto na origem quanto no destino de uma prova
- **Prova Emprestada**: Prova produzida em um processo que pode ser aproveitada em outro, desde que observado o contraditório
- **Prova Diabólica**: Prova impossível ou extremamente difícil de produzir, geralmente em casos de fatos negativos

### Referências legais
- Art. 372 do CPC
- Súmula 617.428/SP do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a distinção entre prova indicária e indireta
- Observar o contraditório tanto na origem quanto no destino de uma prova
- Entender que a prova emprestada pode ser aproveitada em outro processo, desde que observado o contraditório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.198", "page_number": 198, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 372 do CPC", "Súmula 617.428/SP do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:00:59.834007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=198", "doc_key": "2720e4f5b2c629525f17b2095ae15384"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1ab017f2d8b06bd2e8787d93d813bd6af8877984f3266b4026a367aa0d8c38b5'),
  ('cpiuris2025::c7e21695e425755bc72b3c32f9fdc2e5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Objeto da Prova e Valoração da Prova', '## Objeto da Prova e Valoração da Prova

O objeto da prova deve recair sobre os atos preparatórios ou fatos que indicam intenção de praticar um ilícito. A valoração da prova é feita por três sistemas: legal, íntima convicção e persuasão racional.

### Conceitos
- **Objeto da Prova**: O que deve ser provado em uma ação
- **Prova Inibitória**: Prova que visa impedir que alguém pratique um ilícito
- **Fatos Notórios**: Fatmos que não precisam ser provados, como feriados nacionais
- **Fatos Afirmados e Confessados**: Fatos que uma parte afirma e a outra confessa
- **Máximas de Experiência**: Regras gerais do direito aplicadas em falta de normas específicas

### Referências legais
- CPC - Art. 199

### Dicas de prova
- Entenda a diferença entre prova inibitória e prova exibitória
- Conheça as três formas de valoração da prova: legal, íntima convicção e persuasão racional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.199", "page_number": 199, "discipline": "Direito Processual Civil", "legal_refs": ["CPC - Art. 199"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:01:43.496237+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=199", "doc_key": "c7e21695e425755bc72b3c32f9fdc2e5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5f9d590003b32c144d89d7d939a101d66349952e16613849510f2f29dc1eb84a'),
  ('cpiuris2025::f7d74ca8f1c01e4899c933ee42105c6d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sistema da Persuasão Racional e Íntima Convicção', '## Sistema da Persuasão Racional e Íntima Convicção

O sistema adotado no Brasil é o da persuasão racional ou do livre convencimento motivado, onde o juiz aprecia a prova constante dos autos independentemente do sujeito que a produziu.

### Conceitos
- **Sistema da Persuasão Racional**: apreço da prova constante dos autos
- **Livre Convencimento Motivado**: juiz fundamenta sua decisão com razões claras e convincentes
- **Princípio da Comunhão das Provas**: prova não pertence à parte que a produziu, mas sim ao processo

### Referências legais
- Art. 371 do CPC
- Art. 406 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre persuasão racional e íntima convicção
- Princípio da comunhão das provas
- Inversão do ônus da prova vs. dispensa do ônus da prova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.200 (1)", "page_number": 200, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 371 do CPC", "Art. 406 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:02:13.479015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=200", "doc_key": "f7d74ca8f1c01e4899c933ee42105c6d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8ff4a49ff5cbf73a53c168923dece61e9977ccce0a2900e6bbdece3e43545495'),
  ('cpiuris2025::bfb4f033737730260d0fac9cc6b7fe9b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Inversão do ônus da prova', '## Inversão do ônus da prova

A inversão do ônus da prova é possível até o saneamento do processo, com base no contraditório e na ampla defesa, conforme o art. 373, § 2º, CPC.

### Conceitos
- **ônus da prova**: obrigação de provar algo
- **inversão do ônus da prova**: mudança da obrigação de provar algo de uma parte para outra
- **contraditório e ampla defesa**: direito à resposta e ao contraditório para a parte adversária
- **saneamento do processo**: atuação final do feito

### Referências legais
- Art. 373, § 2º, CPC

### Dicas de prova
- Entenda a diferença entre ônus da prova e inversão do ônus da prova.
- Conheça o artigo 373, § 2º, CPC para entender quando é possível a inversão do ônus da prova.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.200 (2)", "page_number": 200, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 373, § 2º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:02:37.060482+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=200", "doc_key": "bfb4f033737730260d0fac9cc6b7fe9b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '322201158732f3d68a50cac8345f684488034213ceab9b9ebae6d2487d033f9a'),
  ('cpiuris2025::b06019fa89cc9e46adc7defb5e1566b1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Produção Antecipada de Provas', '## Produção Antecipada de Provas

A produção antecipada de provas é a prova produzida antes do momento em que ela normalmente seria produzida. É uma ação probatória autônoma, com competência concorrente entre o juízo do foro onde a prova deve ser produzida ou do juízo do foro do domicílio do réu.

### Conceitos
- **Produção Antecipada de Provas**: Prova produzida antes do momento em que ela normalmente seria produzida
- **Competência Concorrente**: A competência para produção antecipada de provas é concorrente, sendo geralmente do juízo do foro onde a prova deve ser produzida ou do juízo do foro do domicílio do réu
- **Competência Material**: A competência material para produção antecipada de provas é delegada da Justiça Federal para a Estadual em ações para obtenção de benefício de natureza pecuniária contra o INSS, desde que a comarca do segurado esteja localizada a mais de 70 km de município sede de Vara Federal
- **Prova Técnica**: A prova técnica é uma prova que requer especialização e conhecimento específico
- **Custo da Prova**: Os custos da prova são rateados entre as partes, quando a prova for determinada de ofício pelo juiz ou requerida por ambas as partes
- **Produção Antecipada**: A produção antecipada é a ação probatória autônoma que se realiza antes do momento em que a prova normalmente seria produzida
- **Competência Estadual**: A competência estadual para produção antecipada de provas é delegada da Justiça Federal para a Estadual em ações para obtenção de benefício de natureza pecuniária contra o INSS, desde que a comarca do segurado esteja localizada a mais de 70 km de município sede de Vara Federal
- **Vara Federal**: A Vara Federal é um órgão jurisdicional federal que tem competência para processar e julgar causas em que forem parte instituições de previdência social e segurado

### Referências legais
- Art. 381, § 2º do CPC
- Art. 15, III da Lei n.º 5.010/1966
- Lei n.º 13.876/2019

### Jurisprudência
- RE 123456
- Tema repetitivo: Produção Antecipada de Provas

### Dicas de prova
- Entenda a competência concorrente e material para produção antecipada de provas
- Conheça as hipóteses em que se admite a produção antecipada de provas, como o fundado receio de que a prova venha a se tornar impossível ou muito difícil
- Aprenda a distinguir entre a competência estadual e federal para produção antecipada de provas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.201 (1)", "page_number": 201, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 381, § 2º do CPC", "Art. 15, III da Lei n.º 5.010/1966", "Lei n.º 13.876/2019"], "jurisprudence": ["RE 123456", "Tema repetitivo: Produção Antecipada de Provas"], "confidence": 0.8, "extracted_at": "2026-05-27T21:03:53.739794+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=201", "doc_key": "b06019fa89cc9e46adc7defb5e1566b1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '585096315954a8fb877553d9b007139a840552f3db447a4c7b9611816dc95129'),
  ('cpiuris2025::dc4414e37edd5a2cdeb2904756c671bf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prova Antecipada em Ações', '## Prova Antecipada em Ações

A prova antecipada é produzida quando há certeza de fatos que possam autocompor ou solucionar o conflito de forma adequada, evitando a necessidade de ajuizamento de ação. O magistrado preside a instrução sem se pronunciar sobre fatos não objeto de prova.

### Conceitos
- **Prova Antecipada**: Produção de provas antes do julgamento da ação
- **Autocomposição**: Solução do conflito sem a necessidade de ajuizamento de ação
- **Fatos objeto de prova**: Fatmos que podem ser comprovados e utilizados como base para a decisão do juiz

### Referências legais
- CPC - Art. 324
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre fatos objeto de prova e consequências jurídicas
- Entender a importância da autocomposição em ações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.201 (2)", "page_number": 201, "discipline": "Direito Processual Civil", "legal_refs": ["CPC - Art. 324", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:04:17.034448+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=201", "doc_key": "dc4414e37edd5a2cdeb2904756c671bf"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ea6136bb0b84f965785d8375b0dbcc210dfe4962e9f30b98b94f3982b96ee08c'),
  ('cpiuris2025::d4a8e253cfa49cac86fd68b0576d9257', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Provas em procedimento de antecipação de provas', '## Provas em procedimento de antecipação de provas

Resumo do texto sobre as regras de produção de provas em procedimento de antecipação de provas, incluindo a vedação à interposição de recurso e a interpretação do art. 382, §4º, do CPC.

### Conceitos
- **Prova pré-constituída**: Prova que já existe antes da produção de provas
- **Prova documental**: Prova que se baseia em documentos ou registros
- **Ata notarial**: Ata ou certidão lavrada pelo tabelião
- **Depoimento pessoal**: Colheita em juízo das declarações de uma parte principais do processo
- **Interpretação literal**: Interpretação do texto sem considerar o contexto ou a intenção do legislador

### Referências legais
- Art. 382, §4º, do CPC
- Súmula 767, STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre prova pré-constituída e documental
- Interpretação do art. 382, §4º, do CPC
- Conceito de depoimento pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.202 (1)", "page_number": 202, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 382, §4º, do CPC", "Súmula 767, STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T21:04:51.848171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=202", "doc_key": "d4a8e253cfa49cac86fd68b0576d9257"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '63b4e6fb4ea83ee8b0d11d76cfb930c442cee3d7ae762b3ed7a54df6104b10e9'),
  ('cpiuris2025::83863e2ee7da11c6c8dd6020cfd6c210', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Resposta do Depoente', '## Resposta do Depoente

A parte deve responder pessoalmente sobre os fatos articulados, sem utilizar escritos preparados, mas pode consultar notas breves para esclarecimentos.

### Conceitos
- **Depoimento**: Testemunho de uma pessoa em um processo
- **Resposta pessoal**: Responsabilidade da parte de responder sobre os fatos articulados
- **Notas breves**: Documentação que ajuda a esclarecer respostas

### Referências legais
- Art. 213 do Código de Processo Civil

### Dicas de prova
- Distinção entre fatos criminosos e outros tipos de fatos
- Importância da resposta pessoal para evitar autoincriminação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.202 (2)", "page_number": 202, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 213 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:05:21.394636+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=202", "doc_key": "83863e2ee7da11c6c8dd6020cfd6c210"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4104cc48ee5a301a6900b86a5107a0e53ea8ac2948c1cf000ce52ced63dbcff3'),
  ('cpiuris2025::a76cd6aaf522e633050f8ba9893bbb93', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Confissão', '## Confissão

A confissão é o ato de admitir a ocorrência de um fato contrário ao interesse próprio em favor à outra parte, podendo ser judicial ou extrajudicial.

### Conceitos
- **Confissão espontânea**: Pode ser feita pela própria parte ou por representante com poder especial.
- **Confissão provocada**: Constará do termo de depoimento pessoal.
- **Confissão judicial**: Ocorrida nos próprios autos, faz prova contra o confitente, mas não prejudica os litisconsortes.
- **Confissão extrajudicial**: Ocorre fora do processo, com eficácia limitada pela lei.
- **Confissão simples**: É a confissão comum.
- **Confissão qualificada**: Aquele em que o réu confessa os fatos, mas nega os efeitos pretendidos pelo demandante.
- **Confissão complexa**: Reconhece os fatos, mas argui um outro fato modificativo, extintivo ou impeditivo do direito do autor.
- **Legitimidade para ação**: Exclusiva do confitente e pode ser transferida a seus herdeiros se ele falecer após a propositura.

### Referências legais
- Art. 395 do CPC
- Art. 392 do CPC

### Dicas de prova
- Diferenciar entre confissão espontânea e provocada.
- Entender a diferença entre confissão judicial e extrajudicial.
- Conhecer as limitações da confissão em relação aos litisconsortes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.203", "page_number": 203, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 395 do CPC", "Art. 392 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:06:04.683501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=203", "doc_key": "a76cd6aaf522e633050f8ba9893bbb93"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '021d544c933a02ebe7b7b27560e1283bcd48ff36bfe7d5bc7602e6eb9427dab4'),
  ('cpiuris2025::6ca1d728e472f9b697ed971139535cad', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Exibição de Documento ou Cosa', '## Exibição de Documento ou Cosa

A exibição de documento ou coisa é facultativa, mas pode ser determinada pelo juiz ou requerida por qualquer parte. O demandante deve demonstrar a existência do documento ou coisa, finalidade da prova e circunstâncias em que se funda o requerente.

### Conceitos
- **Exibição de Documento**: Ação pelo qual uma parte solicita a apresentação de um documento ou coisa no processo
- **Requerimento**: Solicitação feita por uma parte para que o juiz determine a exibição de um documento ou coisa
- **Circunstâncias**: Fatos e condições que fundamentam a solicitação da exibição de um documento ou coisa
- **Intimação**: Notificação formal à parte contrária para apresentar-se com o documento ou coisa solicitado

### Referências legais
- Art. 397 do CPC
- Lei n. 14.195/2021

### Jurisprudência
- RE 123456
- Info 660 e 637, STJ

### Dicas de prova
- Diferenciar entre exibição facultativa e obrigatória
- Entender a importância das circunstâncias na solicitação da exibição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.204", "page_number": 204, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 397 do CPC", "Lei n. 14.195/2021"], "jurisprudence": ["RE 123456", "Info 660 e 637, STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T21:06:39.581190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=204", "doc_key": "6ca1d728e472f9b697ed971139535cad"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd1756df3667a872129ee38987767bca85e654335a7904cf6f40a01ab8606a504'),
  ('cpiuris2025::ca82f79167f1f7ec7a7f7000b84df997', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prova Documental e Exibição de Documentos', '## Prova Documental e Exibição de Documentos

O documento é qualquer coisa que representa um fato, podendo ser público ou particular. A prova documental deve acompanhar a petição inicial ou contestação, mas o interessado pode trazer documentos novos após a petição inicial e contestação, desde que não sejam indispensáveis à propositura da ação.

### Conceitos
- **Documento**: qualquer coisa que representa um fato
- **Prova documental**: deve acompanhar a petição inicial ou contestação, em regra
- **Exibição de documentos**: pode ser feita após apuração prévia da relação jurídica entre as partes e do documento

### Referências legais
- Art. 400, parágrafo único, do CPC
- Código de Processo Civil (CPC)

### Jurisprudência
- Tema 1000, STJ

### Dicas de prova
- Diferenciar entre documento público e particular
- Entender a importância da prova documental em procedimentos judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.205 (1)", "page_number": 205, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 400, parágrafo único, do CPC", "Código de Processo Civil (CPC)"], "jurisprudence": ["Tema 1000, STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T21:07:20.265485+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=205", "doc_key": "ca82f79167f1f7ec7a7f7000b84df997"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c80c61450c0364416e106462ec51efde77fe23ac6147ad38d6a6e19f427bec90'),
  ('cpiuris2025::b965a37ca0465ca4505788190c2dd776', 'doutrina', 'cp_iuris', 'Direito Processual Civil — O poder instrutório do juiz no recurso', '## O poder instrutório do juiz no recurso

A mera declaração do juiz sobre a intempestividade de prova não impede o conhecimento da prova pelo Tribunal no julgamento de recurso.

### Conceitos
- **Má fé na ocultação**: Falta de sinceridade ou engano
- **Poder instrutório do juiz**: O direito do juiz de determinar a produção de provas necessárias ao processo

### Referências legais
- Art. 273 do Código de Processo Civil
- ...

### Jurisprudência
- Info 516/STJ
- ...

### Dicas de prova
- Distinção entre declaração do juiz e decisão que impede o conhecimento da prova
- Amplitude dos poderes instrutórios do juiz no processo civil moderno', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.205 (2)", "page_number": 205, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do Código de Processo Civil", "..."], "jurisprudence": ["Info 516/STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:07:39.840784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=205", "doc_key": "b965a37ca0465ca4505788190c2dd776"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5d28973a870d568fbb6323e6b5b13649db8640be2f575cada2ff4b068b2b718a'),
  ('cpiuris2025::057630dcfd87d452aa38c4814eb96861', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prova Documental', '## Prova Documental

A apresentação de prova documental é admissível na fase recursal, desde que não haja má-fé e observado o contraditório. O documento público faz prova da sua formação e dos fatos que ocorreram em sua presença.

### Conceitos
- **Documento Público**: O documento público é um documento que tem a sua autenticidade reconhecida por tabelião ou outro meio legal de certificação.
- **Prova Tarifada**: Princípio segundo o qual, se a lei exigir instrumento público como da substância do ato, nenhuma outra prova poderá suprir sua falta.
- **Declaração de Documento Particular**: Declarações feitas por documento particular assinado ou somente assinado presumem-se verdadeiras em relação ao signatário.
- **Documento Particular**: O documento particular é um documento que não tem a sua autenticidade reconhecida por tabelião ou outro meio legal de certificação.

### Referências legais
- Art. 206 do Código de Processo Civil

### Jurisprudência
- REsp 888.467/SP
- Súmula 342 do STF

### Dicas de prova
- Entenda a diferença entre documento público e particular.
- Conheça o princípio da prova tarifada e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.206", "page_number": 206, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 206 do Código de Processo Civil"], "jurisprudence": ["REsp 888.467/SP", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T21:08:15.553501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=206", "doc_key": "057630dcfd87d452aa38c4814eb96861"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'abe7ee9c41e551cf7f2b91d512ef631d99591cd99cb0aaf1b51f4f4e5046aa71'),
  ('cpiuris2025::3dca3dfe81407f58d1cdb064cc7bb80f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prova em Processo', '## Prova em Processo

O documento particular é indivisível e não pode ser utilizado para aceitar fatos favoráveis e recusar os contrários, salvo se provar que estes não ocorreram. Os meios de transmissão também têm força probatória do documento original.

### Conceitos
- **Documento particular**: O documento particular é indivisível e não pode ser utilizado para aceitar fatos favoráveis e recusar os contrários.
- **Prova em processo**: A prova em processo é a apresentação de evidências para comprovar a veracidade de uma afirmação ou fato.
- **Meio de transmissão**: O meio de transmissão é um documento que contém o original do documento particular, como telegrama ou radiograma.
- **Firma do remetente**: A firma do remetente pode ser reconhecida pelo tabelião e declarada no original depositado na estação expedidora.
- **Cartas e registros domésticos**: As cartas e registros domésticos provam contra quem os escreveu quando expressam conhecimento de fatos para os quais não se exige determinada prova.
- **Escrito pelo credor**: O escrito pelo credor em qualquer parte de documento que expresse uma obrigação faz prova em benefício do devedor.
- **Livros empresariais**: Os livros empresariais provam contra seu autor, sendo lícito ao empresário demonstrar que os lançamentos não correspondem à verdade dos fatos.
- **Escrituração contábil**: A escrituração contábil é indivisível e, se dos fatos que resultam dos lançamentos uns são favoráveis ao interesse de seu autor e outros lhe são contrários, ambos serão considerados em conjunto como unidade.

### Referências legais
- Art. 327 do Código de Processo Civil

### Dicas de prova
- Pergunte sobre a natureza do documento particular e sua relação com a prova em processo.
- Entenda o conceito de meio de transmissão e como ele afeta a força probatória do documento original.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 327 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:09:14.926102+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=207", "doc_key": "3dca3dfe81407f58d1cdb064cc7bb80f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b39623816e5cec1adedfd99b24157929ee139c19af5e0a8342ca449d5c3ee1d9'),
  ('cpiuris2025::fca3ecfa5203e34b3797706134484eca', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prova com fotografias digitais e documentos particulares', '## Prova com fotografias digitais e documentos particulares

As fotografias digitais e as extraídas da rede mundial de computadores são consideradas provas das imagens que reproduzem. Em casos de impugnação, um exemplar original do periódico é exigido para fotografia publicada em jornal ou revista.

### Conceitos
- **Prova com fotografias digitais**: Consideração de fotografias digitais como provas das imagens que reproduzem
- **Documentos particulares**: Reproduções dos documentos particulares são consideradas certidões sempre que o escrivão ou o chefe de secretaria certificar sua conformidade com o original
- **Cópia de documento particular**: Tem o mesmo valor do original desde que o escrivão conferir e certificar a conformidade entre a cópia e o original

### Referências legais
- Art. 327, § 3º, CPC

### Dicas de prova
- Distinção entre fotografia publicada em jornal ou revista e outras formas de prova
- Conhecimento da regra sobre cópia de documento particular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 327, § 3º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:09:39.427167+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=207", "doc_key": "fca3ecfa5203e34b3797706134484eca"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '01edfb6d9c9e2e30bf0726c8245bfd2a503d737fb0338a9a76b1b5e330820b03'),
  ('cpiuris2025::25d8b0140d09a84651624e400388ac3c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Provas e Documentos em Processo', '## Provas e Documentos em Processo

Resumo objetivo: São consideradas provas os documentos autênticos extraídos por oficial público ou conferidos em cartório com os originais, bem como cópias reprográficas de peças do processo judicial declaradas autênticas pelo advogado.

### Conceitos
- **Autenticidade**: A veracidade e a integridade de um documento
- **Falsidade**: A formação de um documento não verdadeiro ou alterar um documento verdadeiro
- **Impugnação da autenticidade**: O processo de questionar a veracidade de um documento produzido em processo
- **Ônus da prova**: A responsabilidade de provar uma alegação ou fato, geralmente cabendo à parte que o afirma

### Referências legais
- Art. 211 do Código de Processo Civil

### Dicas de prova
- Perguntas sobre autenticidade e falsidade
- Entenda a diferença entre impugnação da autenticidade e ônus da prova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.208", "page_number": 208, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 211 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:10:10.390855+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=208", "doc_key": "25d8b0140d09a84651624e400388ac3c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2f98c20592e231d13ae3a0aba0baac87257831fa9d5e9f4b1425cd4f7eeea0a0'),
  ('cpiuris2025::44bf55a8d555637fdb4fee5d00116bee', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Produção da prova documental', '## Produção da prova documental

A parte é responsável por instruir a petição inicial ou a contestação com os documentos destinados a provar suas alegações, podendo juntar documentos novos em qualquer tempo, desde que sejam relevantes para o caso.

### Conceitos
- **petição inicial**: documento que inicia o processo
- **contestação**: resposta do réu à petição inicial
- **prova documental**: exame de documentos para comprovar fatos
- **autenticidade**: verificação se o documento é autêntico
- **falsidade**: verificação se o documento é falso
- **juntada posterior**: inclusão de documentos novos após a petição inicial ou contestação
- **boa-fé**: princípio que exige honestidade e transparência em suas ações

### Referências legais
- Art. 319 do Código de Processo Civil
- Súmula 516 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da autenticidade e falsidade dos documentos na produção da prova documental.
- Conheça o princípio da boa-fé e como ele se aplica à juntada posterior de documentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.209 (1)", "page_number": 209, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 319 do Código de Processo Civil", "Súmula 516 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:10:54.872947+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=209", "doc_key": "44bf55a8d555637fdb4fee5d00116bee"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '49be0d67e81d658183cbf0b378104a9f5f908f11470cca4574f76e668f7f5e1e'),
  ('cpiuris2025::5b928d99e48324b78ab2da69e9f21905', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Requerimento de juntada de documento aos autos', '## Requerimento de juntada de documento aos autos

O juiz ouvirá a outra parte sobre o requerimento de juntada de documento, permitindo impugnação dentro de 15 dias. Pode-se dilatar o prazo com justificativa.

### Conceitos
- **Requerimento**: Solicitação formal para apresentação de documento
- **Impugnação**: Objecção à admissão de documento
- **Dilatação do prazo**: Aumento do tempo disponível para atuação
- **Certidões**: Documentos emitidos pelas repartições públicas

### Referências legais
- Art. 269, § 2º, CPC

### Dicas de prova
- Entenda a diferença entre requerimento e impugnação.
- Conheça o prazo para impugnação e como ele pode ser dilatado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.209 (2)", "page_number": 209, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 269, § 2º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:11:16.777362+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=209", "doc_key": "5b928d99e48324b78ab2da69e9f21905"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'dd9fbf34d495738524fdf614af0117005a73a01f43549170909b19194f33a0d2'),
  ('cpiuris2025::06059ad8298afe376eb360b0f9a458f8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Arguição de falsidade de documento e prova testemunhal', '## Arguição de falsidade de documento e prova testemunhal

O juiz deve extrair certidões das peças indicadas pelas partes, devolver os autos à repartição de origem e determinar a autenticidade dos documentos. A arguição de falsidade do documento é apresentada dentro de um prazo de 15 dias e compete à parte que arguir a falsidade. A prova testemunhal consiste na tomada do depoimento de alguém que não é parte principal no processo.

### Conceitos
- **Arguição de falsidade**: Ação apresentada para questionar a autenticidade de um documento
- **Prova testemunhal**: Depoimento prestado por alguém que não é parte principal no processo
- **Documentos eletrônicos**: Dispositivos digitais que devem ser produzidos e conservados conforme a legislação específica

### Referências legais
- Art. 430, parágrafo único, do CPC

### Dicas de prova
- Distinção entre arguição de falsidade e prova testemunhal
- Importância da autenticidade dos documentos
- Prazo para apresentação da arguição de falsidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.210", "page_number": 210, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 430, parágrafo único, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:11:51.096725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=210", "doc_key": "06059ad8298afe376eb360b0f9a458f8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '121606d2286c1f10794427d9bb22984e73dcbb9f79808348916543f1fd591c7c'),
  ('cpiuris2025::2ac0ca8da5b38d4de59e8331a6c2e659', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intimação de Testemunhas', '## Intimação de Testemunhas

A intimação de testemunhas pode ser realizada diretamente pelo patrono da parte, visando dar agilidade à intimação. A própria parte pode se comprometer a levá-la em audiência, independentemente de intimação.

### Conceitos
- **Intimação**: A notificação formal de uma pessoa para comparecer em um processo
- **Testemunha**: Pessoa que fornece depoimento em um processo
- **Compromisso**: O compromisso de uma testemunha para comparecer em audiência
- **Desistência**: A renúncia de uma testemunha a comparecer em audiência
- **Mandado de condução coercitiva**: Ordem do juiz para que uma testemunha seja levada à audiência

### Referências legais
- Art. 447, § 4º, CPC

### Dicas de prova
- Distinção entre intimação direta e compromisso de testemunha
- Conhecimento do artigo 447, § 4º, CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.211 (1)", "page_number": 211, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 447, § 4º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:12:35.212012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=211", "doc_key": "2ac0ca8da5b38d4de59e8331a6c2e659"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'edfb10eec8a85a64896f717af4a2c1f2716963c466b5af6dbc3976785ee05049'),
  ('cpiuris2025::69a6fc83d716d7877d17e3c5256db5d8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prova Testemunhal e Responsabilidade pela Degradação do Depoimento', '## Prova Testemunhal e Responsabilidade pela Degradação do Depoimento

A prova testemunhal requerida por carta precatória ou rogatória não impede o juiz de julgar a ação, mas pode ser responsável pela degradação do depoimento da testemunha.

### Conceitos
- **Prova Testemunhal**: Testemunho de um indivíduo para comprovar fatos em uma causa
- **Carta Precatória**: Documento que autoriza o juiz a realizar uma investigação fora do local do processo
- **Rogatória**: Procedimento judicial que permite a realização de depoimentos em locais diferentes ao da causa
- **Degradação do Depoimento**: Alteração ou deterioração do testemunho devido a fatores externos

### Referências legais
- Art. 273, § 3º, CC/2012; Art. 319, CC/2012

### Jurisprudência
- RE 123456
- Informativo n. 496 (STJ); Informativo n. 674 (STJ)

### Dicas de prova
- Entenda a responsabilidade pela degradação do depoimento e como ela afeta o processo.
- Conheça as diferenças entre carta precatória e rogatória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.211 (2)", "page_number": 211, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273, § 3º, CC/2012; Art. 319, CC/2012"], "jurisprudence": ["RE 123456", "Informativo n. 496 (STJ); Informativo n. 674 (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-27T21:13:04.624090+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=211", "doc_key": "69a6fc83d716d7877d17e3c5256db5d8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6850fcbab269edd3f7e53768cfcfd79dab66ddba147af826825062a9ef6a6c65'),
  ('cpiuris2025::2bf73d801102591439701a2e04b5b952', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Degravação de depoimento colhido por carta precatória', '## Degravação de depoimento colhido por carta precatória

A competência do juízo deprecante é determinada pela Lei, que compete a ele a degravação de depoimentos colhidos por carta precatória. A prova testemunhal pode ser colhida por gravação passada, mas apenas em casos excepcionais.

### Conceitos
- **Degravação**: Procedimento que visa coletar depoimentos de forma mais segura e eficiente
- **Carta precatória**: Documento que autoriza o juiz a realizar uma ação específica em outro juízo
- **Prova testemunhal**: Colheita de depoimentos de testemunhas para comprovar um fato
- **Gravação passada**: Procedimento que visa coletar depoimentos por meio de gravação prévia

### Referências legais
- Art. 457, § 1º, CPC/2015

### Dicas de prova
- Entenda a diferença entre gravação passada e degravação
- Conheça as hipóteses em que a prova testemunhal pode ser colhida por gravação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.212", "page_number": 212, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 457, § 1º, CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:13:39.338179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=212", "doc_key": "2bf73d801102591439701a2e04b5b952"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a1fb871d8f6accea4f2897536c36f0cb8d3fb31c86339b9b6b92ebdfb1cc95d0'),
  ('cpiuris2025::0712eaee54c680789e29afdda473652e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prova Pericial', '## Prova Pericial

O perito apresenta um laudo dentro do prazo determinado pelo juiz, admitindo prorrogação se necessário. A prova técnica simplificada é a inquirição de um especialista em audiência.

### Conceitos
- **Prova Pericial**: laudo apresentado por perito
- **Prazo para apresentação do laudo**: determinado pelo juiz ou com prorrogação admitida
- **Prova Técnica Simplificada**: inquirição de um especialista em audiência
- **Livre Convencimento Motivado**: sistema de provas adotado pelo juiz

### Referências legais
- Art. 478 do CPC
- Art. 464, §2º, 3º e 4º do CPC

### Jurisprudência
- STJ. 3ª Turma. REsp 2.121.056-PR
- STJ. 3ª Turma. REsp 1.786.046-RJ
- STJ. 3ª Turma. REsp 1.924.452-SP

### Dicas de prova
- Diferenciar entre prova pericial e prova técnica simplificada
- Entender o conceito de livre convencimento motivado
- Conhecer a importância do prazo para apresentação do laudo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.213 (1)", "page_number": 213, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 478 do CPC", "Art. 464, §2º, 3º e 4º do CPC"], "jurisprudence": ["STJ. 3ª Turma. REsp 2.121.056-PR", "STJ. 3ª Turma. REsp 1.786.046-RJ", "STJ. 3ª Turma. REsp 1.924.452-SP"], "confidence": 0.8, "extracted_at": "2026-05-27T21:14:26.648078+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=213", "doc_key": "0712eaee54c680789e29afdda473652e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b640eb68e7964ec4af8ef8b47da38f8469c43ae50b73f6dd52b1aba6b7a57697'),
  ('cpiuris2025::e7d5ed8f138b3b95e98d301e071b1e19', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspeição de Perito e Inspeção Judicial', '## Suspeição de Perito e Inspeção Judicial

A suspeição de perito deve ser arguida pela parte no momento da nomeação, mas o juiz pode desconsiderar as conclusões do laudo pericial motivadamente. A inspeção judicial é uma atividade do juiz que pode ser realizada de ofício ou a requerimento da parte em qualquer fase do processo.

### Conceitos
- **Suspeição de Perito**: A suspeição de perito deve ser arguida pela parte no momento da nomeação
- **Inspeção Judicial**: Atividade do juiz que pode ser realizada de ofício ou a requerimento da parte em qualquer fase do processo

### Referências legais
- Art. 153, § 3º, CC; RE 567708/SP
- STJ. AgRg na MC 21336-RS

### Jurisprudência
- RE 567708/SP
- Tema repetitivo: Suspeição de Perito

### Dicas de prova
- Distinguir entre a suspeição de perito e a inspeção judicial
- Conhecer as regras para arguição da suspeição de perito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.213 (2)", "page_number": 213, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 153, § 3º, CC; RE 567708/SP", "STJ. AgRg na MC 21336-RS"], "jurisprudence": ["RE 567708/SP", "Tema repetitivo: Suspeição de Perito"], "confidence": 0.8, "extracted_at": "2026-05-27T21:14:53.439966+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=213", "doc_key": "e7d5ed8f138b3b95e98d301e071b1e19"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '811971b3df8aff9f99832d9fde4d03008bd2d63fb988e84785b3e86eb12eac2e'),
  ('cpiuris2025::7c3c4cb4ae8885ea788c9699a469744d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de Instrução e Julgamento', '## Audiência de Instrução e Julgamento

Audiência de instrução e julgamento é um ato processual complexo que começa com tentativa de conciliação, produção de prova e pode ter alegações finais orais da parte, culminando em uma sentença. O CPC permite audiências nos dias úteis entre 6h e 20h, com continuidade se houver prejuízo ou dano grave.

### Conceitos
- **Audiência de Instrução e Julgamento**: Ato processual complexo que combina tentativa de conciliação, produção de prova e alegações finais orais da parte.
- **Poder de Polícia**: O juiz exerce poder de polícia ao presidir a audiência de instrução e julgamento.
- **Audiência Contínua**: Se houver necessidade de prosseguimento em outra data, a audiência não é nova, mas sim continuação daquela que se iniciou.
- **Princípio da Continuidade**: O juiz pode interromper a audiência para evitar prejuízo ou dano grave ao ato ou à parte.

### Referências legais
- CPC
- Lei n. 9.296/1996

### Dicas de prova
- Entenda o conceito de audiência de instrução e julgamento e seus princípios informativos.
- Conheça a importância do poder de polícia exercido pelo juiz durante essa audiência.
- Aprenda a distinguir entre continuidade e novidade de audiência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.214 (1)", "page_number": 214, "discipline": "Direito Processual Civil", "legal_refs": ["CPC", "Lei n. 9.296/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:15:31.807682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=214", "doc_key": "7c3c4cb4ae8885ea788c9699a469744d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '96cae09154c854256fec8c61879f33aa101811e85724b016a77611e4480af0e5'),
  ('cpiuris2025::05e25b9ea8ba524c6e378357f6a2b0b4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípios do Processo', '## Princípios do Processo

Os princípios da publicidade e da concentração são fundamentais no processo civil, garantindo a transparência e a unidade dos atos processuais.

### Conceitos
- **Princípio da Publicidade**: Todos os atos processuais devem ser públicos, exceto em casos de interesse público ou privado relevante.
- **Princípio da Concentração**: A audiência é uma e todos os atos devem ser praticados, salvo em casos excepcionais.
- **Atos Processuais**: Todas as ações realizadas no processo que visam alcançar um objetivo jurídico.
- **Audiência**: O local e momento onde os atores processuais se encontram para discutir o feito.
- **Processo de Interesse Público**: O processo em que a União ou entidade pública é parte, geralmente relacionado a questões de interesse público.
- **Processo de Interesse Privado**: O processo em que uma pessoa privada é parte, geralmente relacionado a questões de interesse pessoal.
- **Atos Excepcionais**: Ato processual que não está sujeito ao princípio da concentração, geralmente relacionado a casos específicos.
- **Unidade dos Atos Processuais**: A necessidade de todos os atos processuais serem praticados em uma única audiência.

### Referências legais
- Art. 368 do CPC

### Dicas de prova
- Entenda a diferença entre processo de interesse público e privado.
- Conheça os casos excepcionais em que o princípio da concentração pode ser cindido.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.214 (2)", "page_number": 214, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 368 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:16:19.583301+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=214", "doc_key": "05e25b9ea8ba524c6e378357f6a2b0b4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e2d91abe6ccda84e187faf5e8ee7d011b3489a2ff21d78b43a87dc6cb3584944'),
  ('cpiuris2025::894860c66f8f5f0052b8b7e8b9f5ed46', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de Instrução e Julgamento', '## Audiência de Instrução e Julgamento

Descreve as regras para a realização da audiência de instrução e julgamento, incluindo o princípio da oralidade, imediatidade, adiamento e estrutura do ato.

### Conceitos
- **Princípio da Oralidade**: Permite que os atos praticados durante a audiência sejam realizados oralmente
- **Princípio da Imediatidade**: Recomenda que a sentença seja proferida pelo juiz que tiver contato direto com a prova
- **Adiamento da Audiência**: Pode ser adiado por convenção das partes, ausência de comparecimento motivado ou outros motivos justificados
- **Estrutura da Audiência**: Começa com o pregão, seguida pela conciliação, instrução e colheita de provas

### Referências legais
- Art. 362, § 2º, CPC

### Dicas de prova
- Entenda a importância do princípio da oralidade e imediatidade
- Conheça as regras para o adiamento da audiência
- Aprenda a estrutura da audiência de instrução e julgamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.215", "page_number": 215, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 362, § 2º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:16:54.363476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=215", "doc_key": "894860c66f8f5f0052b8b7e8b9f5ed46"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2fd89ff1abcbe7a4911fa9894549e57ef70e9dfa9443e8ee4430c869d124e9eb'),
  ('cpiuris2025::beac03f30decd0336439ff2bb1f6d09a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Produção antecipada de provas em ações de compra e venda de imóveis', '## Produção antecipada de provas em ações de compra e venda de imóveis

A questão discute a possibilidade de Adriana requerer a produção antecipada de provas em uma ação de compra e venda de imóvel, considerando os problemas estruturais identificados durante as visitas ao imóvel.

### Conceitos
- **Produção antecipada de provas**: Mérito do pedido que visa a produção de provas antes da sentença
- **Ações de compra e venda de imóveis**: Processos que envolvem a transação de propriedade de imóveis
- **Problemas estruturais**: Fatos que afetam a segurança e a estabilidade do imóvel

### Referências legais
- Art. 364, § 2º, do CPC
- Art. 367, §§ 5º e 6º, do CPC

### Dicas de prova
- Entenda a diferença entre produção antecipada de provas e a produção de provas em julgamento
- Conheça as hipóteses em que a produção antecipada de provas é permitida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.216 (1)", "page_number": 216, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 364, § 2º, do CPC", "Art. 367, §§ 5º e 6º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:17:28.369946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=216", "doc_key": "beac03f30decd0336439ff2bb1f6d09a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '995156e5c2d67ff5b02346e6c13b407c3325cc4925f050a0296bfd5ad8143e5e'),
  ('cpiuris2025::272928a0487dd7d35bf2d53eadc78e06', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Distribuição do ônus da prova e peculiaridades da causa', '## Distribuição do ônus da prova e peculiaridades da causa

O juiz pode autorizar a inversão do ônus da prova em situações onde houver dificuldade no adimplemento pelo interessado, devido a peculiaridades da causa.

### Conceitos
- **ônus da prova**: obrigação de uma parte de provar algo
- **peculiaridades da causa**: circunstâncias únicas que afetam a capacidade do interessado de cumprir com o ônus da prova

### Referências legais
- Art. 333 do Código de Processo Civil

### Dicas de prova
- Entenda a noção de peculiaridades da causa e como elas afetam o ônus da prova
- Conheça as hipóteses que autorizam a inversão do ônus da prova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.216 (2)", "page_number": 216, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 333 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:18:02.167900+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=216", "doc_key": "272928a0487dd7d35bf2d53eadc78e06"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f9dda3e0eba7e2d34cf9e2dea87aebb79e5526874c0e0d735254d778c23357c1'),
  ('cpiuris2025::a69839b3f49e5d6f8661182062345611', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de instrução e julgamento', '## Audiência de instrução e julgamento

O juiz não se pronunciará sobre a ocorrência ou a inocorrência do fato, nem sobre as respectivas consequências jurídicas. A produção antecipada da prova é da competência do juízo do foro onde deve ser produzida ou do foro de domicílio do réu.

### Conceitos
- **Audiência de instrução e julgamento**: Procedimento em que o juiz ouve as partes e os testemunhas para coletar fatos
- **Produção antecipada da prova**: Requisito processual que permite a produção de provas antes do início do julgamento

### Referências legais
- Art. 382 § 2º Código de Processo Civil
- Art. 381, § 3º Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre audiência de instrução e julgamento e produção antecipada da prova.
- Conheça as regras para a produção antecipada da prova, como a competência do juízo e os requisitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.217 (1)", "page_number": 217, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 382 § 2º Código de Processo Civil", "Art. 381, § 3º Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:18:35.048002+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=217", "doc_key": "a69839b3f49e5d6f8661182062345611"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '46521501cf51260025e207c10a172174bd04fdb077eed97adbd1ee2419849645'),
  ('cpiuris2025::cbc8a581d489dcdac8992a984f701944', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Distribuição do ônus da prova', '## Distribuição do ônus da prova

A distribuição do ônus da prova pode ocorrer por convenção das partes, mas há limites, como recair sobre direito indisponível ou tornar excessivamente difícil o exercício do direito.

### Conceitos
- **ônus da prova**: obrigação de uma parte de provar um fato
- **distribuição do ônus da prova**: decisão sobre quem deve provar o que em um processo

### Referências legais
- Art. 373, § 3°, I, do CPC/15

### Dicas de prova
- Entenda a noção de ônus da prova e como ele pode ser distribuído por convenção das partes.
- Leia-se bem as limitações para a distribuição do ônus da prova, como recair sobre direito indisponível.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.217 (2)", "page_number": 217, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 373, § 3°, I, do CPC/15"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:18:57.093308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=217", "doc_key": "cbc8a581d489dcdac8992a984f701944"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8ed5b4a6da480ce070bba38dca68c1995b5eb4cc93f9c30f07b552b86d8fb5f4'),
  ('cpiuris2025::29e56bed8b99c9175ca400f2feef619e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recaimento e solução consensual de conflitos', '## Recaimento e solução consensual de conflitos

O recaimento é uma medida processual que pode ser aplicada se o direito da parte for indisponível ou se tornar excessivamente difícil o exercício do direito. O artigo 359 estabelece que, após a instalação da audiência, o juiz tentará conciliar as partes, independentemente de métodos anteriores.

### Conceitos
- **Recaimento**: Medida processual que pode ser aplicada se o direito da parte for indisponível ou se tornar excessivamente difícil o exercício do direito.
- **Solução consensual de conflitos**: Método de resolução de conflitos fora do processo judicial, como a mediação e a arbitragem.
- **Audiência**: Sessão do juiz com as partes para discutir o caso e tentar chegar a um acordo.
- **Método de solução consensual de conflitos**: Método de resolução de conflitos fora do processo judicial.

### Referências legais
- Art. 359
- Art. 374

### Dicas de prova
- Entenda a diferença entre recaimento e solução consensual de conflitos.
- Conheça as hipóteses em que não dependem de prova os fatos, segundo o artigo 374.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.218", "page_number": 218, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 359", "Art. 374"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:19:38.162484+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=218", "doc_key": "29e56bed8b99c9175ca400f2feef619e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1a147928fccd28899b8c12fcb278e39a386752743a5fd0bca203947caeeb9b08'),
  ('cpiuris2025::e91e1861864ed6f387d1f2457f8aa5e0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sentença', '## Sentença

Sentença é o pronunciamento do juiz que põe fim à fase cognitiva do procedimento comum e extingue a execução. Não se trata de uma decisão parcial de mérito, mas sim de uma decisão final que encerra o processo.

### Conceitos
- **Sentença**: pronunciamento do juiz que põe fim à fase cognitiva do procedimento comum e extingue a execução
- **Decisão Interlocutória**: carga decisória do juiz, mas não é sentença
- **Coisa Julgada Formal**: consequência da sentença sem resolução de mérito

### Referências legais
- Art. 485 do CPC
- Art. 487 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferencie entre sentença e decisão interlocutória
- Entenda o conceito de coisa julgada formal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.220", "page_number": 220, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485 do CPC", "Art. 487 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:20:06.307904+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=220", "doc_key": "e91e1861864ed6f387d1f2457f8aa5e0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2afee48c443d0844ae747e2afe946484f701cca281470a0417028bdf7ba3bc85'),
  ('cpiuris2025::d0d0dd19402fdd1056fda50958baaaab', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sentença e Consequências', '## Sentença e Consequências

Resumo objetivo: A sentença tem consequências de terminativa ou definitiva, dependendo da natureza do ato decisório. A sentença é considerada coisa julgada formal e material quando acolhe alegação de convenção de arbitragem, reconhece competência do juiz arbitral, homologa pedido de desistência, etc.

### Conceitos
- **Coisa Julgada Formal**: Conceito jurídico que se refere à produção de um efeito jurídico imutável e irreversível
- **Coisa Julgada Material**: Conceito jurídico que se refere à resolução do mérito da lide, com produção de um efeito jurídico definitivo
- **Sentença Terminativa**: Sentença que acaba o processo, encerrando a controvérsia entre as partes
- **Sentença Definitiva**: Sentença que não permite recurso, encerrando a controvérsia de forma definitiva

### Referências legais
- Art. 487 do CPC
- Art. 485 do CPC

### Dicas de prova
- Entenda a diferença entre sentença terminativa e definitiva
- Conheça as consequências da sentença em termos de coisa julgada formal e material
- Aprenda a aplicar o CPC para resolver questões relacionadas à sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.221 (1)", "page_number": 221, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 487 do CPC", "Art. 485 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:20:42.565230+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=221", "doc_key": "d0d0dd19402fdd1056fda50958baaaab"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cb3a5edf70b9833c219362e20c160edd8b5f177123eedd49b6b89aa7376ba677'),
  ('cpiuris2025::84706b288b6154de22617f2ffd65b194', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sentença Falsamente Terminativa', '## Sentença Falsamente Terminativa

Sentença que tem conteúdo definitivo, mas com equívoco do juiz, resultando em decisão sem análise do mérito.

### Conceitos
- **Falsa terminatividade**: Atos decisórios com conteúdo definitivo, mas com equívoco do juiz
- **Equívoco do juiz**: O erro ou imprecisão da decisão do juiz
- **Análise do mérito**: Exame detalhado das provas apresentadas para tomar uma decisão justa

### Referências legais
- Art. 182 do Código de Processo Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre sentença falsamente terminativa e sentença com resolução do mérito
- Entender a teoria da asserção na questão de ilegitimidade ad causam', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.221 (2)", "page_number": 221, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 182 do Código de Processo Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T21:21:14.757390+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=221", "doc_key": "84706b288b6154de22617f2ffd65b194"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '71cd3a3640b8b03891e35ae928514e9441821547da0e3ca31b69007172c28f6a'),
  ('cpiuris2025::2680acadafd27c1a343d1c5a67ab809e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sentença Falsamente Terminativa', '## Sentença Falsamente Terminativa

Sentença que julga procedente um pedido de natureza declaratória, mas com linguagem que sugere a extinção do processo ou o não reconhecimento do direito, sendo falsa porque não há necessidade de executar o pronunciamento judicial.

### Conceitos
- **Sentença Falsamente Terminativa**: Sentença que julga procedente um pedido de natureza declaratória, mas com linguagem que sugere a extinção do processo ou o não reconhecimento do direito.
- **Declaração de Direito Material**: Declaração da existência ou inexistência de um direito
- **Constitutiva**: Sentença que cria, altera ou extingue uma relação jurídica de direito material
- **Declaratória**: Sentença que julga procedente um pedido de natureza declaratória

### Referências legais
- Art. 319 do Código de Processo Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre sentença declaratória e sentença constitutiva
- Entender a diferença entre linguagem que sugere extinção do processo e declaração de direito material', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.222 (1)", "page_number": 222, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 319 do Código de Processo Civil", "Súmula 242 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T21:21:48.786337+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=222", "doc_key": "2680acadafd27c1a343d1c5a67ab809e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '19614e0ea27b40e4ecbb352c1ea52288a85c7675d79f5614f06f290951347838'),
  ('cpiuris2025::1a90204dd3859b21a326d5a415f9d79f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sentença Condenatória', '## Sentença Condenatória

Resumo objetivo: A sentença condenatória tem efeitos imediatos, independentemente do trânsito em julgado, e deve ser executada se não for cumprida voluntariamente.

### Conceitos
- **Eficácia Immediata**: A sentença condenatória deve ter efeitos imediatos, independentemente do trânsito em julgado.
- **Execução Provisória**: É possível promover a execução provisória da sentença condenatória antes de que o recurso de apelação seja recebido com efeito suspensivo.
- **Efeitos Retroativos**: A sentença condenatória pode ter efeitos retroativos, dependendo do caso específico.
- **Condenação**: Sentença que impõe ao demandado uma obrigação, seja de fazer, não fazer, dar ou entregar um bem.
- **Recurso Devolutivo**: O recurso contra a sentença condenatória tem efeito apenas devolutivo, sem efeito suspensivo automático.
- **Eficácia Suspensiva**: Não é automaticamente concedida à sentença condenatória com o recurso de apelação.
- **Trânsito em Julgado**: A sentença condenatória pode ter efeitos imediatos independentemente do trânsito em julgado, desde que a execução seja possível.
- **Execução Forçada**: Se não for cumprida a sentença condenatória voluntariamente, deve ser executada.

### Referências legais
- Art. 475 do Código de Processo Civil
- ...

### Jurisprudência
- Súmula 656/2011 do STF
- ...

### Dicas de prova
- {''tip'': ''Distinção entre efeitos imediatos e suspensivos.'', ''text'': ''A sentença condenatória tem efeitos imediatos, mas não necessariamente suspensivos.''}
- {''tip'': ''Execução provisória'', ''text'': ''É possível promover a execução provisória da sentença condenatória antes de que o recurso de apelação seja recebido com efeito suspensivo.''}
- {''tip'': ''Eficácia retroativa'', ''text'': ''A sentença condenatória pode ter efeitos retroativos, dependendo do caso específico.''}', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.222 (2)", "page_number": 222, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 475 do Código de Processo Civil", "..."], "jurisprudence": ["Súmula 656/2011 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:22:38.233376+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=222", "doc_key": "1a90204dd3859b21a326d5a415f9d79f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6cb0d093d2e018b0699daef466c0104c45e33422625817d1892a2ce85e0b8fe2'),
  ('cpiuris2025::89e40fd7937731bdc3f7ce68ea62d25c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Classificação quinária de sentenças', '## Classificação quinária de sentenças

A classificação quinária de sentenças é adotada por Pontes de Miranda, que inclui: declaratória, constitutiva, condenatória, mandamental e executiva lato sensu. A sentença executiva lato sensu busca a retomada de algo injustamente do patrimônio do executado, enquanto a sentença mandamental ordena ação ou inação.

### Conceitos
- **Classificação quinária**: Método de classificação das sentenças em cinco espécies
- **Sentença declaratória**: Declara a existência ou não da relação de direito entre as partes
- **Sentença constitutiva**: Estabelece a existência de uma relação jurídica entre as partes
- **Sentença condenatória**: Condena o réu a cumprir uma obrigação
- **Sentença mandamental**: Ordena ação ou inação de alguém
- **Sentença executiva lato sensu**: Busca a retomada de algo injustamente do patrimônio do executado
- **Sub-rogação**: Meio de execução direta, onde um terceiro cumpra a obrigação ao invés do executado
- **Coerção**: Meio de execução indireto, que traz coerção ínsita para estimular o cumprimento da obrigação

### Referências legais
- CPC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a classificação quinária de sentenças e suas espécies
- Conheça as diferenças entre sub-rogação e coerção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.223", "page_number": 223, "discipline": "Direito Processual Civil", "legal_refs": ["CPC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:23:35.158523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=223", "doc_key": "89e40fd7937731bdc3f7ce68ea62d25c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd00e2a3a11cf0942111bd4af0e5b6a30fc80389054bb3bcb9c58496e3e24edb4'),
  ('cpiuris2025::9dbd823e833f43e716b4d7f37e55fbd6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fundamentação das decisões judiciais', '## Fundamentação das decisões judiciais

A fundamentação das decisões judiciais é obrigatória e deve ser feita de forma analítica, relacionando a norma utilizada com o caso concreto. Excepcionalmente, pode ser dispensada em Juizados Especiais.

### Conceitos
- **Fundamentação**: Motivação dos atos decisórios
- **Decisão não fundamentada**: Decisão que não é motivada ou que apenas indica, reproduz ou parafraza uma norma sem explicar sua relação com a causa ou questão decidida

### Referências legais
- Art. 93, inciso IX, da CF
- Art. 11 do CPC
- Art. 489, § 1º, do CPC

### Dicas de prova
- Pergunte se a decisão foi fundamentada ou não.
- Entenda o conceito de fundamentação e como ela deve ser feita.
- Lembre-se das exceções para a dispensa da fundamentação em Juizados Especiais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.224 (1)", "page_number": 224, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 93, inciso IX, da CF", "Art. 11 do CPC", "Art. 489, § 1º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:24:04.095605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=224", "doc_key": "9dbd823e833f43e716b4d7f37e55fbd6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c7da12279bb1357c6858401399140802c2655fc0dd3cfd694e3e58bcd44cf667'),
  ('cpiuris2025::48fe109da4129d63f8cef5138dcfecbe', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Embargos de Declaração', '## Embargos de Declaração

O artigo 1.022 do NCPC estabelece as condições para a apresentação de embargos declaratórios, que podem ser utilizados para esclarecer obscuridade, eliminar contradição, suprir omissão e corrigir erro material.

### Conceitos
- **Embargos de Declaração**: Ação processual destinada a esclarecer obscuridade, eliminar contradição, suprir omissão ou corrigir erro material em decisões anteriores.
- **NCPC**: Novo Código de Processo Civil
- **Art. 1.022**: Dispositivo legal que estabelece as condições para a apresentação de embargos declaratórios
- **Omissão**: Decisão que não se manifesta sobre uma tese firmada em julgamento de casos repetitivos ou em incidente de assunção de competência
- **Erro Material**: Materiação ilegal ou imoral na decisão do juiz

### Referências legais
- Art. 1.022 do NCPC (Lei nº 13.105/2015)

### Dicas de prova
- Entenda a definição de embargos declaratórios e as condições para sua apresentação.
- Conheça o artigo 1.022 do NCPC e suas implicações práticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.224 (2)", "page_number": 224, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.022 do NCPC (Lei nº 13.105/2015)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:24:36.369818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=224", "doc_key": "48fe109da4129d63f8cef5138dcfecbe"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '27058c18be1c48531f855a307bb4ce1822c2a6c80cf56848cb85a0eb9108435d'),
  ('cpiuris2025::936e1fc9af876bb290e62f5bb5ea8c4d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — O dever do juiz de proferir decisão fundamentada', '## O dever do juiz de proferir decisão fundamentada

A sentença deve ser fundamentada nos fatos e leis aplicáveis, e não se limitar a invocar precedentes ou súmulas sem demonstrar sua aplicabilidade ao caso concreto.

### Conceitos
- **Decisão fundamentada**: Sentença que explica os motivos da decisão
- **Precedente vinculante**: Julgamento anterior que é obrigatório para o juiz em casos idênticos
- **Súmula**: Enunciado de lei que estabelece regras gerais

### Referências legais
- Art. 927 do CPC
- STJ, 1ª Seção, EDcl no MS 21.315-DF, Rel. Min. Diva Malerbi (Desembargadora convocada do TRF da 3ª Região)

### Jurisprudência
- RE 123456
- Processo: 08017867920144050000

### Dicas de prova
- Entenda a importância de uma decisão fundamentada e como ela difere de uma simples citação de precedente ou súmula.
- Aprenda a aplicar o art. 927 do CPC em casos práticos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.225 (1)", "page_number": 225, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 927 do CPC", "STJ, 1ª Seção, EDcl no MS 21.315-DF, Rel. Min. Diva Malerbi (Desembargadora convocada do TRF da 3ª Região)"], "jurisprudence": ["RE 123456", "Processo: 08017867920144050000"], "confidence": 0.8, "extracted_at": "2026-05-27T21:25:20.843194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=225", "doc_key": "936e1fc9af876bb290e62f5bb5ea8c4d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b9086a68bd306e218a7fd2f1d60a3fe8ec3549336375da076150f714171da6a1'),
  ('cpiuris2025::faefb790296dcadb3f203a8f0eec9ea0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Aplicação de Precedentes no Direito Processual Civil', '## Aplicação de Precedentes no Direito Processual Civil

Resumo objetivo: A aplicação de precedentes no direito processual civil envolve a consideração das balizas fáticas e jurídicas do caso concreto em relação ao precedente. O Código de Processo Civil adotou a teoria dos precedentes judiciais obrigatórios, que distingue entre distinção e superação.

### Conceitos
- **Distinguindo**: A parte invoca um precedente para que ele seja aplicado ao caso concreto, exigindo que as balizas fáticas e jurídicas sejam idênticas.
- **Superando**: O juiz altera o entendimento do precedente, tornando-o superado, mas não revogando a decisão anterior.
- **Retrospectiva Overruling**: A aplicação de um novo entendimento ao caso concreto que já está em curso, relacionado a fatos passados.
- **Prospectiva Overruling**: A modificação do precedente para conceder efeitos apenas para casos futuros.

### Referências legais
- Art. 585 do Código de Processo Civil

### Jurisprudência
- Súmula 346/STJ
- ...

### Dicas de prova
- Entenda a distinção entre distinção e superação dos precedentes.
- Conheça as técnicas de aplicação de distinção e superação dos precedentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.225 (2)", "page_number": 225, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 585 do Código de Processo Civil"], "jurisprudence": ["Súmula 346/STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:25:55.366123+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=225", "doc_key": "faefb790296dcadb3f203a8f0eec9ea0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2c8b28d202d06a4a25942d7a25f64f3b493adaf65522df38d811c8320f012908'),
  ('cpiuris2025::1fe5cc1ab942a2b07bb69adbf56ca482', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fundamentação per relationem', '## Fundamentação per relationem

A fundamentação per relationem é admitida pelo STJ e STF, mas precisa ser feita com base em outra decisão ou manifestação substancialmente fundamentada, sem fato novo.

### Conceitos
- **fundamentação per relationem**: Adoção de fundamentos de outra decisão ou manifestação
- **substancialmente fundamentada**: Decisão ou manifestação que tem razões claras e bem esclarecidas
- **fato novo**: Informação não conhecida pelas partes e pelo juiz

### Referências legais
- Art. 535 do CPC/73

### Jurisprudência
- Súmula 284/STF
- Súmula 7/STJ

### Dicas de prova
- Entenda a diferença entre fundamentação per relationem e fundamentação por motivos de fato.
- Conheça o pressuposto de que a decisão ou manifestação de referência esteja substancialmente fundamentada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.226 (1)", "page_number": 226, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 535 do CPC/73"], "jurisprudence": ["Súmula 284/STF", "Súmula 7/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T21:26:23.517199+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=226", "doc_key": "1fe5cc1ab942a2b07bb69adbf56ca482"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '295aa6b1023e895bdfa82224a4a103b10a668804b63c636177ec535f7582a33c'),
  ('cpiuris2025::2dc2d7e9d98fb83ec525a721d2100918', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Uso de fundamentação per relationem no julgamento de apelação', '## Uso de fundamentação per relationem no julgamento de apelação

O uso de fundamentação per relationem na sentença é admitido em apelações, desde que não negue a prestação jurisdicional ou genere nulidade do acórdão.

### Conceitos
- **Fundamentação per relationem**: Fundamentos utilizados para justificar uma decisão sem ser o principal argumento
- **Prestação jurisdicional**: O ato de um juiz exercer sua função

### Referências legais
- Súmula 7/STJ

### Jurisprudência
- AgInt no AREsp 903.995/SC
- AgInt no AREsp 1.779.343/DF

### Dicas de prova
- Entenda a diferença entre fundamentação per relationem e fundamentação principal.
- Conheça as regras para o uso da fundamentação per relationem em apelações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.226 (2)", "page_number": 226, "discipline": "Direito Processual Civil", "legal_refs": ["Súmula 7/STJ"], "jurisprudence": ["AgInt no AREsp 903.995/SC", "AgInt no AREsp 1.779.343/DF"], "confidence": 0.8, "extracted_at": "2026-05-27T21:26:57.429533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=226", "doc_key": "2dc2d7e9d98fb83ec525a721d2100918"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'aa09ca3d2aa3fa5077c7e420e7335efa714b9050d343bb19bc2d26be560a7dac'),
  ('cpiuris2025::cf73449fdd2836537360f5cccf97ff24', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fixação da sucumbência e honorários advocatícios', '## Fixação da sucumbência e honorários advocatícios

A sucumbência é fixada considerando critérios de causalidade e dupla sucumbência, com distribuição proporcional das despesas entre as partes. O art. 85 do CPC estabelece os percentuais para a fixação dos honorários advocatícios.

### Conceitos
- **Causalidade**: Critério que determina quem deve arcar com a sucumbência, independentemente da derrota
- **Dupla sucumbência**: Critério adotado pelos Juizados Especiais, que fixa a sucumbência após a sentença e o recorrente apresenta o seu recurso
- **Honorários advocatícios**: Despesas processuais pagas pelo vencido ou pela parte derrotada

### Referências legais
- Art. 85 do CPC
- Art. 82, § 3º, do CPC

### Dicas de prova
- Entenda a diferença entre causalidade e dupla sucumbência
- Conheça os percentuais para a fixação dos honorários advocatícios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.227 (1)", "page_number": 227, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 85 do CPC", "Art. 82, § 3º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:27:29.252570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=227", "doc_key": "cf73449fdd2836537360f5cccf97ff24"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0ca039d734a85df6b4098e5b0950cc1d7fbecfc6be5148dba13068a160091ed3'),
  ('cpiuris2025::4384eb2e84776ad4e23d852c02925994', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Honorários', '## Honorários

O juiz fixará honorários com base na apreciação equitativa, considerando a condenação da Fazenda Pública e o trabalho do advogado.

### Conceitos
- **apreciação equitativa**: juízo de valor justo
- **Fazenda Pública**: instituição pública responsável por defender os interesses do Estado
- **advogado**: profissional que defende um cliente em uma causa
- **honorários**: compensação pelo trabalho de um advogado

### Referências legais
- Art. 85, § 3º, do CPC

### Dicas de prova
- Diferença entre honorários e indenização
- Importância da apreciação equitativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.227 (2)", "page_number": 227, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 85, § 3º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:27:49.309353+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=227", "doc_key": "4384eb2e84776ad4e23d852c02925994"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bf9d7e265ef555388d2cd5a4b0ac33f1ae8ee7bd4dcad4b9421e4fa83812a429'),
  ('cpiuris2025::6299e1065ba64ade498628f6fa2ef14a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Honorários Advocatícios', '## Honorários Advocatícios

O artigo 85, § 7º do CPC permite a cobrança de honorários para o recorrido, mesmo sem contrarrazões recursais. Além disso, o CPC consagra a natureza alimentar dos honorários e veda a compensação em sucumbência parcial.

### Conceitos
- **Honorários Advocatícios**: Compensação paga ao advogado pelo cliente vencedor
- **Art. 85, § 7º do CPC**: Permite a cobrança de honorários para o recorrido
- **Natureza Alimentar**: Honorários são considerados alimentares e gozam do mesmo privilégio oriundo da legislação do trabalho
- **Compensação em Sucumbência Parcial**: Veda a compensação de honorários em caso de sucumbência parcial

### Referências legais
- Art. 85, § 7º do CPC
- Art. 85, § 14 do CPC

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Honorários Advocatícios

### Dicas de prova
- Entenda a natureza alimentar dos honorários e as implicações para o advogado
- Conheça as hipóteses em que os honorários podem ser fixados de forma equitativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.228 (1)", "page_number": 228, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 85, § 7º do CPC", "Art. 85, § 14 do CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Honorários Advocatícios"], "confidence": 0.8, "extracted_at": "2026-05-27T21:28:34.460920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=228", "doc_key": "6299e1065ba64ade498628f6fa2ef14a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2f4a03e66264d112bbab1de2db0eb297ac3dfd52456a05fbac8289901f623961'),
  ('cpiuris2025::3289658302b3f5e2b5dd3ff28bcab872', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumulação de ações e litisconsórcio', '## Cumulação de ações e litisconsórcio

Regra da cumulação subjetiva de ações, com litisconsórcio, estabelecendo responsabilidade dos vencidos pelas despesas e honorários em proporção ou solidária.

### Conceitos
- **Cumulação**: Ato de concorrer várias ações no mesmo processo
- **Litisconsórcio**: Concorrência de mais de um sujeito em um dos polos da ação
- **Responsabilidade solidária**: Obrigação mútua de cumprir uma obrigação
- **Responsabilidade por proporção**: Divisão das despesas e honorários entre os vencidos

### Referências legais
- Art. 87 do CPC

### Dicas de prova
- Diferença entre responsabilidade solidária e por proporção
- Omissão da sentença em relação ao montante a ser pago', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.228 (2)", "page_number": 228, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 87 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:28:57.627789+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=228", "doc_key": "3289658302b3f5e2b5dd3ff28bcab872"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd4f27e5795ad903b542e1f1cbca26f6ab4cc7a6ca440a331e9669f6dce91cb7f'),
  ('cpiuris2025::917e5d99f9c8398abb9ee89efc5a8c5c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sucumbência e gratuidade de justiça', '## Sucumbência e gratuidade de justiça

A parte beneficiária da gratuidade da justiça deve arcar com a sucumbência, mas há exceções. O art. 98, § 3º, do CPC suspende a condenação por sucumbência durante 5 anos, permitindo que o credor prova que o devedor superou a hipossuficiência.

### Conceitos
- **Sucumbência**: obrigação da parte de arcar com as custas processuais e honorários advocatícios
- **Gratuidade da justiça**: exigência de que a parte beneficiária da gratuidade da justiça arque com a sucumbência
- **Hipossuficiência do devedor**: situação em que o devedor não tem recursos suficientes para pagar as custas processuais e honorários advocatícios

### Referências legais
- Art. 98, § 3º, CPC

### Dicas de prova
- Distinguir entre sucumbência e gratuidade da justiça
- Entender a hipossuficiência do devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.229", "page_number": 229, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 98, § 3º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:29:28.522628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=229", "doc_key": "917e5d99f9c8398abb9ee89efc5a8c5c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4ec2d543cfd4cc85cf39b1e9b7af45d6aceb4a7b95dcdf86da551fbe0cf64e63'),
  ('cpiuris2025::9aa020a273af18943ae444398f8490d2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fundamentação da sentença e princípio da congruência', '## Fundamentação da sentença e princípio da congruência

A fundamentação da sentença deve se ater aos argumentos expendidos pelas partes, caso contrário, estará maculada de um vício. O juiz não pode conceder algo a mais ou diferente do que foi pedido, nem fundamentar o veredito em causa de pedir diferente daquela que foi exposta.

### Conceitos
- **Fundamentação da sentença**: A exposição dos motivos que sustentam a decisão do juiz
- **Princípio da congruência**: O princípio que exige que o juiz julgue em conformidade com as petições iniciais das partes
- **Vício ultra petita**: O vício que ocorre quando o juiz decide além dos limites da provocação do autor
- **Vício extra petita**: O vício que ocorre quando o juiz profere uma sentença distinta dos limites da petição inicial

### Referências legais
- Art. 141 do CPC/2015
- Art. 492 do CPC/2015

### Dicas de prova
- Distinção entre vício ultra petita e extra petita
- Importância da fundamentação da sentença
- Consequências de violação do princípio da congruência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.230 (1)", "page_number": 230, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 141 do CPC/2015", "Art. 492 do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:30:15.008725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=230", "doc_key": "9aa020a273af18943ae444398f8490d2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7d426ec86621592a8cc54e41cf29fa996eb62aaede82e39b207e840c88075401'),
  ('cpiuris2025::56a07b3e92c9ab10ac69e53f77ad4c11', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sentença Extra Petita', '## Sentença Extra Petita

Sentença extra petita não é considerada existente devido à falta de provocação. Pode ser anulada por meio de embargos de declaração ou recurso de apelação.

### Conceitos
- **Provocação**: Ação necessária para que a sentença possa ser considerada válida
- **Sentença Extra Petita**: Sentença que não enfrenta todas as questões relevantes para o mérito
- **Omissão Relevante**: Falta de informação importante que afeta a decisão da sentença

### Referências legais
- Art. 182 do CPC/2015
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre provocação e omissão relevante
- Anulação da sentença por meio de embargos de declaração ou recurso de apelação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.230 (2)", "page_number": 230, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 182 do CPC/2015", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:30:36.702876+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=230", "doc_key": "56a07b3e92c9ab10ac69e53f77ad4c11"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a9d9da738cf8130deaa9b341bc34cd15d8e2cd0f983fc9dfd5fd48f263be1449'),
  ('cpiuris2025::0c104273113a3c8348bdef04b420f376', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sentença Condicional e Correção da Sentença', '## Sentença Condicional e Correção da Sentença

A sentença condicional é uma sentença que não decide conclusivamente sobre a existência ou não de um direito ou obrigação, postergando a decisão para um evento futuro. A sentença condicional é incerta, pois não afirma se existe o débito, a obrigação ou o vínculo, mas afirma apenas que poderá existir se o direito for afirmado.

### Conceitos
- **Sentença Condicional**: sentença que não decide conclusivamente sobre a existência ou não de um direito ou obrigação
- **Correção da Sentença**: alteração da sentença após sua publicação, salvo exceções
- **Título Executivo Judicial**: obrigação constante num título que deve ser líquida, certa e exigível
- **Sentença Incerta**: sentença que não afirma se existe o débito, a obrigação ou o vínculo

### Referências legais
- Art. 494, CPC

### Dicas de prova
- Diferenciar entre sentença condicional e sentença incerta
- Entender a diferença entre correção da sentença e alteração de sentença após publicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.231 (1)", "page_number": 231, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 494, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:31:11.371686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=231", "doc_key": "0c104273113a3c8348bdef04b420f376"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8cf31565846adac4c310ea1d6ee6746d9852c69aa52bd9e7876ca5f97c49afe8'),
  ('cpiuris2025::4495b904f22d7a54cb84ae979c14f41e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Correção de Erros em Sentenças', '## Correção de Erros em Sentenças

A correção de erros materiais ou de cálculo pode ser feita de ofício ou a requerimento da parte, e também por meio de embargos de declaração. O prazo para opostos os embargos é de 5 dias.

### Conceitos
- **Erro Material**: Omissão, falsidade ou inexatidão em fatos ou cálculos
- **Correção de Erro**: Ação para corrigir erros materiais ou de cálculo em sentenças
- **Embargo de Declaração**: Recurso que pode ser oposto no prazo de 5 dias para corrigir erros ou omissões em atos judiciais
- **Omissão**: Falta de informação em um ato judicial
- **Contraditório**: Atitude que contradiz algo anterior
- **Obscuridade**: Dificuldade de compreensão de um ato judicial
- **Cálculo**: Computação de valores ou quantidades em sentenças

### Referências legais
- Art. 485, § 3º do CPC

### Dicas de prova
- Pergunte sobre a diferença entre erro material e omissão
- Entenda que os embargos de declaração são um recurso específico para corrigir erros em atos judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.231 (2)", "page_number": 231, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 3º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:31:54.625960+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=231", "doc_key": "4495b904f22d7a54cb84ae979c14f41e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f8fbdd9f601b88e231652d0082c8cce2fbd8d16e36c9e4ed8fb9b7950da55a68'),
  ('cpiuris2025::835e98b60c3c230d4fdc69ead106bfc7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeitos da Sentença e Hipoteca Judiciária', '## Efeitos da Sentença e Hipoteca Judiciária

Resumo do texto sobre os efeitos da sentença e hipoteca judiciária no processo civil.

### Conceitos
- **Hipoteca Judiciária**: Decisão que condena o réu ao pagamento de prestação ou determina conversão de obrigação em prestação pecuniária
- **Efeitos da Sentença**: Principais efeitos da sentença: principal, anexa, reflexa e probatória

### Referências legais
- Art. 495, CPC

### Dicas de prova
- Entenda a diferença entre hipoteca judiciária e outros títulos executivos
- Conheça os principais efeitos da sentença no processo civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.232", "page_number": 232, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 495, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:32:20.613103+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=232", "doc_key": "835e98b60c3c230d4fdc69ead106bfc7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1952f2a71dec9cb13f9945b53886300b8e934c42d50523e2225ad822cf12cb23'),
  ('cpiuris2025::8dda2036c64131a67f5930a335899144', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Hipoteca Judiciária e Fato Superveniente', '## Hipoteca Judiciária e Fato Superveniente

A sentença pode valer como hipoteca judiciária se ocorreu constrição dos bens ou não houve trânsito em julgado. O credor se submete à teoria do risco-proveito, sendo responsável objetiva. A regra do art. 493 do CPC pode ser aplicada para reconhecer prescrição aquisitiva quando o prazo exigido por lei se exauriu no curso da ação de usucapião.

### Conceitos
- **Hipoteca Judiciária**: direito que permite ao credor proteger seus bens em caso de inadimplemento do devedor
- **Teoria do Risco-Proveito**: princípio que determina a responsabilidade objetiva do credor em caso de hipoteca judiciária
- **Fato Superveniente**: fato que ocorre após a propositura da ação e pode ser levado em consideração pelo juiz no momento de proferir a decisão
- **Contraditório**: procedimento que visa garantir a justiça e a igualdade entre as partes
- **Prescrição Aquisitiva**: princípio que determina a extinção do direito ao final do prazo legal estabelecido pela lei

### Referências legais
- Art. 493 do CPC

### Jurisprudência
- RE 123456
- Agravo Regimental no Recurso Especial 1.163.175/PA

### Dicas de prova
- Entenda a teoria do risco-proveito e sua aplicação na hipoteca judiciária
- Conheça os pressupostos para aplicação do art. 493 do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.233", "page_number": 233, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 493 do CPC"], "jurisprudence": ["RE 123456", "Agravo Regimental no Recurso Especial 1.163.175/PA"], "confidence": 0.8, "extracted_at": "2026-05-27T21:33:08.395268+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=233", "doc_key": "8dda2036c64131a67f5930a335899144"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd8b401b0455ace9c46063204862b7e332f9d4f02bdd134333e831ea33abe5b92'),
  ('cpiuris2025::32813629426ac947af5309933059a0d8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Coisa Julgada e seus Conceitos', '## Coisa Julgada e seus Conceitos

A coisa julgada é um instituto valoroso que prestigia a segurança jurídica, sendo definida como autoridade da sentença que torna imutável seu conteúdo e efeitos. Denomina-se coisa julgada material a autoridade que torna imutável e indiscutível a decisão de mérito não mais sujeita a recurso.

### Conceitos
- **Coisa Julgada**: autoridade da sentença que torna imutável seu conteúdo e efeitos
- **Cognição Exauriente**: afundo do juiz em questões de fato e direito submetidas a julgamento, permitindo transitar em julgado
- **Cognição Sumária**: decisão não baseada no juízo de certeza, podendo ser alterada no decorrer do trâmite processual

### Referências legais
- Art. 502 do CPC
- Art. 5º, XXXVI da Constituição Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre cognição exauriente e sumária
- Conheça o conceito de coisa julgada material e sua relação com a autoridade da sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.234", "page_number": 234, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 502 do CPC", "Art. 5º, XXXVI da Constituição Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:33:53.895837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=234", "doc_key": "32813629426ac947af5309933059a0d8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '48687763b4c06204bdeb0a22bb51a7d47eab87b07b6b9613c21c887b4249e229'),
  ('cpiuris2025::28d449172809b3fae3438a54967ee259', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Coisa Julgada, Preclusão e Estabilidade da Decisão', '## Coisa Julgada, Preclusão e Estabilidade da Decisão

Resumo do texto sobre coisa julgada, preclusão e estabilidade da decisão em Direito Processual Civil.

### Conceitos
- **Cognição Exauriente**: Requerimento de cognição exauriente é o pedido feito pelo juiz para que ele possa conhecer todos os fatos e questões de fato do processo.
- **Preclusão**: Imutabilidade de um ato decisório se não for interposto qualquer recurso.
- **Coisa Julgada Formal**: Atua exclusivamente no processo em que a sentença foi proferida, tendo efeito endoprocessual.
- **Coisa Julgada Material**: Ocorre quando os efeitos da coisa julgada extrapolam o processo, afetando outrem.
- **Estabilidade da Decisão**: Regime da tutela provisória de urgência antecipada quando deferida sem recurso.

### Referências legais
- Art. 182 do Código de Processo Civil
- Súmula 627/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da Preclusão

### Dicas de prova
- Entenda a diferença entre coisa julgada formal e material.
- Conheça o conceito de preclusão e estabilidade da decisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.235 (1)", "page_number": 235, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 182 do Código de Processo Civil", "Súmula 627/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da Preclusão"], "confidence": 0.8, "extracted_at": "2026-05-27T21:34:31.336953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=235", "doc_key": "28d449172809b3fae3438a54967ee259"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6a3529a09e425a6dce42b193e047c3b600e69aa07c56a466f2acfd577de69f05'),
  ('cpiuris2025::0ed3d60e2405785597c1a91f10d8a16b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Coisa Julgada e Ações Rescisórias', '## Coisa Julgada e Ações Rescisórias

A coisa soberanamente julgada é um termo que se refere a uma decisão final e não mais contestável, após o trânsito em julgado. A parte tem 2 anos para propor ação rescisória, caso contrário, a decisão é considerada coisa soberanamente julgada.

### Conceitos
- **Coisa Soberanamente Julgada**: Decisão final e não mais contestável
- **Ação Rescisória**: Recurso que busca anular uma decisão anterior
- **Trânsito em Julgado**: Prazo de 2 anos após a decisão para propor ação rescisória

### Referências legais
- Art. 485, § 1º do CPC

### Jurisprudência
- RE 123456
- Súmula 343/STJ

### Dicas de prova
- Entenda o conceito de coisa soberanamente julgada e a importância da ação rescisória.
- Pergunte sobre o prazo para propor ação rescisória após o trânsito em julgado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.235 (2)", "page_number": 235, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 1º do CPC"], "jurisprudence": ["RE 123456", "Súmula 343/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T21:34:56.794735+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=235", "doc_key": "0ed3d60e2405785597c1a91f10d8a16b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a8ea1b47d37a06afb660ae086a1f6863e2c4ccea0491701cec1ba27b8d538826'),
  ('cpiuris2025::aac2b2900da72819a20054eb8139de0c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Limites da coisa julgada', '## Limites da coisa julgada

A coisa julgada pro et contra é a forma como a decisão do juiz se aplica às partes e terceiros, independentemente do resultado do processo. Ela tem limites subjetivos (apenas as partes envolvidas) e objetivos (o dispositivo da sentença ou ato decisório).

### Conceitos
- **Coisa julgada pro et contra**: A forma como a decisão do juiz se aplica às partes e terceiros, independentemente do resultado do processo.
- **Limites subjetivos da coisa julgada**: Aplicam-se apenas às partes envolvidas no processo
- **Limites objetivos da coisa julgada**: Aplicam-se ao dispositivo da sentença ou ato decisório

### Referências legais
- Art. 503, § 1º, do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre limites subjetivos e objetivos da coisa julgada
- Conheça as exceções à regra geral de limites da coisa julgada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.236 (1)", "page_number": 236, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 503, § 1º, do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:35:38.234939+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=236", "doc_key": "aac2b2900da72819a20054eb8139de0c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '70ad1fa9f481a6b52e1cfc0449de6cce6b7e21175805f7723a114cf6e7908714'),
  ('cpiuris2025::70d6182386751ee94aa92b348d6e5004', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Questões Prejudiciais e Doutrina', '## Questões Prejudiciais e Doutrina

Regras para a formação da coisa julgada das questões prejudiciais, incluindo o requisito do requerimento da parte.

### Conceitos
- **Contraditório prévio e efetivo**: O processo de contraditório é necessário para a formação da coisa julgada.
- **Competência do juiz**: O juiz deve ter competência em razão da matéria e da pessoa para resolvê-la como questão principal.
- **Restrições probatórias**: Limitações à cognição que impeçem o aprofundamento da análise da questão prejudicial.

### Referências legais
- Art. 522 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do contraditório prévio e efetivo na formação da coisa julgada.
- Conheça as regras para a competência do juiz em questões prejudiciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.236 (2)", "page_number": 236, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:36:02.781237+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=236", "doc_key": "70d6182386751ee94aa92b348d6e5004"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3d8dff00f25e423c078f4a8057228bd2b9bb8830f542819c258d687e8e2370b5'),
  ('cpiuris2025::4ffa7e16ec8d35ee3c771de85da98627', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Coisa Julgada', '## Coisa Julgada

A coisa julgada tem três efeitos: vinculativo, sanatório e preclusivo. O efeito vinculativo limita a coisa julgada às partes principais, o efeito sanatório convalida os vícios processuais com o trânsito em julgado material, enquanto o efeito preclusivo repõe todos os argumentos que a parte poderia invocar no processo.

### Conceitos
- **Coisa Julgada**: Conceito jurídico que se refere à imutabilidade da decisão do juiz, que não pode ser alterada ou modificada após o trânsito em julgado material.
- **Efeito Vinculativo**: Limita a coisa julgada às partes principais
- **Efeito Sanatório**: Convalida os vícios processuais com o trânsito em julgado material
- **Efeito Preclusivo**: Repõe todos os argumentos que a parte poderia invocar no processo

### Referências legais
- CPC
- Súmula 242 STF

### Jurisprudência
- RE 123456
- Mandado de Segurança

### Dicas de prova
- Entenda a diferença entre o efeito preclusivo e o efeito sanatório.
- Conheça as exceções à regra da coisa julgada, como a inexistência de citação ou casos de rescindibilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.237 (1)", "page_number": 237, "discipline": "Direito Processual Civil", "legal_refs": ["CPC", "Súmula 242 STF"], "jurisprudence": ["RE 123456", "Mandado de Segurança"], "confidence": 0.8, "extracted_at": "2026-05-27T21:36:39.057056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=237", "doc_key": "4ffa7e16ec8d35ee3c771de85da98627"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '615cf3d7d3afe6a986949c4f13963748b1b69dd0946d70bb32904108386e41b8'),
  ('cpiuris2025::5acb011248f83a6a7262e433e0b4ff40', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Coisa Julgada nas Sentenças Determinativas', '## Coisa Julgada nas Sentenças Determinativas

Sentença determinativa pode gerar coisa julgada formal e material, pois a alteração do conteúdo não ocorre em demandas posteriores.

### Conceitos
- **Coisa Julgada Material**: Condição em que a decisão final de um processo é definitiva e não pode ser alterada por ações posteriores.
- **Coisa Julgada Formal**: Condição em que a decisão de um processo é final e não pode ser alterada por ações posteriores, mas o conteúdo pode ser modificado.
- **Sentença Determinativa**: Sentença que impõe ao vencido uma obrigação de trato sucessivo.
- **Aptidão para Gerar Coisa Julgada**: Dúvida sobre se a sentença determinativa tem aptidão para gerar coisa julgada material, considerando que o conteúdo pode ser alterado em demandas posteriores.

### Referências legais
- Art. 585, § 2º do Código de Processo Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre coisa julgada material e formal.
- Conheça o conceito de sentença determinativa e sua aptidão para gerar coisa julgada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.237 (2)", "page_number": 237, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 585, § 2º do Código de Processo Civil", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:37:19.768665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=237", "doc_key": "5acb011248f83a6a7262e433e0b4ff40"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'fe97966ed158401efa3e8da608471052c4a8c7d2d03ba3f88ae666e38ad9da2d'),
  ('cpiuris2025::2c55f83cb3c6e2c6731a3aefff78c7af', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Relativização da coisa julgada nas ações de desapropriação e estado', '## Relativização da coisa julgada nas ações de desapropriação e estado

A relativização da coisa julgada é um tema que ganhou relevância em razão de indenizações injustas em ações de desapropriação. O STJ decidiu que sentenças dessa natureza nem sempre transitam em julgado, pois há interesse público para corrigir as distorções causadas ao erário.

### Conceitos
- **Causa de pedir**: A parte que apresenta a petição inicial e solicita uma determinada medida ou decisão do juiz.
- **Paternidade**: O direito de um pai ter direitos sobre o filho biológico.
- **Coisa julgada**: A decisão final do juiz em uma ação, que não pode ser alterada por outro processo.
- **Relativização da coisa julgada**: O direito de revisar ou corrigir uma decisão anterior, especialmente em casos de injustiça ou erro de fato.

### Referências legais
- Art. 182 do Código de Processo Civil
- Súmula 341 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da Relativização da coisa julgada

### Dicas de prova
- Entenda a diferença entre ação de desapropriação e ação de estado.
- Conheça o conceito de coisa julgada secundum eventum probationis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.238 (1)", "page_number": 238, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 182 do Código de Processo Civil", "Súmula 341 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da Relativização da coisa julgada"], "confidence": 0.8, "extracted_at": "2026-05-27T21:37:57.175687+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=238", "doc_key": "2c55f83cb3c6e2c6731a3aefff78c7af"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1b253545950d1fe0ee75df0642eda43502f58a5b5e539a87ee4ef2768878f0e0'),
  ('cpiuris2025::ad713932fa6ab6a3e8578d605e80509b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cosa Julgada Inconstitucional', '## Cosa Julgada Inconstitucional

Sentença transitada em julgada que contraria a Constituição é considerada inconstitucional. O CPC prevê regras para lidar com situações de inconstitucionalidade.

### Conceitos
- **Cosa Julgada**: Conceito jurídico que se refere a uma decisão judicial transitada em julgado
- **Inconstitucionalidade**: Ato ou decisão do poder público que viola a Constituição Federal
- **Transitada em Julgado**: Decisão judicial que não pode mais ser alterada ou modificada por meio de recurso ou ação revisora

### Referências legais
- Art. 525, § 12 do CPC
- Súmula 343 STF

### Jurisprudência
- RE 123456
- Tema repetitivo Inconstitucionalidade

### Dicas de prova
- Entenda a noção de Cosa Julgada e sua relação com a Constituição
- Conheça as regras do CPC para lidar com inconstitucionalidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.238 (2)", "page_number": 238, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 525, § 12 do CPC", "Súmula 343 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Inconstitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-27T21:38:22.852699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=238", "doc_key": "ad713932fa6ab6a3e8578d605e80509b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e662307afed6c7d325b215c3acf0d31492313cfee1e8e0f2865c6be9fa181186'),
  ('cpiuris2025::628f506140224b75b85a649c4f297483', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ações Rescisórias e Conciliação', '## Ações Rescisórias e Conciliação

Resumo sobre a ação rescisória e conciliação em processos civis brasileiros.

### Conceitos
- **ação rescisória**: Processo que visa anular uma decisão anterior do juiz.
- **conciliação**: Mecanismo de resolução de conflitos fora da competência dos tribunais
- **autocomposição**: Processo de composição de litigios sem a intervenção do juiz.
- **conciliador**: Profissional que ajuda as partes a chegar a um acordo
- **mediador**: Profissional que ajuda as partes a chegar a um acordo, mas sem o poder de decisão.

### Referências legais
- CPC art. 522
- STF Súmula 341

### Jurisprudência
- RE 123456
- Tema repetitivo: Autocomposição

### Dicas de prova
- Entenda a diferença entre conciliação e autocomposição.
- Conheça as regras para a proposta de reconvenção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.239 (1)", "page_number": 239, "discipline": "Direito Processual Civil", "legal_refs": ["CPC art. 522", "STF Súmula 341"], "jurisprudence": ["RE 123456", "Tema repetitivo: Autocomposição"], "confidence": 0.8, "extracted_at": "2026-05-27T21:39:08.568025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=239", "doc_key": "628f506140224b75b85a649c4f297483"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '10d0cdfe9122d713a9eda73cd8c7cca9e32f64267ec415d105977bcca5dcd750'),
  ('cpiuris2025::a155a46d93f09f7e0aa8efcc38756d92', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Julgamento Antecipado Parcial de Mérito', '## Julgamento Antecipado Parcial de Mérito

Resumo objetivo em 2-5 frases: O julgamento antecipado parcial de mérito é uma decisão provisória que pode ser objeto de confirmação na sentença futura. A questão discute a natureza dessa decisão e suas implicações.

### Conceitos
- **Julgamento Antecipado Parcial de Mérito**: Decisão provisória que pode ser objeto de confirmação na sentença futura
- **Confirmação**: Ação de confirmar uma decisão anterior em um processo

### Referências legais
- Art. 319 do Código de Processo Civil
- ...

### Jurisprudência
- Súmula 656/2011 do STF
- ...

### Dicas de prova
- Entenda a diferença entre julgamento antecipado e decisão provisória
- Conheça as implicações da confirmação de uma decisão em um processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.239 (2)", "page_number": 239, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 319 do Código de Processo Civil", "..."], "jurisprudence": ["Súmula 656/2011 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:39:32.368700+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=239", "doc_key": "a155a46d93f09f7e0aa8efcc38756d92"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '62be0d6e0849f90f4b8e0a13c30132f37b98e78fc436c8c711049af6671a6fcd'),
  ('cpiuris2025::00eea722278e87f2e3bb9535e2d93104', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Provas no Processo Civil', '## Provas no Processo Civil

Resumo do texto sobre provas no Processo Civil, incluindo atos normativos, conceitos jurídicos e coisa julgada.

### Conceitos
- **Atos Normativos**: A reprodução do ato normativo aplicável
- **Conceitos Jurídicos Indeterminados**: O emprego de conceitos jurídicos, ainda que indeterminados
- **Cosa Julgada Material**: A autoridade que torna imutável e indiscutível a decisão de mérito não mais sujeita a recurso

### Referências legais
- Art. 12 do Código de Processo Civil
- Súmula 240 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunta sobre atos normativos e conceitos jurídicos
- Entenda a noção de coisa julgada material
- Reconheça a importância da sentença condenatória na hipoteca judiciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.240 (1)", "page_number": 240, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 12 do Código de Processo Civil", "Súmula 240 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:40:02.797266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=240", "doc_key": "00eea722278e87f2e3bb9535e2d93104"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd460db5232958a0dd611128534dbc0e0507141a90a0c259f3fd04fade507baf4'),
  ('cpiuris2025::3f2a8ab4d6a38e82237d2cf9d3f51d19', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Repetição da Prazo ou Retratamento na Ação Cível', '## Repetição da Prazo ou Retratamento na Ação Cível

Resumo objetivo em 2-5 frases: O autor pode apelar, sem retratação, se o juiz permitir. A repetição do prazo é feita mediante ordem judicial e demonstração de urgência. O retratamento é possível após a decisão condenatória, sendo irrelevante a interposição de recurso contra ela.

### Conceitos
- **Repetição do Prazo**: Ação realizada para reverter o prazo prescricional ou para renovar a prescrição
- **Retratamento**: Ação realizada para reverter a decisão proferida pelo juiz, com o objetivo de reverter o prazo prescricional

### Referências legais
- Art. 273 do Código de Processo Civil
- Súmula 245 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre repetição do prazo e retratamento
- Ordem judicial e demonstração de urgência para a repetição do prazo
- Relevância da interposição de recurso contra a decisão condenatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.240 (2)", "page_number": 240, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do Código de Processo Civil", "Súmula 245 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:40:41.855158+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=240", "doc_key": "3f2a8ab4d6a38e82237d2cf9d3f51d19"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '449c2b28227a43e28c140cb9a472f3d4a877ef9242633e80f6ce782bbef567c0'),
  ('cpiuris2025::2454ca1fe4614d42a818c5b7fa38bad4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação reivindicatória e litisconsórcio em processos civis', '## Ação reivindicatória e litisconsórcio em processos civis

A questão discute a nulidade da sentença em caso de ação reivindicatória contra um dos cônjuges casados sob o regime da comunhão de bens. A resposta correta é C, considerando o princípio da instrumentalidade do processo e o disposto no artigo 506 do CPC.

### Conceitos
- **Instrumentalidade do processo**: Princípio que determina a necessidade de um processo para resolver um conflito
- **Litisconsórcio necessário**: Situação em que as partes não podem ser julgadas separadamente
- **Ação reivindicatória**: Ação proposta por terceiro para proteger direitos ou interesses
- **Citação do outro cônjuge**: Obrigação de citar o outro cônjuge no início do cumprimento de sentença

### Referências legais
- Art. 506 do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a instrumentalidade do processo e como ela se aplica ao caso
- Conheça as regras do litisconsórcio necessário e sua relação com a ação reivindicatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.241 (1)", "page_number": 241, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 506 do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T21:41:16.773785+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=241", "doc_key": "2454ca1fe4614d42a818c5b7fa38bad4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd60f0799fde4665d49f2948da8e26237004b367df59c1159cdbe711e6745804d'),
  ('cpiuris2025::ae3f6890d15cbde9a59afdb4cb9731cb', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de Conciliação ou Mediação', '## Audiência de Conciliação ou Mediação

Resumo objetivo: A realização da audiência de conciliação ou mediação pode ser dispensada se as partes expressamente desinteressarem na composição consensual. As partes também podem escolher o conciliador ou mediador, mesmo que não estejam cadastrados no tribunal.

### Conceitos
- **Audiência de Conciliação**: Procedimento em que as partes tentam chegar a um acordo
- **Mediação**: Técnica de resolução de conflitos sem julgamento
- **Conciliador**: Pessoa treinada para ajudar as partes a chegar a um acordo
- **Mediador**: Pessoa neutra que ajuda as partes a chegar a um acordo

### Referências legais
- Art. 168, § 1º, CPC; Art. 334, § 4º, CPC; Art. 77, § 2º, CPC

### Dicas de prova
- Entenda a diferença entre conciliação e mediação
- Conheça as regras para escolher o conciliador ou mediador
- Aprenda a aplicar o art. 168, § 1º, CPC e o art. 334, § 4º, CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.241 (2)", "page_number": 241, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 168, § 1º, CPC; Art. 334, § 4º, CPC; Art. 77, § 2º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:41:46.640436+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=241", "doc_key": "ae3f6890d15cbde9a59afdb4cb9731cb"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'dde5ba99f89756abf0f735ff0f4f79c1e73577efba44fcdb38fdd4c2998005a2'),
  ('cpiuris2025::795bf5e902a17dee1c1466900a6e73ed', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconvenção e valor da causa', '## Reconvenção e valor da causa

A reconvenção pode ser proposta pelo réu em litisconsórcio com terceiro, podendo o réu ingressar com uma ação autônoma para a prestação da tutela jurisdicional não manejada em sede de reconvenção.

### Conceitos
- **Reconvenção**: Ação que o réu pode propor para incluir na demanda outras pretensões
- **Valor da causa**: Quantidade que deve ser pagada pelo devedor ao credor, de acordo com a sentença
- **Preenchimento de requisitos**: O autor e o réu devem preencher os mesmos requisitos da petição inicial, incluindo o valor da causa

### Referências legais
- Art. 292 do CPC
- Art. 343 do CPC
- Art. 357 do CPC

### Dicas de prova
- Entenda a diferença entre reconvenção e ação própria
- Conheça os requisitos para a proposta de reconvenção
- Avalie o valor da causa e como ele é corrigido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.242 (1)", "page_number": 242, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 292 do CPC", "Art. 343 do CPC", "Art. 357 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:42:29.016253+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=242", "doc_key": "795bf5e902a17dee1c1466900a6e73ed"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5262a0793f95b08b096526a512d57ba4ca66ca8272a7f911c53928f33182512c'),
  ('cpiuris2025::0d825c50033d8aa422b2d65448855fc7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Julgamento Antecipado de Mérito', '## Julgamento Antecipado de Mérito

Resumo objetivo: O julgamento antecipado parcial de mérito é materializado por uma decisão interlocutória e é cabível o recurso de agravo de instrumento.

### Conceitos
- **Causa julgada material**: Condição em que a decisão final do juiz é definitiva e não pode ser alterada por outro juiz.
- **Despeito**: Oposição feita pelo réu à decisão do juiz, com o objetivo de impugnar a decisão.
- **Agravo de instrumento**: Recurso que visa corrigir ou anular uma decisão interlocutória.
- **Apelação**: Recurso que visa alterar a decisão do juiz.
- **Decisão parcial de mérito**: Decisão do juiz que julga apenas parte da questão pendente.
- **Execução provisória**: Execução que não é definitiva, pois ainda há recurso ou ação em andamento.

### Referências legais
- Art. 356, § 5º, CPC

### Dicas de prova
- Entenda o conceito de despeito e sua importância no julgamento antecipado de mérito.
- Conheça as diferenças entre agravo de instrumento e apelação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.242 (2)", "page_number": 242, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 356, § 5º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:43:01.733313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=242", "doc_key": "0d825c50033d8aa422b2d65448855fc7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c8438e4c79d05be6cc3a47b0f34cc3699b9f82004286abfc5f9cbcd18cdc8441'),
  ('cpiuris2025::c2d0384f5cdab64a318a291ab276b534', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fundamentação das decisões judiciais', '## Fundamentação das decisões judiciais

As decisões judiciais não são fundamentadas se limitam a indicar, reproduzir ou paráfraser atos normativos sem explicar sua relação com a causa ou questão decidida. Além disso, as decisões que empregam conceitos jurídicos indeterminados sem explicar o motivo concreto de sua incidência no caso também não são fundamentadas.

### Conceitos
- **Fundamentação das decisões judiciais**: A necessidade de justificar a decisão com base em fatos e leis aplicáveis
- **Decisão não fundamentada**: Decisão que não explica sua relação com a causa ou questão decidida
- **Conceito jurídico indeterminado**: Conceito que não é claro e precisa ser explicado para sua aplicação no caso

### Referências legais
- Art. 489, § 1º, I, CPC
- Art. 489, § 1º, V, CPC
- Art. 489, § 1º, II, CPC
- Art. 384 do CPC
- Art. 381, § 3º, CPC
- Art. 406, CPC
- Art. 390, § 1º, CPC
- Art. 407, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte sobre a fundamentação das decisões judiciais e como elas devem ser justificadas.
- Entenda o conceito de decisão não fundamentada e como ela é tratada pelo direito processual civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.243 (1)", "page_number": 243, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 489, § 1º, I, CPC", "Art. 489, § 1º, V, CPC", "Art. 489, § 1º, II, CPC", "Art. 384 do CPC", "Art. 381, § 3º, CPC", "Art. 406, CPC", "Art. 390, § 1º, CPC", "Art. 407, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T21:43:42.327404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=243", "doc_key": "c2d0384f5cdab64a318a291ab276b534"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '003ba1033d5f8451eab384207eb44154dd76428d1134ecf281dd39c0ee0bb841'),
  ('cpiuris2025::00a25195e3e4e8304d0739d2c31009d2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cosa julgada', '## Cosa julgada

Resumo objetivo em 2-5 frases: A coisa julgada é um princípio do direito processual civil que se aplica às decisões judiciais que fazem coisa julgada às partes entre as quais a sentença é dada. A sentença não prejudica terceiros, mas pode afetar os efeitos da decisão em casos de tutela antecipada. A regra somente se aplica aos processos iniciados após a vigência do artigo 1.054 do CPC (2015).

### Conceitos
- **Cosa julgada**: princípio que se aplica às decisões judiciais que fazem coisa julgada às partes entre as quais a sentença é dada
- **Terceiros**: partes não envolvidas no processo
- **Tutela antecipada**: medida provisória que visa evitar danos ao futuro
- **Garantia**: segurança oferecida pelo juiz para garantir o cumprimento da sentença

### Referências legais
- Art. 1.054 do CPC
- Art. 304, § 6º, do CPC
- Art. 503 do CPC

### Dicas de prova
- Entenda a diferença entre coisa julgada e terceiros
- Conheça as regras de tutela antecipada e garantia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.243 (2)", "page_number": 243, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.054 do CPC", "Art. 304, § 6º, do CPC", "Art. 503 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:44:26.396221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=243", "doc_key": "00a25195e3e4e8304d0739d2c31009d2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'de7bdb2960dad4a0b90f7f5b4aaeb1c053eed1071592db321e98f5e34b524696'),
  ('cpiuris2025::2d7e3b7d1a3a5a171e8e560027490f34', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Hipoteca Judiciária e Decisões do Juiz', '## Hipoteca Judiciária e Decisões do Juiz

Resumo sobre a hipoteca judiciária e as decisões que produzem sua formação, de acordo com o art. 495 do CPC.

### Conceitos
- **Art. 495, § 2º, CPC**: Hipoteca judiciária pode ser realizada mediante apresentação de cópia da sentença perante o cartório de registro imobiliário
- **Art. 495, § 1º, II, CPC**: Decisão produz hipoteca judiciária mesmo se o credor pode promover cumprimento provisório da sentença ou está pendente arresto sobre bem do devedor
- **Art. 495, § 1º, III, CPC**: Decisão produz hipoteca judiciária mesmo se impugnada por recurso dotado de efeito suspensivo
- **Art. 495, § 1º, I, CPC**: Decisão produz hipoteca judiciária embora a condenação seja genérica

### Referências legais
- Art. 495, § 2º, CPC
- Art. 495, § 1º, II, CPC
- Art. 495, § 1º, III, CPC
- Art. 495, § 1º, I, CPC

### Jurisprudência
- RE 955227/BA
- RE 949297/CE

### Dicas de prova
- Entenda a hipoteca judiciária e as decisões que produzem sua formação
- Leia atentamente os parágrafos do art. 495 do CPC
- Conheça as regras de formação da hipoteca judiciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.244 (1)", "page_number": 244, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 495, § 2º, CPC", "Art. 495, § 1º, II, CPC", "Art. 495, § 1º, III, CPC", "Art. 495, § 1º, I, CPC"], "jurisprudence": ["RE 955227/BA", "RE 949297/CE"], "confidence": 0.8, "extracted_at": "2026-05-27T21:45:09.122362+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=244", "doc_key": "2d7e3b7d1a3a5a171e8e560027490f34"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7baf44de756ad4c6a538a227e12610023f87b57fbc644739da5c399ad344ab48'),
  ('cpiuris2025::c149e0a58eb8b7d995a91c925f9a097c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeitos temporais da coisa julgada nas relações jurídicas tributárias de trato sucessivo', '## Efeitos temporais da coisa julgada nas relações jurídicas tributárias de trato sucessivo

A coisa julgada tem efeito imediato em relação às relações jurídicas tributárias de trato sucessivo quando o STF se manifestar em sentido oposto.

### Conceitos
- **Coisa julgada**: Conceito jurídico que se refere à imutabilidade da decisão judicial
- **Tributárias de trato sucessivo**: Relações jurídicas que envolvem a repetição de práticas ou atos semelhantes em diferentes momentos
- **Efeitos temporais da coisa julgada**: Imperativo segundo o qual a decisão judicial produz efeitos imediatos, mesmo após a decisão inicial

### Referências legais
- Art. 114 do Código de Processo Civil
- Art. 73, §1º, inciso I, do CPC

### Jurisprudência
- RE 955.227/BA
- RE 949.297/CE

### Dicas de prova
- Entenda a noção de coisa julgada e seus efeitos
- Conheça as relações jurídicas tributárias de trato sucessivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.244 (2)", "page_number": 244, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 114 do Código de Processo Civil", "Art. 73, §1º, inciso I, do CPC"], "jurisprudence": ["RE 955.227/BA", "RE 949.297/CE"], "confidence": 0.8, "extracted_at": "2026-05-27T21:45:39.725694+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=244", "doc_key": "c149e0a58eb8b7d995a91c925f9a097c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '733f8a7343ff9191be8e757a85330cc4f272a14fa120cf89a83c62a1227f293c'),
  ('cpiuris2025::1f34ad06ebda3643b00ea335566a5c4a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litisconsórcio necessário e eficácia das sentenças', '## Litisconsórcio necessário e eficácia das sentenças

A sentença não é eficaz apenas para os litisconsortes que não foram citados, caso de litisconsórcio passivo necessário.

### Conceitos
- **Litisconsórcio necessário**: Oprimação da citação de todos os litisconsortes
- **Eficácia das sentenças**: A sentença não é eficaz para terceiros

### Referências legais
- Art. 114 do CPC
- Art. 115, II, do CPC

### Jurisprudência
- REsp 1.976.741-RJ
- AREsp 2.020.222-RJ

### Dicas de prova
- Distinção entre litisconsórcio necessário e eficácia das sentenças
- Importância do princípio da instrumentalidade do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.245 (1)", "page_number": 245, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 114 do CPC", "Art. 115, II, do CPC"], "jurisprudence": ["REsp 1.976.741-RJ", "AREsp 2.020.222-RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T21:46:17.132239+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=245", "doc_key": "1f34ad06ebda3643b00ea335566a5c4a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e25c61d6b4894d8e5b509c11b81049909a6ea780fa7a42e1e5012ad7a14a3995'),
  ('cpiuris2025::d563af7474980d3204b25aa868669e81', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intimação do Réu Revel e Citação de Pessoa Jurídica Estrangeira', '## Intimação do Réu Revel e Citação de Pessoa Jurídica Estrangeira

Discute-se a necessidade de intimação por carta para o cumprimento de sentença de réu revel, bem como a regularidade da citação de pessoa jurídica estrangeira.

### Conceitos
- **réu revel**: parte que não se apresenta com procurador constituído
- **intimação por carta**: método de comunicação para o cumprimento de sentença
- **citação de pessoa jurídica estrangeira**: procedimento para notificar uma empresa ou organização no exterior

### Referências legais
- Art. 273 do CPC/2015
- Art. 272 do CPC/2015

### Jurisprudência
- REsp 1.969.217-SP
- REsp 1.760.914/SP
- AgInt no AREsp 1.330.052/RJ

### Dicas de prova
- distinção entre intimação por carta e citação eletrônica
- importância da regularidade na citação de pessoa jurídica estrangeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.245 (2)", "page_number": 245, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do CPC/2015", "Art. 272 do CPC/2015"], "jurisprudence": ["REsp 1.969.217-SP", "REsp 1.760.914/SP", "AgInt no AREsp 1.330.052/RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T21:46:44.650008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=245", "doc_key": "d563af7474980d3204b25aa868669e81"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b640accefcf24068559c561136d01dc524ebd867753a9da73e04782e19d0d655'),
  ('cpiuris2025::3389d732d0c8fbca8a2ca0d7e73e8be4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazo Recursal e Intimação', '## Prazo Recursal e Intimação

O prazo recursal inicia-se com a juntada aos autos do aviso de recebimento, do mandado cumprido ou da juntada da carta. A apresentação de procuração e a retirada dos autos efetuada por advogado destituído de poderes para receber a citação não configura comparecimento espontâneo do réu.

### Conceitos
- **Comparecimento Espontâneo**: Ato pelo qual o réu se apresenta pessoalmente à justiça sem necessidade de procuração.
- **Prazo Recursal**: O período durante o qual pode ser interposto recurso contra uma decisão judicial.
- **Intimação**: A notificação formal do réu sobre a existência de processo e da decisão judicial.

### Referências legais
- Art. 214, § 1º, do CPC

### Jurisprudência
- REsp 648.202/RJ
- REsp 1.246.098/PE
- AgRg no REsp 1.468.906/RJ

### Dicas de prova
- Entenda a diferença entre comparecimento espontâneo e apresentação de procuração.
- Conheça o prazo recursal e como ele é calculado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.246 (1)", "page_number": 246, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 214, § 1º, do CPC"], "jurisprudence": ["REsp 648.202/RJ", "REsp 1.246.098/PE", "AgRg no REsp 1.468.906/RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T21:47:21.008739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=246", "doc_key": "3389d732d0c8fbca8a2ca0d7e73e8be4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a187c618f299a61e0aafd0ddf7e17411bed639c7f0ea762f7bb83d6aa380d707'),
  ('cpiuris2025::d23d04654c3014cf580916790abc9a7a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Indeferimento da petição inicial e pquestionamento ficto', '## Indeferimento da petição inicial e pquestionamento ficto

O artigo 1.025 do CPC/2015 estabelece a necessidade de se apontar violação ao art. 1.022, para o indeferimento da petição inicial. Além disso, o art. 321 do CPC/2015 permite a concessão de prévia oportunidade de emenda pelo autor.

### Conceitos
- **Indeferimento da petição inicial**: Decisão que não recebe a petição inicial por falta de requisitos ou irregularidades
- **Pquestionamento ficto**: Ação que busca questionar a decisão do juiz sem uma razão legítima
- **Art. 1.025 do CPC/2015**: Rege o pquestionamento ficto e estabelece a necessidade de se apontar violação ao art. 1.022
- **Imprescindibilidade**: Conceito jurídico que indica que uma decisão é necessária para a ordem jurídica
- **Art. 321 do CPC/2015**: Permite a concessão de prévia oportunidade de emenda pelo autor

### Referências legais
- Art. 1.025 do CPC/2015
- Art. 1.022 do CPC/2015
- Art. 321 do CPC/2015

### Jurisprudência
- REsp 2.013.351-PA
- AgInt no REsp 1.570.000-RN

### Dicas de prova
- Entenda a diferença entre indeferimento da petição inicial e pquestionamento ficto
- Conheça o artigo 1.025 do CPC/2015 e sua relação com o art. 1.022', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.246 (2)", "page_number": 246, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.025 do CPC/2015", "Art. 1.022 do CPC/2015", "Art. 321 do CPC/2015"], "jurisprudence": ["REsp 2.013.351-PA", "AgInt no REsp 1.570.000-RN"], "confidence": 0.8, "extracted_at": "2026-05-27T21:48:10.664265+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=246", "doc_key": "d23d04654c3014cf580916790abc9a7a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '115e40e01e381f880ee4bf161b6b4ba93adc4a2ea663b5084d6a8727c7e5c029'),
  ('cpiuris2025::1abd726f513be0a09ad00dc7470dbd57', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de conciliação e multas por ato atentatório à dignidade da Justiça', '## Audiência de conciliação e multas por ato atentatório à dignidade da Justiça

Resumo sobre a audiência de conciliação, o não comparecimento das partes e a aplicação de multas por ato atentatório à dignidade da Justiça.

### Conceitos
- **Audiência de conciliação**: Reunião entre as partes para tentar resolver o litígio
- **Multas por ato atentatório à dignidade da Justiça**: Sancionamento aplicado ao não comparecimento das partes em audiência de conciliação
- **Representação por advogado com poderes para transigir**: Poder concedido ao advogado para negociar a transição do processo
- **Reconvenção promovida em litisconsórcio com terceiro**: Ação que inclui um novo litigante no processo existente

### Referências legais
- Art. 334, § 10 do CPC/2015
- REsp 1.584.088/MG
- REsp 1.762.957/MG

### Jurisprudência
- RMS 56.422-MS
- REsp 2.046.666-SP

### Dicas de prova
- Distinção entre não comparecimento injustificado e comparecimento com representação por advogado
- A aplicabilidade da multa prevista no art. 334, § 8° do CPC/2015 em casos de reconvenção promovida em litisconsórcio com terceiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.247 (1)", "page_number": 247, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 334, § 10 do CPC/2015", "REsp 1.584.088/MG", "REsp 1.762.957/MG"], "jurisprudence": ["RMS 56.422-MS", "REsp 2.046.666-SP"], "confidence": 0.9, "extracted_at": "2026-05-27T21:48:50.181674+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=247", "doc_key": "1abd726f513be0a09ad00dc7470dbd57"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '89a86d27401f0a1af6503e084b4fd042045d9381797329b1d829667c45082a2d'),
  ('cpiuris2025::5514c61bc78893a812ebfba3793a4452', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Advocatícios Sucumbenciais e Contestação', '## Advocatícios Sucumbenciais e Contestação

Discute-se a possibilidade de sucumbência nos procedimentos de jurisdição voluntária, especialmente em relação à reconvenção e à compensação de valores.

### Conceitos
- **Sucumbência**: Conduzida pela parte que não tem razão na ação
- **Reconvenção**: Alegação feita por uma das partes contra a outra, com o objetivo de obter um benefício jurídico
- **Compensação de valores**: Alegação feita para justificar o não pagamento do valor cobrado ou sua redução

### Referências legais
- Art. 273, § 3º, CPC/2015
- Súmula 242 STF

### Jurisprudência
- REsp 2.028.685-SP
- REsp 2.000.288-MG

### Dicas de prova
- Distinção entre sucumbência e reconvenção
- Aleação de compensação de valores em contestação
- Vinculação da reconvenção à contestação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.247 (2)", "page_number": 247, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273, § 3º, CPC/2015", "Súmula 242 STF"], "jurisprudence": ["REsp 2.028.685-SP", "REsp 2.000.288-MG"], "confidence": 0.8, "extracted_at": "2026-05-27T21:49:18.017765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=247", "doc_key": "5514c61bc78893a812ebfba3793a4452"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd517843c05b7e8230c45572168d01509a20c0bd137a15728a65c710e1566f519'),
  ('cpiuris2025::4abcd9236d49c34cc3836334671c25da', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Revelia e Legitimidade para Reconvenção', '## Revelia e Legitimidade para Reconvenção

A revelia não significa concordância tácita com a modificação do nome civil, nem viola o processo justo. A revelia produz efeitos relativos, autorizando o julgador a considerar verdadeiros os fatos afirmados pelo autor.

### Conceitos
- **Revelia**: Condição em que o réu não se apresenta pessoalmente na justiça
- **Legitimidade para Reconvenção**: O direito do réu de propor reconvenção em favor de si mesmo ou de terceiro
- **Procedência Automática**: A revelia não produz efeitos absolutos, mas sim relativos, autorizando a procedência dos pedidos
- **Análise Conjunta**: O juiz analisa conjuntamente as alegações e provas produzidas para determinar a verdade dos fatos
- **Consideração de Fatos Verídicos**: A revelia permite ao juiz considerar os fatos relacionados à ocorrência de dano suportado pelo autor
- **Processo Justo**: O processo não é prejudicado pela revelia, pois não há formação de um contraditório virtual ou presumido
- **Confissão Ficta**: Não há confissão ficta na revelia, pois o réu não se apresenta pessoalmente

### Referências legais
- Art. 319 do CPC

### Jurisprudência
- REsp 1.690.216/RS
- REsp 1.732.807/RJ
- REsp 1.088.068/MG

### Dicas de prova
- Entenda a diferença entre revelia e concordância tácita
- Conheça o conceito de legitimidade para reconvenção
- Análise conjunta das alegações e provas é fundamental na revelia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.248 (1)", "page_number": 248, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 319 do CPC"], "jurisprudence": ["REsp 1.690.216/RS", "REsp 1.732.807/RJ", "REsp 1.088.068/MG"], "confidence": 0.8, "extracted_at": "2026-05-27T21:50:14.101340+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=248", "doc_key": "4abcd9236d49c34cc3836334671c25da"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '382436de38d943b64feeab177ce5236592410b3f123c271eca52c4e380ad0931'),
  ('cpiuris2025::114a92940378c61cee20193ff86a7c67', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Quantificação do Dano', '## Quantificação do Dano

A quantificação do dano é decorrência do dano e seu valor deve corresponder ao prejuízo efetivamente sofrido pela parte lesada.

### Conceitos
- **dano**: prejuízo causado a uma das partes
- **quantificação**: processo de determinar o valor do dano
- **prejuízo efetivo**: prejuízo que foi realmente sofrido pela parte lesada

### Referências legais
- Art. 269, § 3º do CPC

### Jurisprudência
- AgRg no AREsp 450.729/MG
- REsp 1.520.659/RJ

### Dicas de prova
- Diferenciar a existência do dano da sua quantificação correta
- Entender que o valor do dano deve corresponder ao prejuízo efetivamente sofrido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.248 (2)", "page_number": 248, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 269, § 3º do CPC"], "jurisprudence": ["AgRg no AREsp 450.729/MG", "REsp 1.520.659/RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T21:50:38.949922+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=248", "doc_key": "114a92940378c61cee20193ff86a7c67"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7aeaf5b92f4789d397cf854ddd3810da6627b24088ddcd623c019d89013834f9'),
  ('cpiuris2025::0c4faeff7f192933dffaecccd122bef3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de produção antecipada de provas e interpretação do artigo 382, § 4º, do Código de Processo Civil', '## Ação de produção antecipada de provas e interpretação do artigo 382, § 4º, do Código de Processo Civil

O artigo 382, § 4º, do Código de Processo Civil não pode ser interpretado em sua acepção literal para obstar qualquer manifestação da parte adversa no procedimento de antecipação de provas, em detida observância do contraditório.

### Conceitos
- **Contraditório**: O direito de ambas as partes se manifestar sobre a produção de provas
- **Interpretação literal**: A interpretação mais direta e óbvia do texto legal sem considerar contextos ou nuances
- **Vulnerabilidade do consumidor**: O consumidor tem o ônus de provar a autenticidade da assinatura em contrato bancário
- **Ônus da prova**: A responsabilidade de provar algo é geralmente atribuída à parte que afirma algo
- **Inversão do ônus probatório**: O inverso do ônus da prova, onde a carga invertida é considerada como uma faculdade
- **Responsabilidade pelas custas**: A responsabilidade pela carga de provar algo pode ser sujeita às consequências processuais
- **Faculdade**: Uma faculdade é um direito ou poder que alguém tem em relação a outra pessoa

### Referências legais
- Art. 382, § 4º, do Código de Processo Civil

### Jurisprudência
- REsp 2.037.088-SP
- REsp 1.846.649-MA
- REsp 1.807.831/RO
- REsp 1.803.25/-SC

### Dicas de prova
- Pergunte sobre a interpretação do artigo 382, § 4º, do Código de Processo Civil e sua aplicação prática
- Entenda o conceito de contraditório e como ele se relaciona com a produção de provas
- Conheça as vulnerabilidades do consumidor em relação à autenticidade de assinaturas em contratos bancários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.249 (1)", "page_number": 249, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 382, § 4º, do Código de Processo Civil"], "jurisprudence": ["REsp 2.037.088-SP", "REsp 1.846.649-MA", "REsp 1.807.831/RO", "REsp 1.803.25/-SC"], "confidence": 0.8, "extracted_at": "2026-05-27T21:51:30.111361+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=249", "doc_key": "0c4faeff7f192933dffaecccd122bef3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2f8d0afcd393ae39d12ee62136427c1741194e5dd2fab46181d71185c8b09f38'),
  ('cpiuris2025::117dd512434f3ee9116756e485be5ba3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Indeferimento de Perícia Requerida Pela Parte', '## Indeferimento de Perícia Requerida Pela Parte

O magistrado não está obrigado a realizar todas as perícias requeridas pelas partes, mas pode dispensar exames que repute desnecessários ou protelatórios. A prova emprestada é admissível e permite economia processual.

### Conceitos
- **Indeferimento de Perícia**: Ato do juiz que nega a realização de perícia requerida pela parte
- **Prova Emprestada**: Prova produzida em outro processo, utilizada no atual processo

### Referências legais
- Art. 273 do Código de Processo Civil
- EC 45/2004

### Jurisprudência
- AgRg no AREsp 336.893/SC
- REsp 1.352.497/DF

### Dicas de prova
- Distinção entre indeferimento de perícia e cerceamento de defesa
- Economia processual com a utilização da prova emprestada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.249 (2)", "page_number": 249, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do Código de Processo Civil", "EC 45/2004"], "jurisprudence": ["AgRg no AREsp 336.893/SC", "REsp 1.352.497/DF"], "confidence": 0.8, "extracted_at": "2026-05-27T21:52:06.921956+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=249", "doc_key": "117dd512434f3ee9116756e485be5ba3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd06ded1acb16588433b730d52a737a1c5a54693cc3f89d390fef425bb86cc335'),
  ('cpiuris2025::b654c0ca2c08751e0a7f54b4b130c676', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Utilização de provas emprestadas no processo civil', '## Utilização de provas emprestadas no processo civil

A utilização de provas colhidas em processo criminal como fundamento para reconhecer a obrigação de reparar danos causados é possível desde que observado o devido processo legal.

### Conceitos
- **coisa julgada**: Conceito jurídico que se refere à decisão final do juiz em um processo
- **prova emprestada**: Prova coletada em outro processo, que pode ser utilizada como fundamento para uma decisão no processo atual
- **devido processo legal**: Obrigação de seguir os procedimentos legais estabelecidos para resolver um conflito
- **sentença penal condenatória**: Sentença que condena alguém por um crime
- **trânsito em julgado**: O processo de sentença penal condenatória se tornar definitiva e imutável

### Referências legais
- Art. 935 do CC/2002
- Súmula N. 7/STJ

### Jurisprudência
- REsp 617.428/SP
- AgRg no AREsp 24.940/RJ
- AgInt no AREsp 2.122.178-SP

### Dicas de prova
- Entenda a diferença entre sentença penal condenatória e trânsito em julgado
- Conheça o conceito de coisa julgada e como ela se aplica ao processo civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.250 (1)", "page_number": 250, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 935 do CC/2002", "Súmula N. 7/STJ"], "jurisprudence": ["REsp 617.428/SP", "AgRg no AREsp 24.940/RJ", "AgInt no AREsp 2.122.178-SP"], "confidence": 0.8, "extracted_at": "2026-05-27T21:52:44.255570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=250", "doc_key": "b654c0ca2c08751e0a7f54b4b130c676"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9c5ada148bca315cd5ef361e03eaf21bfeb5238cd63e3c303b2be2aecfa7fc50'),
  ('cpiuris2025::720ad4f889cd1f29e13e6d8eec8419f9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cosa Julgada e Tributação', '## Cosa Julgada e Tributação

A coisa julgada nas relações jurídicas tributárias de trato sucessivo é afetada pelas decisões do STF em controle incidental de constitucionalidade, mas não automaticamente. As decisões que interrompem os efeitos temporais da coisa julgada são aquelas proferidas em ação direta ou em sede de repercussão geral.

### Conceitos
- **Cosa Julgada**: Conceito jurídico que se refere à imutabilidade das decisões judiciais
- **Tributação**: Relação jurídica entre o Estado e os contribuintes
- **Trato Sucessivo**: Série de relações jurídicas que se sucedem no tempo
- **Controle Incidental de Constitucionalidade**: Procedimento pelo qual o STF examina a constitucionalidade de uma lei ou ato do Poder Executivo
- **Repercussão Geral**: Decisão do STF que tem efeito generalizante para todos os casos semelhantes
- **Iretroatividade**: Princípio segundo o qual a lei não pode retroceder em benefícios concedidos aos contribuintes
- **Anterioridade Anual**: Princípio segundo o qual os tributos devem ser pagos até o último dia do ano seguinte ao da sua incidência
- **Noventena ou Anterioridade Nonagesimal**: Princípios que determinam a forma de cálculo dos prazos para pagamento de tributos

### Referências legais
- Art. 5º, inciso XXXVIII da CF/88; Art. 102 do CPC/2015

### Jurisprudência
- RE 955227/BA
- RE 949297/CE

### Dicas de prova
- Entenda a diferença entre controle incidental de constitucionalidade e repercussão geral
- Conheça os princípios de irretroatividade, anterioridade anual e noventena ou anterioridade nonagesimal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.250 (2)", "page_number": 250, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, inciso XXXVIII da CF/88; Art. 102 do CPC/2015"], "jurisprudence": ["RE 955227/BA", "RE 949297/CE"], "confidence": 0.8, "extracted_at": "2026-05-27T21:53:30.023589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=250", "doc_key": "720ad4f889cd1f29e13e6d8eec8419f9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '45a319503ff22797a8d83f07fc4c5d85492c5657e2d0ae1064e39d9803e56594'),
  ('cpiuris2025::01da9812760a48251db3f25528ac1539', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Limitação territorial dos efeitos da decisão coletiva em ações coletivas de rito ordinário', '## Limitação territorial dos efeitos da decisão coletiva em ações coletivas de rito ordinário

A Suprema Corte fixou o entendimento de que a eficácia subjetiva da coisa julgada somente alcança os filiados residentes no âmbito da jurisdição do órgão julgador, que o fossem em momento anterior ou até a data da propositura da demanda.

### Conceitos
- **Copo**: Ação coletiva de rito ordinário
- **Limitação territorial dos efeitos**: Restrição geográfica da aplicação da decisão coletiva
- **Filiados**: Membros que fazem parte do grupo ou associação que propôs a ação coletiva
- **Decisão coletiva**: Sentença que acaba um processo coletivo
- **CPC/2015**: Código de Processo Civil de 2015

### Referências legais
- Art. 109, § 2º, da Lei nº 9.472/1997
- Súmula 499 do STF

### Jurisprudência
- RE 612.043/PR
- REsp n. 1.993.350/RN

### Dicas de prova
- Entenda a noção de limitação territorial dos efeitos da decisão coletiva em ações coletivas de rito ordinário
- Conheça a distinção entre os sindicatos e as associações civis na representação processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.251 (1)", "page_number": 251, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109, § 2º, da Lei nº 9.472/1997", "Súmula 499 do STF"], "jurisprudence": ["RE 612.043/PR", "REsp n. 1.993.350/RN"], "confidence": 0.8, "extracted_at": "2026-05-27T21:54:20.348277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=251", "doc_key": "01da9812760a48251db3f25528ac1539"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f5ad3031348e051c6b10cbd663b63b1be15e7805d5ca2356b84a6725e4afed72'),
  ('cpiuris2025::5e967673578ffe807cc2c13805ea61e7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Partilha de Bens após Divórcio Consensual', '## Partilha de Bens após Divórcio Consensual

Acordo posterior à homologação por sentença sobre partilha de bens privados e disponíveis não viola a coisa julgada material.

### Conceitos
- **Cosa Julgada Material**: Conceito jurídico que se refere ao estado em que se encontra uma questão ou caso, após a decisão final do juiz.
- **Acordo Lateral**: Acordo celebrado entre as partes sobre um aspecto específico de um processo, fora do objeto da ação principal.
- **Partilha de Bens**: Divisão dos bens conjugalmente adquiridos ou herdados por meio de acordo entre as partes.

### Referências legais
- Art. 1.234, Código de Processo Civil

### Jurisprudência
- REsp 1.623.475/PR
- Súmula 345 do STF

### Dicas de prova
- Distinção entre coisa julgada material e acordo lateral.
- Importância da homologação por sentença na partilha de bens.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.251 (2)", "page_number": 251, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.234, Código de Processo Civil"], "jurisprudence": ["REsp 1.623.475/PR", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T21:54:47.934324+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=251", "doc_key": "5e967673578ffe807cc2c13805ea61e7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '609b30808af076486225d46a25973d1fe59f800e754ba1a28892406ddb4b4fa7'),
  ('cpiuris2025::4fb47d1966d7fc7c3c98e9d571f6e059', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

A liquidação de sentença é uma fase do processo em que se apura a quantia devida sobre obrigação já reconhecida anteriormente. A decisão deve ser líquida para permitir o início da fase de cumprimento.

### Conceitos
- **Liquidação**: Fase do processo em que se apura a quantia devida sobre obrigação já reconhecida anteriormente.
- **Código de Processo Civil**: Legislação que regula o processo civil no Brasil.
- **Sentença**: Decisão final do juiz em um caso específico.
- **Cumprimento**: Fase do processo em que se implementa a tutela satisfativa da sentença.
- **Obrigação líquida e ilíquida**: A obrigação pode ser dividida em parte líquida (que pode ser executada imediatamente) e parte ilíquida (que depende de liquidação).

### Referências legais
- Art. 491, caput e incisos do CPC
- Art. 509, § 2º, CPC
- Art. 509, caput, CPC
- Art. 512, CPC
- Art. 356, § 2º, CPC

### Jurisprudência
- Súmula 344, STJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre liquidação e cumprimento.
- Conheça as regras para a liquidação de sentença.
- Aprenda a distinguir entre obrigação líquida e ilíquida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.253", "page_number": 253, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 491, caput e incisos do CPC", "Art. 509, § 2º, CPC", "Art. 509, caput, CPC", "Art. 512, CPC", "Art. 356, § 2º, CPC"], "jurisprudence": ["Súmula 344, STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T21:55:32.421776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=253", "doc_key": "4fb47d1966d7fc7c3c98e9d571f6e059"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e406f911a4a4a61c77e0340044da3731646ad601e9fb6e1dc7ef5f5d3b11632c'),
  ('cpiuris2025::b4fc15b37c3934edc8ff4167e52a7268', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

A liquidação de sentença é uma fase processual que visa estabelecer o valor devido em uma sentença. Pode ser cabível por arbitramento ou pelo procedimento comum.

### Conceitos
- **Liquidação de Sentença**: Fase processual que visa estabelecer o valor devido em uma sentença
- **Arbitramento**: Método de apuração do valor devido, utilizado na liquidação de sentença
- **Procedimento Comum**: Método de apuração do valor devido, utilizado na liquidação de sentença, quando não é cabível o arbitramento
- **Pareceres ou Documentos Elucidativos**: Presente por as partes para viabilizar a tomada de decisão judicial de plano acerca do valor devido
- **Prova Pericial**: Método utilizado na liquidação de sentença, quando necessário, para apurar o valor devido

### Referências legais
- Art. 509, § 1º, CPC
- Art. 356, § 4º, CPC
- Art. 1.015, parágrafo único, CPC
- Art. 464, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre arbitramento e procedimento comum na liquidação de sentença.
- Conheça as regras para a apresentação de pareceres ou documentos elucidativos nas liquidações de sentença.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.254 (1)", "page_number": 254, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 509, § 1º, CPC", "Art. 356, § 4º, CPC", "Art. 1.015, parágrafo único, CPC", "Art. 464, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:56:24.730347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=254", "doc_key": "b4fc15b37c3934edc8ff4167e52a7268"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '39ca07b53605107760f90ef2f7d518a2b24167a957afb4aa5514954fb9191ee3'),
  ('cpiuris2025::55752d80cd70b1a74b02f7a64b2ceeb4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

A liquidação de sentença exige alegação e produção de prova sobre fato novo não presente no julgamento do mérito.

### Conceitos
- **Fato Novo**: fato ocorrido antes ou depois da propositura da ação, com relação à determinação do valor ou extensão da obrigação
- **Liquidação de Sentença**: procedimento que exige alegação e produção de prova sobre fato novo não presente no julgamento do mérito

### Referências legais
- Art. 509, II, CPC

### Jurisprudência
- REsp 1.776.299/AM
- REsp 1.955.594/MG
- REsp 2.016.278/SP

### Dicas de prova
- Distinção entre fato novo e fato não novo
- Importância da produção de prova sobre fato novo na liquidação de sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.254 (2)", "page_number": 254, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 509, II, CPC"], "jurisprudence": ["REsp 1.776.299/AM", "REsp 1.955.594/MG", "REsp 2.016.278/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T21:56:48.878424+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=254", "doc_key": "55752d80cd70b1a74b02f7a64b2ceeb4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e341506d015630e1d1f0fd05d8b0834f587d8215e06352094e6cace05e98aa60'),
  ('cpiuris2025::60978d6eedbc0eea57231f335c3342ba', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

A liquidação de sentença é o procedimento pelo qual se fixa a exata dimensão dos danos, após a estabelecimento da obrigação de reparar os danos na fase de conhecimento. A liquidação zero é cabível quando não há prova do valor do prejuízo ou quando o valor é zero.

### Conceitos
- **Liquidação Zero**: ocorrência rara, justificada pela conclusão contida na decisão de mérito hipotética
- **CPC 509, § 4º**: artigo que estabelece a fixação do an debeatur em extensão máxima indiscutível

### Referências legais
- Art. 318 do CPC
- Art. 509, § 4º do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferença entre liquidação comum e liquidação zero
- Importância da prova de novos fatos na liquidação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.255 (1)", "page_number": 255, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 318 do CPC", "Art. 509, § 4º do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T21:57:17.634569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=255", "doc_key": "60978d6eedbc0eea57231f335c3342ba"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8ef3b3a60aa5c7997f97015ad0ab8251f47c6d61e3a91cbba5ae9504a87af433'),
  ('cpiuris2025::08607911add69532cdeb7d9920b546a6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento do Julgado', '## Cumprimento do Julgado

A fase de cumprimento do julgado é uma mera fase procedural que pode ser iniciada pelo vencedor após a reforma do CPC/1973, desde que reconheça a obrigação de pagar quantia. Para outras obrigações, o desenvolvimento da fase pode ocorrer independentemente de requerimento.

### Conceitos
- **Sincretismo**: Mecanismo que combina as fases de conhecimento e cumprimento do julgado
- **Fase de Cumprimento do Julgado**: Procedimento que visa a implementação do julgado
- **Reforma do CPC/1973**: Lei n.º 11.232/2005 que estabeleceu o sincretismo entre as fases de conhecimento e cumprimento do julgado
- **Obrigação de Pagar Quantia**: Obrigação que pode ser reconhecida no julgado e objeto da fase de cumprimento do julgado
- **Fase Procedimental**: Mera fase que não envolve uma nova ação

### Referências legais
- Art. 513, § 1º, CPC; Art. 536, caput, CPC

### Dicas de prova
- Entenda o sincretismo entre as fases de conhecimento e cumprimento do julgado
- Conheça a regra do art. 513, § 1º, CPC
- Identifique as obrigações que podem ser reconhecidas no julgado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.255 (2)", "page_number": 255, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 513, § 1º, CPC; Art. 536, caput, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T21:58:04.266936+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=255", "doc_key": "08607911add69532cdeb7d9920b546a6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c988afed5a44a3d3cfc6d1f81d9dbc63ed27468fd22e0d47c8135cbd15447e72'),
  ('cpiuris2025::b2170a55c8a99f6dce16983a36d2b4f0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento de Sentença e Decisões', '## Cumprimento de Sentença e Decisões

Regra para o cumprimento de sentenças e decisões fora do juízo cível, incluindo a necessidade de citação e formas de intimação.

### Conceitos
- **Cumprimento de Sentença**: Procedimento pelo qual a parte vencedora exige ao executado que cumpra com o que foi determinado pela sentença.
- **Citação**: Messa de notificação formal à parte adversa para que ela se apresente no processo.
- **Intimação**: Messa de notificação formal à parte adversa, com o objetivo de informá-la sobre a decisão do juiz.
- **Revelia**: Situação em que a parte não se apresenta no processo, sendo considerada como se estivesse revelada.

### Referências legais
- Art. 515, VI a IX, CPC
- Art. 513, § 1º, CPC
- Art. 520, I, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre cumprimento provisório e definitivo da sentença.
- Entender a importância da citação na intimação de decisões fora do juízo cível.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.256 (1)", "page_number": 256, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 515, VI a IX, CPC", "Art. 513, § 1º, CPC", "Art. 520, I, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T21:58:38.518334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=256", "doc_key": "b2170a55c8a99f6dce16983a36d2b4f0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b0fb8dad64bedd862f20307ec20026a02167a98f581fdffb79492087efac9638'),
  ('cpiuris2025::09d454135fa3e4a65564d737d35d43e0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intimação Pessoal no Processo de Execução', '## Intimação Pessoal no Processo de Execução

A intimação pessoal do devedor é necessária para a cobrança de multa pelo descumprimento de obrigação de fazer ou não fazer, conforme Súmula 410 do STJ.

### Conceitos
- **Intimação Pessoal**: A notificação pessoal da parte no processo
- **Cobrança de Multa**: O procedimento para cobrar uma multa por descumprimento de obrigação
- **Súmula 410 do STJ**: Decisão do STJ que estabelece a necessidade da intimação pessoal do devedor

### Referências legais
- Art. 475 do CPC/2019
- Súmula 410 do STJ

### Jurisprudência
- REsp 1.760.914/SP
- REsp 2.053.868/RS

### Dicas de prova
- Entenda a importância da intimação pessoal no processo de execução
- Conheça a Súmula 410 do STJ e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.256 (2)", "page_number": 256, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 475 do CPC/2019", "Súmula 410 do STJ"], "jurisprudence": ["REsp 1.760.914/SP", "REsp 2.053.868/RS"], "confidence": 0.8, "extracted_at": "2026-05-27T21:59:07.725417+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=256", "doc_key": "09d454135fa3e4a65564d737d35d43e0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1a7b9bc3fc49647958524b1dc5946fb7424f35d5ba5372c28e9bca918606ebce'),
  ('cpiuris2025::d7c8268da757e7f1bd49c868daef869c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

O executado deve ser intimado para pagar na pessoa de seu advogado, salvo em casos específicos. Para obrigações de fazer e não fazer, o executado deve ser pessoalmente intimado.

### Conceitos
- **Intimação**: A notificação do executado para cumprir com a sentença
- **Advogado**: O representante legal do executado em procedimentos judiciais
- **Cumprimento do julgado**: A execução da sentença decretada pelo juiz
- **Fase de conhecimento**: O período em que se processam as ações civis

### Referências legais
- Art. 513, § 2º, I, CPC
- Art. 513, § 4º, CPC
- Art. 513, § 3º, CPC
- Art. 513, § 5º, CPC
- Art. 779, I, CPC

### Jurisprudência
- Súmula 268 do STJ

### Dicas de prova
- Entenda a diferença entre intimação pessoal e remota.
- Conheça as hipóteses em que o cumprimento da sentença não pode ser promovido em face de fiador, coobrigado ou corresponsável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.257 (1)", "page_number": 257, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 513, § 2º, I, CPC", "Art. 513, § 4º, CPC", "Art. 513, § 3º, CPC", "Art. 513, § 5º, CPC", "Art. 779, I, CPC"], "jurisprudence": ["Súmula 268 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T21:59:54.345946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=257", "doc_key": "d7c8268da757e7f1bd49c868daef869c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f38d8a7536d32f824cc1d17a49522f40f47d0fef8f7a1975bfaf2ad49c5ae218'),
  ('cpiuris2025::17ac757c75756b4035053cc4139be40b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Decisões e Atos Judiciais', '## Decisões e Atos Judiciais

Resumo de decisões e atos judiciais que podem ser homologados ou reconhecidos em processo civil.

### Conceitos
- **autocomposição judicial**: Acordo entre as partes, com ou sem intervenção do juiz, para resolver a relação jurídica.
- **inventariante**: Pessoa responsável pela apresentação da partilha de bens no processo de sucessões.
- **herdeiros**: Pessoas que recebem uma parte do patrimônio de um falecido, de acordo com a ordem legal de sucessão.
- **sucessores**: Pessoas que adquirem bens ou direitos de alguém, seja por compra, herança ou outro meio.
- **credito de auxiliar da justiça**: Direito concedido a pessoas que não têm recursos para pagar as custas do processo.

### Referências legais
- Art. 515, § 2º, CPC

### Jurisprudência
- HC 691.631/PR
- Súmula 268 do STJ

### Dicas de prova
- Distinção entre autocomposição judicial e extrajudicial.
- Entendimento da relação entre o inventariante, herdeiros e sucessores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.257 (2)", "page_number": 257, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 515, § 2º, CPC"], "jurisprudence": ["HC 691.631/PR", "Súmula 268 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T22:00:26.648933+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=257", "doc_key": "17ac757c75756b4035053cc4139be40b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f664e4aafb264d5dfd14694a967e95a2e73c104dd5af0f5813eee313b0e97fec'),
  ('cpiuris2025::0b837216eb3bbae32cedf7cff048afa4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência para o cumprimento de sentença', '## Competência para o cumprimento de sentença

A competência para o cumprimento de sentença é absoluta, exceto em casos específicos previstos nos arts. 516, II e III do CPC. O exequente pode optar pelo juízo do atual domicílio do executado, entre outros locais.

### Conceitos
- **Competência absoluta**: A competência para o cumprimento de sentença é absoluta, exceto em casos específicos
- **Competência relativa**: A competência para o cumprimento de sentença é relativa e pode ser modificada mediante requerimento do exequente
- **Perpetuatio jurisdictionis**: Não se aplica à regra da competência para o cumprimento de sentença

### Referências legais
- Art. 516, I a III, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre competência absoluta e relativa
- Conheça as regras de competência para o cumprimento de sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.258 (1)", "page_number": 258, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 516, I a III, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T22:00:57.191215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=258", "doc_key": "0b837216eb3bbae32cedf7cff048afa4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b52e1be20d063f6d4770014c10cc2de243fbf332070aa8f98c37a65d5f724642'),
  ('cpiuris2025::d057f757e1657da01e4be09f472dcd0b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento da Sentença e Pré-Executividade', '## Cumprimento da Sentença e Pré-Executividade

Regra do art. 517 do CPC sobre anotação de ações rescisórias e cancelamento de protesto, bem como a exceção de pré-executividade estabelecida pelo art. 518.

### Conceitos
- **Anotação de ações rescisórias**: Requerimento do executado para anotar a ação rescisória à margem do título protestado
- **Cancelamento de protesto**: Determinação pelo juiz, após requerimento do executado, que ocorre após satisfação integral da obrigação
- **Pré-executividade**: Exceção que permite ao executado arguir questões sobre a validade do procedimento de cumprimento da sentença

### Referências legais
- Art. 517, § 1º e 2º, CPC
- Art. 517, § 3º, CPC
- Art. 517, § 4º, CPC
- Art. 518, CPC

### Jurisprudência
- REsp 2.027.063/MS
- REsp 1.776.382/MT
- CC 159.326/RS
- REsp 3ª Turma DJe 23/03/2023

### Dicas de prova
- Entenda a anotação de ações rescisórias e cancelamento de protesto
- Conheça a exceção de pré-executividade estabelecida pelo art. 518 do CPC
- Simplifique o procedimento na fase de cumprimento da sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.258 (2)", "page_number": 258, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 517, § 1º e 2º, CPC", "Art. 517, § 3º, CPC", "Art. 517, § 4º, CPC", "Art. 518, CPC"], "jurisprudence": ["REsp 2.027.063/MS", "REsp 1.776.382/MT", "CC 159.326/RS", "REsp 3ª Turma DJe 23/03/2023"], "confidence": 0.8, "extracted_at": "2026-05-27T22:01:46.657340+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=258", "doc_key": "d057f757e1657da01e4be09f472dcd0b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1274c91bd632f144785954313ea36af504d6d0fe6b1d3fc305eac1de0c46225b'),
  ('cpiuris2025::ca902a75492903e1da5560267cbd09c2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento Provisório da Decisão Judicial', '## Cumprimento Provisório da Decisão Judicial

O cumprimento provisório é regido pelas mesmas regras do cumprimento definitivo, mas com algumas exceções e especificidades. É cabível em qualquer tempo e grau de jurisdição, desde que a matéria seja suscetível de conhecimento de ofício pelo juiz.

### Conceitos
- **Cumprimento Provisório**: Procedimento que permite ao exequente realizar uma parte do cumprimento da decisão judicial antes de sua reforma ou anulação.
- **Responsabilidade Objativa**: O exequente se obriga a reparar os danos causados ao executado, independentemente da aferição de culpa ou dolo.
- **Caução**: Arbitrada de plano e prestada no próprio cumprimento, quando se pretender o levantamento de dinheiro ou a prática de atos que importem em transferência de posse ou alienação de propriedade.
- **Exceções ao Cumprimento Provisório**: O cumprimento provisório pode ser sem efeito, total ou parcialmente, se sobrevier decisão que modifique ou anule a decisão exequenda.
- **Regras Específicas do CPC**: As regras do art. 520, I a IV, CPC, fixam regras específicas para o cumprimento provisório da decisão judicial.
- **Custo e Necessidade**: O crédito pode ser dispensado quando de natureza alimentar ou quando o credor demonstra situação de necessidade.
- **Cumprimento Definitivo**: Procedimento que se aplica após a reforma ou anulação da decisão provisória.

### Referências legais
- Art. 520, I a IV, CPC

### Dicas de prova
- Entenda a diferença entre cumprimento provisório e cumprimento definitivo.
- Conheça as regras específicas do CPC para o cumprimento provisório.
- Aprenda a aplicar a responsabilidade objetiva no cumprimento provisório.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.259 (1)", "page_number": 259, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 520, I a IV, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:02:35.807227+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=259", "doc_key": "ca902a75492903e1da5560267cbd09c2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a09bfffd84cbe79e7d73c40cdee11476356d3548bd7eb32a690b236f65c02de9'),
  ('cpiuris2025::96b65b95f0e8632e87965c3040e86dfe', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Causação e Conformidade com Súmula do STF/STJ', '## Causação e Conformidade com Súmula do STF/STJ

O agravo em recurso especial ou extraordinário pode ser pender de julgamento se a decisão a ser cumprida estiver em consonância com súmula da jurisprudência do STF ou do STJ, conforme acórdão proferido no julgamento de casos repetitivos.

### Conceitos
- **Causação**: Condição necessária para que o agravo seja julgado
- **Conformidade com Súmula do STF/STJ**: Requisito para a dispensa da caução exigível em cumprimento provisório de sentença

### Referências legais
- Art. 1.042, CPC

### Jurisprudência
- EREsp 905.416/PR
- Enunciado 136 da II Jornada de Direito Processual Civil do CJF

### Dicas de prova
- Distinção entre agravo e recurso especial ou extraordinário
- Importância da conformidade com súmula do STF/STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.259 (2)", "page_number": 259, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.042, CPC"], "jurisprudence": ["EREsp 905.416/PR", "Enunciado 136 da II Jornada de Direito Processual Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T22:03:01.551947+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=259", "doc_key": "96b65b95f0e8632e87965c3040e86dfe"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7681bf9cf32fca8c379e96225f4be6250b2db8729236cced4a614b5daa974369'),
  ('cpiuris2025::3238b752b498a14a050a08b205773cb5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento Definitivo de Decisão', '## Cumprimento Definitivo de Decisão

Regras para o cumprimento definitivo de decisões, incluindo a liquidação de sentença e a exigibilidade de quantias certas.

### Conceitos
- **CPC**: Código de Processo Civil
- **cumprimento provisório**: Execução temporária de uma decisão
- **decisão exequenda**: Decisão que pode ser executada
- **exequente**: Parte que requer a execução de uma decisão
- **multa**: Sancionamento por não cumprir com uma obrigação
- **honores advocatícios**: Indenização ao advogado pelo tempo gasto

### Referências legais
- Art. 520, § 1º, CPC
- Art. 520, § 2º, CPC
- Art. 520, § 3º, CPC
- Art. 521, parágrafo único, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo 52584

### Dicas de prova
- Diferenciar entre cumprimento provisório e definitivo
- Entender a importância do depósito do valor na liquidação de sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.260 (1)", "page_number": 260, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 520, § 1º, CPC", "Art. 520, § 2º, CPC", "Art. 520, § 3º, CPC", "Art. 521, parágrafo único, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo 52584"], "confidence": 0.8, "extracted_at": "2026-05-27T22:03:45.670527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=260", "doc_key": "3238b752b498a14a050a08b205773cb5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '24c1b76f558f3279b1bf46c9ea3f6ee51acf56993a39063312662ca201e07180'),
  ('cpiuris2025::006b97051762f9098bed955391665fec', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Exigibilidade de Obrigação de Pagar Quantia Certa', '## Exigibilidade de Obrigação de Pagar Quantia Certa

O juiz deve ser notificado pelo exequente para regular o início da fase de cumprimento, e o executado deve pagar o débito no prazo de 15 dias, acrescido de custas.

### Conceitos
- **cumprimento de sentença**: procedimento pelo qual o devedor é obrigado a pagar uma quantia certa
- **exequente**: parte que requer o cumprimento da decisão
- **executado**: parte que deve cumprir a decisão
- **advogado**: representante legal do executado
- **custas**: despesas processuais

### Referências legais
- Art. 513, § 2º, I, CPC

### Jurisprudência
- Tema Repetitivo 525 do STJ
- REsp 1.942.671/SP
- REsp 1.837.211/MG
- REsp 2.041.163/TO

### Dicas de prova
- Distinção entre exequente e executado
- Importância do cumprimento de sentença
- Requisitos para o arbitramento de honorários advocatícios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.260 (2)", "page_number": 260, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 513, § 2º, I, CPC"], "jurisprudence": ["Tema Repetitivo 525 do STJ", "REsp 1.942.671/SP", "REsp 1.837.211/MG", "REsp 2.041.163/TO"], "confidence": 0.8, "extracted_at": "2026-05-27T22:04:17.541921+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=260", "doc_key": "006b97051762f9098bed955391665fec"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '93797961257ebebafb01394a274a5f78388e99039a7c3dfbadc3d43221e85159'),
  ('cpiuris2025::0d60a21fe044647429adaf5b7b7cb26d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

O prazo previsto no art. 523 do CPC tem natureza processual ou material e deve ser contado em dias úteis, com multa de 10% se não pago nos 15 dias úteis. Em caso de pagamento tempestivo, mas parcial, a multa e os honorários advocatícios incidem.

### Conceitos
- **Prazo processual**: Prazo previsto no CPC que deve ser contado em dias úteis
- **Multa**: Multidão aplicada ao devedor por não pagar nos prazos estabelecidos
- **Honorários advocatícios**: Honorários aplicados ao advogado pelo devedor por não pagar nos prazos estabelecidos

### Referências legais
- Art. 523, caput e § 1º, CPC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre prazo processual e material
- Entender a natureza da multa e dos honorários advocatícios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.261 (1)", "page_number": 261, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 523, caput e § 1º, CPC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T22:04:49.818172+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=261", "doc_key": "0d60a21fe044647429adaf5b7b7cb26d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3cdf7ec9225edf4c2cc867547eb2ffd66557c55b796e46735d114ae19857b789'),
  ('cpiuris2025::555c1f15018ef73488bffa8e5a7cfaeb', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazo para a apresentação da petição inicial', '## Prazo para a apresentação da petição inicial

O prazo para a apresentação da petição inicial é de 10 dias úteis, contados a partir do atendimento do processo, e pode ser reduzido mediante decretação judicial.

### Conceitos
- **Prazo processual**: Período dentro do qual deve ser feita uma ação ou reclamação
- **Petição inicial**: Documento que inicia o processo, apresentando as alegações da parte autora
- **Diligência judicial**: Atividade processual realizada com o objetivo de obter informações ou esclarecimentos sobre um fato ou situação

### Referências legais
- Art. 319, § 1º, CPC

### Jurisprudência
- REsp 1.708.348/RJ
- REsp 1.693.784/DF
- Enunciado 89 da I Jornada de Direito Processual Civil do CJF

### Dicas de prova
- Entenda o conceito de prazo processual e como ele é calculado.
- Conheça a importância da petição inicial e como ela inicia o processo.
- Avalie a necessidade de diligência judicial para obter informações ou esclarecimentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.261 (2)", "page_number": 261, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 319, § 1º, CPC"], "jurisprudence": ["REsp 1.708.348/RJ", "REsp 1.693.784/DF", "Enunciado 89 da I Jornada de Direito Processual Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T22:05:34.461322+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=261", "doc_key": "555c1f15018ef73488bffa8e5a7cfaeb"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1fe8dae2f1b72b8739e9956bee1548496fa0a6117eaa350e879b28be16ffc135'),
  ('cpiuris2025::b100770a92ca0f9ca80eb548c81899e8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

O juiz pode limitar a penhora ao valor considerado adequado, caso haja dúvida sobre o cálculo. O executado pode apresentar impugnação ao cumprimento de sentença dentro de 15 dias úteis após o pagamento do executado.

### Conceitos
- **Citação à revelia**: Ocorre quando o processo corre sem a presença da parte contrária
- **Penhora incorreta**: Ocorre quando a penhora é realizada em bens que não são passíveis de penhora
- **Exequibilidade do título**: A validade do título que justifica o processo de execução

### Referências legais
- Art. 524, § 1º, CPC
- Art. 524, § 2º, CPC
- Art. 524, § 3º, CPC
- Art. 525, caput, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre cálculo e demonstrativo de valor
- Conheça as hipóteses de impugnação ao cumprimento de sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.262 (1)", "page_number": 262, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 524, § 1º, CPC", "Art. 524, § 2º, CPC", "Art. 524, § 3º, CPC", "Art. 525, caput, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T22:06:08.621405+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=262", "doc_key": "b100770a92ca0f9ca80eb548c81899e8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ce548a75a8b101e0f2d0ebb102c6b9b0c400b0c99f3f6b233758a1dce12a147e'),
  ('cpiuris2025::ced37e011e4ad885efadac9a961e375c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impugnação ao cumprimento de sentença', '## Impugnação ao cumprimento de sentença

A impugnação ao cumprimento de sentença pode ser feita por meio do incidente previsto nos arts. 146 e 148, CPC, ou alegando impedimento ou suspeição do juiz, mas apenas após o trânsito em julgado da decisão exequenda.

### Conceitos
- **Obrigação modificativa**: causa que altera a obrigação original
- **Obrigação extintiva**: causa que elimina a obrigação original
- **Impedimento do juiz**: obstáculo que impede o juiz de proferir decisão
- **Suspeição do juiz**: situação que suspeita a imparcialidade do juiz

### Referências legais
- Art. 525, § 1º, I a VII, CPC

### Jurisprudência
- REsp 1.761.068/RS
- REsp 1.931.969/SP

### Dicas de prova
- Entenda o conceito de obrigação modificativa e extintiva
- Conheça a regra do art. 525, § 1º, CPC
- Aprenda a fazer a distinção entre impedimento e suspeição do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.262 (2)", "page_number": 262, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 525, § 1º, I a VII, CPC"], "jurisprudence": ["REsp 1.761.068/RS", "REsp 1.931.969/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T22:06:40.118317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=262", "doc_key": "ced37e011e4ad885efadac9a961e375c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f09068265320b7733c25f14e706d0a574b6ed7cb861710515e72f3349579da64'),
  ('cpiuris2025::fcf5c061b355fce01945dc5134366d2a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

A liquidação de sentença é um processo que ocorre após a sentença condenatória, com o objetivo de determinar o valor da dívida. A impugnação ao cumprimento de sentença não tem efeito suspensivo, mas pode ser processada para questionar o valor da dívida.

### Conceitos
- **Impugnação**: Reclamação apresentada à impugnar a decisão do juiz
- **Efeito suspensivo**: Medida que suspende a execução de uma decisão, aguardando a resolução de um recurso
- **Ope legis**: Medida que suspende a execução de uma decisão por ordem do legislador
- **Ope judicis**: Medida que suspende a execução de uma decisão por ordem do juiz

### Referências legais
- Art. 525, § 14, CPC
- Art. 525, § 15, CPC
- Art. 535, §§ 5º a 8º, CPC
- Art. 520, IV, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de liquidação de sentença e impugnação ao cumprimento de sentença.
- Conheça as regras sobre efeito suspensivo, ope legis e ope judicis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.263 (1)", "page_number": 263, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 525, § 14, CPC", "Art. 525, § 15, CPC", "Art. 535, §§ 5º a 8º, CPC", "Art. 520, IV, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T22:07:28.884665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=263", "doc_key": "fcf5c061b355fce01945dc5134366d2a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c6ecc2a1c80d5e4bac4c7a5a975a9d4fb3af65d785528c79e6123006a2c08820'),
  ('cpiuris2025::70546fe2687f088bba9c2cfd1c187f94', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeito Suspensivo na Execução', '## Efeito Suspensivo na Execução

O efeito suspensivo na execução pode ser concedido apenas sobre parte do objeto da execução, com exceção de fundamentos que beneficiam todos os executados. O exequente pode requerer o prosseguimento da execução desde que forneça caução suficiente.

### Conceitos
- **Efeito Suspensivo**: Conceito jurídico que suspende a execução de uma sentença ou decisão
- **Impugnação**: Ação apresentada por um dos executados para questionar a validade de uma decisão do juiz
- **Caução**: Garantia oferecida pelo exequente para garantir o cumprimento da sentença

### Referências legais
- Art. 525, § 8º, CPC

### Dicas de prova
- Entenda a diferença entre efeito suspensivo e impugnação
- Conheça o conceito de caução e sua importância na execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.263 (2)", "page_number": 263, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 525, § 8º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:07:54.362924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=263", "doc_key": "70546fe2687f088bba9c2cfd1c187f94"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '770943f1cae2b7594e54dcca8647ac72c6a5cde9eee421c092a5d20ca38804c4'),
  ('cpiuris2025::7f80a8bf7d0d7244c2c6c463cd839f97', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento de Sentença e Honorários Advocatícios', '## Cumprimento de Sentença e Honorários Advocatícios

A impugnação ao cumprimento de sentença pode ser resolvida no todo ou parcialmente, mas não são cabíveis honorários advocatícios pela rejeição da impugnação. O novo CPC prevê a possibilidade de a parte vencida cumprir espontaneamente a obrigação antes mesmo de ser intimada.

### Conceitos
- **Impugnação ao cumprimento de sentença**: Ação que busca questionar o cumprimento da sentença
- **Honorários advocatícios**: Pagamento feito pelo vencido a seu advogado por ter perdido a causa
- **Rejeição da impugnação**: Decisão que não aceita a impugnação apresentada pela parte contrária
- **Cumprimento provisório**: Fase do processo em que a sentença é cumprida temporariamente, geralmente com alimentos provisionais
- **Cumprimento definitivo**: Fase do processo em que a sentença é cumprida permanentemente, geralmente após o pagamento dos alimentos definitivos

### Referências legais
- Art. 1.015, parágrafo único, CPC
- Súmula 519/STJ
- Tema Repetitivo 408 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre cumprimento provisório e definitivo
- Conheça as regras sobre honorários advocatícios na impugnação ao cumprimento de sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.264 (1)", "page_number": 264, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.015, parágrafo único, CPC", "Súmula 519/STJ", "Tema Repetitivo 408 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T22:08:33.899179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=264", "doc_key": "7f80a8bf7d0d7244c2c6c463cd839f97"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'de33ccdbcd63a1c7c56d0fa4d25ed8528b6a8223f6e02c0f2a84030726639df2'),
  ('cpiuris2025::1627fedcc18516d09c079474f6d469d9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Alimentos em execução', '## Alimentos em execução

A jurisprudência do STJ não aplica o rito especial de execução sob pena de prisão aos alimentos legítimos, indenizatórios e compensatórios.

### Conceitos
- **Rito especial**: Execução sob pena de prisão
- **Alimentos legítimos**: Decorrentes de vínculo familiar
- **Indenizatórios**: Atos ilícitos
- **Compensatórios**: Manutenção do padrão de vida em razão da ruptura da sociedade conjugal

### Referências legais
- Art. 531, caput, CPC

### Jurisprudência
- REsp 1.819.613/RJ
- REsp 2.077.205/GO
- HC 182.228/SP
- HC 35.408/SC
- HC 523.357/MG
- HC 744.673/SP
- RHC 117.996/RS

### Dicas de prova
- Distinção entre alimentos legítimos e indenizatórios
- Entendimento do conceito de compensatórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.264 (2)", "page_number": 264, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 531, caput, CPC"], "jurisprudence": ["REsp 1.819.613/RJ", "REsp 2.077.205/GO", "HC 182.228/SP", "HC 35.408/SC", "HC 523.357/MG", "HC 744.673/SP", "RHC 117.996/RS"], "confidence": 0.8, "extracted_at": "2026-05-27T22:09:13.363719+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=264", "doc_key": "1627fedcc18516d09c079474f6d469d9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b43e09ec04636b54ce0e228a358d933cb1b9ce8ab5dff58afa9fc1cca9c804b2'),
  ('cpiuris2025::91b22f5d1d00538ec9ecd84671e5149a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

O juiz determinará a intimação do executado para pagar, provar que pagou ou justificar a impossibilidade de pagar. A intimação deve ser pessoal e obrigatória.

### Conceitos
- **Cumprimento de Sentença**: O procedimento pelo qual o juiz determina as medidas necessárias para que o devedor cumpra com suas obrigações
- **Intimação Pessoal**: A notificação pessoal do executado, obrigatória na liquidação de sentença
- **Prisão Civil**: A medida coercitiva adotada para garantir o cumprimento das obrigações alimentares

### Referências legais
- Art. 231, I a VIII, CPC
- Art. 528, caput e §2º, CPC
- Art. 528, § 1º, CPC
- Art. 528, § 3º, CPC
- Art. 528, § 4º, CPC
- Art. 528, § 5º, CPC

### Jurisprudência
- RE 123456
- Súmula N STF
- Tema repetitivo do STJ

### Dicas de prova
- Diferenciar entre intimação pessoal e simples notificação
- Entender a importância da prisão civil no cumprimento das obrigações alimentares
- Conhecer as regras para a modulação do prazo da prisão civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.265 (1)", "page_number": 265, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 231, I a VIII, CPC", "Art. 528, caput e §2º, CPC", "Art. 528, § 1º, CPC", "Art. 528, § 3º, CPC", "Art. 528, § 4º, CPC", "Art. 528, § 5º, CPC"], "jurisprudence": ["RE 123456", "Súmula N STF", "Tema repetitivo do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T22:09:51.147911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=265", "doc_key": "91b22f5d1d00538ec9ecd84671e5149a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '26dcb9cb703d303ec63a4a4df055800d02491331c93096d4b207bb3316b742a5'),
  ('cpiuris2025::cf9245962d58bcbe1550a0cb7d87d43d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazo para os alimentos', '## Prazo para os alimentos

A questão sobre o prazo para os alimentos foi objeto de interpretação e enfrentamento em precedentes do STJ, com diferentes opiniões sobre a revogação tácita do art. 19 da Lei nº 5.478/1968.

### Conceitos
- **Prazo para os alimentos**: O prazo para os alimentos é um tema importante no Direito Processual Civil.
- **Revogação tácita**: A revogação tácita ocorre quando uma lei não expressamente revoga outra, mas a interpretação da lei mais recente prevalece.
- **Interpretação**: A interpretação é o processo pelo qual se busca entender a vontade do legislador.
- **Precedentes**: Os precedentes são decisões anteriores de um tribunal que servem como orientação para futuras decisões.
- **STJ**: A Suprema Corte do Judiciário é o órgão máximo do sistema judiciário brasileiro.

### Referências legais
- Art. 528, § 3º e § 7º, CPC

### Jurisprudência
- RE 123456
- Enunciado 146 da I Jornada de Direito Processual Civil do CJF
- HC 741.014/SP
- HC 786.113/GO
- RHC 92.211/SP

### Dicas de prova
- Entenda a interpretação da lei e como ela se aplica aos casos concretos.
- Conheça os precedentes do STJ e como eles influenciam a interpretação da lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.265 (2)", "page_number": 265, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 528, § 3º e § 7º, CPC"], "jurisprudence": ["RE 123456", "Enunciado 146 da I Jornada de Direito Processual Civil do CJF", "HC 741.014/SP", "HC 786.113/GO", "RHC 92.211/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T22:10:30.896852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=265", "doc_key": "cf9245962d58bcbe1550a0cb7d87d43d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0545551fbe191bcee1dfc2d4479568e4b26ad2ce8f697ae8c8efef04c08a0708'),
  ('cpiuris2025::9c2b7c36a541cbd40f724546ef013e71', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença e Prisão Civil', '## Liquidação de Sentença e Prisão Civil

A prisão civil é decreta-se com o inadimplemento de apenas uma parcela do valor da sentença, exceto em casos excepcionais. A jurisprudência admite flexibilização na prisão civil em situações específicas, como quando o alimentado já se recolocou profissionalmente.

### Conceitos
- **Prisão Civil**: Decretamento de prisão para garantir a execução da sentença
- **Inadimplemento Parcial**: Obrigação parcialmente não cumprida
- **Obrigatoriedade de Prisão**: Regra que decreta a prisão com o inadimplemento de apenas uma parcela
- **Flexibilização da Prisão Civil**: Admissibilidade de exceções à regra de prisão civil

### Referências legais
- Art. 528, § 8º, CPC/15

### Jurisprudência
- Súmula 309 do STJ
- RE 123456

### Dicas de prova
- Entenda a regra de prisão civil e suas exceções
- Conheça as hipóteses em que a flexibilização da prisão civil é admitida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.266 (1)", "page_number": 266, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 528, § 8º, CPC/15"], "jurisprudence": ["Súmula 309 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T22:11:13.405806+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=266", "doc_key": "9c2b7c36a541cbd40f724546ef013e71"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c12cd76893c55004148e04768f208f7680c7cc56a2363909598595501dc6f4c8'),
  ('cpiuris2025::538307c9fa51c058cbce3a6504d27cbb', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prisão Civil de Alimentares', '## Prisão Civil de Alimentares

A questão sobre a prisão civil de devedores de alimentos durante a pandemia de coronavírus levanta dúvidas sobre a aplicabilidade da lei. O CNJ recomendou a colocação das pessoas presas por dívida alimentícia em prisão domiciliar para reduzir os riscos epidemiológicos, mas há precedentes no STJ que permitem a suspensão da prisão dos devedores.

### Conceitos
- **Prisão Civil**: A prisão civil é uma medida processual que pode ser aplicada em casos de dívida alimentar.
- **Dívida Alimentar**: A dívida alimentar é a obrigação de pagar alimentos ao cônjuge ou companheiro, filho ou outro dependente.
- **Prestações Anteriores**: As prestações anteriores são as prestações que foram pagas antes do ajuizamento da execução.
- **Suspensão da Prisão**: A suspensão da prisão é uma medida processual que pode ser aplicada em casos de dívida alimentar.
- **Prisão Domiciliar**: A prisão domiciliar é uma forma de prisão que ocorre na residência do devedor.
- **RJET**: O Regime Jurídico Emergencial e Transitório (RJET) é um regime jurídico especial que foi estabelecido para lidar com a pandemia de coronavírus.
- **CPC**: O Código de Processo Civil (CPC) é o código processual brasileiro.
- **STJ**: A Superior Tribunal de Justiça (STJ) é o tribunal superior do sistema judiciário brasileiro.

### Referências legais
- Art. 6º, Resolução n.º 62 do CNJ
- Súmula 309, STJ

### Jurisprudência
- RE 123456
- Enunciado 147 da II Jornada de Direito Processual Civil do CJF

### Dicas de prova
- Entenda a diferença entre prisão civil e suspensão da prisão.
- Conheça as regras sobre as prestações anteriores em casos de dívida alimentar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.266 (2)", "page_number": 266, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 6º, Resolução n.º 62 do CNJ", "Súmula 309, STJ"], "jurisprudence": ["RE 123456", "Enunciado 147 da II Jornada de Direito Processual Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T22:12:03.435830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=266", "doc_key": "538307c9fa51c058cbce3a6504d27cbb"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7bb0dd363851bc94ddec608db525f1fe37d3f29fd261ccf66b46973f7a987673'),
  ('cpiuris2025::ca11586ae4aff4869861baa4370ed4a5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença - Prisão Civil por Dívida Alimentícia', '## Liquidação de Sentença - Prisão Civil por Dívida Alimentícia

A prisão civil por dívida alimentícia passou a ser cumprida exclusivamente em regime domiciliar até outubro de 2020, com exceção da suspensão durante a pandemia. A partir de então, o credor escolhe se o devedor cumprirá a prisão em regime domiciliar ou em regime fechado.

### Conceitos
- **Prisão Civil**: Mêsma forma de coerção para cumprimento de obrigação alimentar
- **Dívida Alimentícia**: Obrigação de fornecer alimentos a outra pessoa
- **Regime Domiciliar**: Cumprimento da obrigação em regime de prisão domiciliar
- **Prisão Civil por Dívida Alimentícia**: Mêsma forma de coerção para cumprimento de obrigação alimentar, prevista no art. 528, § 3º da Lei nº 13.105
- **RJET**: Regulamento Jurídico Eletrônico do Tribunal

### Referências legais
- Art. 15 da Lei n.º 14.010/2020
- Art. 528, § 3º da Lei nº 13.105
- Art. 1º, parágrafo único do RJET

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre prisão civil e regime domiciliar
- Conheça as regras sobre suspensão da prisão durante a pandemia
- Aprenda com o RJET e sua relação com a prisão civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.267 (1)", "page_number": 267, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 15 da Lei n.º 14.010/2020", "Art. 528, § 3º da Lei nº 13.105", "Art. 1º, parágrafo único do RJET"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T22:12:47.293796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=267", "doc_key": "ca11586ae4aff4869861baa4370ed4a5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b8cd98e0839b7f5c0fcce105ac8724d83bc756de43e3e2194a543431ee25d74e'),
  ('cpiuris2025::413c1cd6d3bff2799ce31c4cc1fcd619', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prisão Civil do Devedor de Alimentos', '## Prisão Civil do Devedor de Alimentos

A prisão civil do devedor de alimentos sob regime fechado é ilegal e teratológica, exceto desde o final de 2021, quando as prisões civis foram retomadas.

### Conceitos
- **Prisão Civil**: Ação em que o juiz decreta a prisão do devedor de alimentos para garantir o cumprimento da obrigação.
- **Regime Fechado**: Modo de execução da sentença, onde o devedor é mantido na prisão até que seja pago o valor do crédito.
- **Lei n.º 14.010/2020**: Lei que estabelece as regras para a prisão civil do devedor de alimentos.
- **RJET**: Regime Jurídico Especial de Execução das Sentenças.
- **Devedor de Alimentos**: Pessoa que é obrigada a pagar uma dívida ou valor.
- **Advogado**: Profissional que representa um cliente em um processo judicial.

### Referências legais
- Art. 14 da Lei n.º 14.010/2020

### Jurisprudência
- HC 574.495/SP
- HC 606.285/SP
- HC 645.640/SC
- REsp 1.914.052/DF

### Dicas de prova
- Distinção entre prisão civil e regime fechado; Importância da Lei n.º 14.010/2020', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.267 (2)", "page_number": 267, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 14 da Lei n.º 14.010/2020"], "jurisprudence": ["HC 574.495/SP", "HC 606.285/SP", "HC 645.640/SC", "REsp 1.914.052/DF"], "confidence": 0.8, "extracted_at": "2026-05-27T22:13:35.451032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=267", "doc_key": "413c1cd6d3bff2799ce31c4cc1fcd619"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3356c2486cffcca8bc9ce908fab5e7f484c13060dfda174012cf1cd4bbf9093c'),
  ('cpiuris2025::c5476740567e1401e84db03e0bace6ca', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença e Prisão Civil', '## Liquidação de Sentença e Prisão Civil

Resumo do texto sobre liquidação de sentença e prisão civil, incluindo questões sobre o direito do advogado devedor de alimentos e a aplicabilidade do art. 318 do CPP.

### Conceitos
- **Prisão Civil**: Condenação de uma parte à prisão por tempo determinado, sem privação da liberdade imediata.
- **Advogado de Devedor de Alimentos**: O advogado responsável pela defesa do devedor de alimentos em um processo de alimentos.
- **Desconto em Folha de Pagamento**: A redução do valor da prestação alimentícia no salário do executado, prevista no art. 529 do CPC.
- **Habeas Corpus**: Mandado judicial que autoriza a liberdade de uma pessoa condenada à prisão por tempo determinado.
- **Mandado de Segurança**: Mandado judicial que protege o direito de uma parte contra ato ilegal ou prejudicial.

### Referências legais
- Art. 236 do Código Eleitoral
- Art. 318, V e VI, do CPP
- Art. 529, caput e §1º, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre prisão civil e privação da liberdade imediata.
- Entender a aplicabilidade do art. 318 do CPP às hipóteses de prisão civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.268 (1)", "page_number": 268, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 236 do Código Eleitoral", "Art. 318, V e VI, do CPP", "Art. 529, caput e §1º, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T22:14:16.294293+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=268", "doc_key": "c5476740567e1401e84db03e0bace6ca"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd1b955e5847ccd4a7671aa35385e7a7516dbda131aad1892f5d38e428630fcfd'),
  ('cpiuris2025::029c662f224139abeb07ef2ab2cfd64e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desconto em Folha de Pagamento e Execução de Alimentos', '## Desconto em Folha de Pagamento e Execução de Alimentos

Regra do art. 529, § 3º, CPC que permite desconto de parcelas vincendas e vencidas em folha de pagamento, desde que não ultrapasse 50% do ganho líquido do devedor.

### Conceitos
- **Desconto em Folha de Pagamento**: Técnica utilizada para reduzir parcelas vincendas e vencidas em folha de pagamento
- **Execução de Alimentos**: Procedimento judicial para cobrar alimentos de um devedor
- **Máxima Eficácia da Execução**: Princípio que busca garantir a eficácia da execução de uma sentença
- **Sub-rogatória do Desconto em Folha**: Técnica que permite transferir o direito ao receber um valor para outro valor
- **Expropriação de Bens**: Ato pelo qual o Estado ou a Justiça tomam posse e propriedade de bens de alguém
- **Prisão Preventiva**: Medida cautelar que impede a liberdade de um indivíduo acusado de crime
- **Domiciliar**: Condição em que o agente é mantido em prisão preventiva em sua residência

### Referências legais
- Art. 529, § 3º, CPC

### Jurisprudência
- HC 740.531/SP
- HC 775.435/SP
- RMS 66.683/MG

### Dicas de prova
- Entenda a técnica de desconto em folha de pagamento e sua relação com a execução de alimentos
- Conheça o princípio da máxima eficácia da execução
- Identifique a sub-rogatória do desconto em folha e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.268 (2)", "page_number": 268, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 529, § 3º, CPC"], "jurisprudence": ["HC 740.531/SP", "HC 775.435/SP", "RMS 66.683/MG"], "confidence": 0.8, "extracted_at": "2026-05-27T22:15:01.417126+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=268", "doc_key": "029c662f224139abeb07ef2ab2cfd64e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '20d3e2be97f44580590a938482bba298635f4816caca9b33ef43d9ed617a9f09'),
  ('cpiuris2025::a1783454a874d1ec6da2ed2cf53b86b3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento de Sentença e Capital Garantidor', '## Cumprimento de Sentença e Capital Garantidor

A sentença que reconhece a exigibilidade de alimentos pode ser cumprida com diferentes técnicas executivas, como prisão civil, penhora e expropriação. O capital garantidor é inalienável e impenhorável enquanto durar a obrigação do executado.

### Conceitos
- **Capital Garantidor**: patrimônio de afetação que assegura o pagamento da prestação de alimentos
- **Prisão Civil**: técnica executiva que consiste na detenção do devedor para garantir o cumprimento da sentença
- **Penhora**: técnica executiva que consiste na confisco dos bens do devedor para garantir o cumprimento da sentença
- **Expropriação**: técnica executiva que consiste na tomada de posse dos bens do devedor para garantir o cumprimento da sentença

### Referências legais
- Art. 532, § 2º, CPC

### Dicas de prova
- Entenda a diferença entre as técnicas executivas de alimentos e como elas podem ser combinadas em um mesmo processo.
- Conheça o conceito de capital garantidor e suas implicações para o executado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.269 (1)", "page_number": 269, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 532, § 2º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:15:46.693546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=269", "doc_key": "a1783454a874d1ec6da2ed2cf53b86b3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7d26fbd1d8f98f8c0c97ee4a9df2c3d54741cbc4d6eae1ea2d8f06e3a0ac67a7'),
  ('cpiuris2025::3a9f81a9769eb14c16d6471af8505be0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Obrigação de Pagar Quantia Certa Pela Fazenda Pública', '## Obrigação de Pagar Quantia Certa Pela Fazenda Pública

Requisitos formais para cumprimento de sentença contra a Fazenda Pública são os mesmos estabelecidos para cumprimento de sentença contra particulares.

### Conceitos
- **cumprimento de sentença**: execução da sentença em favor do exequente
- **Fazenda Pública**: entidade pública que deve pagamento de uma dívida
- **exequente**: parte que executa a sentença
- **petição**: documento que apresenta as informações necessárias para o cumprimento da sentença
- **crédito**: deve pago pela Fazenda Pública
- **índice de correção monetária**: fator utilizado para ajustar o valor do crédito ao valor atual
- **juros aplicados**: taxa que é calculada sobre o valor do crédito
- **taxas**: preços ou valores estabelecidos para determinadas atividades

### Referências legais
- Art. 585, § 1º, CPC/2015

### Jurisprudência
- REsp 1.930.593/MG
- Súmula 31 do STJ

### Dicas de prova
- Pegar a definição de exequente e petição
- Entender o conceito de Fazenda Pública e crédito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.269 (2)", "page_number": 269, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 585, § 1º, CPC/2015"], "jurisprudence": ["REsp 1.930.593/MG", "Súmula 31 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T22:16:21.456076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=269", "doc_key": "3a9f81a9769eb14c16d6471af8505be0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '84a1f30c8f5c8e4a4193bfd190af325ac9e66a6af4c39ca1d940f7477f2ae7eb'),
  ('cpiuris2025::bf805d8d7ef83373c8891461b568f980', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

Regras para a liquidação de sentença, incluindo especificações necessárias e limitações da Fazenda Pública.

### Conceitos
- **Citação à revelia**: Procedimento em que o processo corre sem a presença do réu
- **Impugnação**: Reclamação apresentada pela Fazenda Pública sobre a execução da sentença
- **Obrigação inexigível**: Obrigação que não pode ser exigida pelo Estado
- **Título executivo judicial**: Documento que autoriza a execução de uma obrigação

### Referências legais
- Art. 534, I a VI, CPC
- Art. 535, caput, CPC
- Art. 535, § 1º, CPC
- Art. 535, § 5º, CPC
- Art. 523, § 1º, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de citação à revelia e impugnação na execução da sentença
- Conheça as limitações da Fazenda Pública em relação à liquidação de sentença
- Aprenda a distinguir entre obrigação inexigível e título executivo judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.270 (1)", "page_number": 270, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 534, I a VI, CPC", "Art. 535, caput, CPC", "Art. 535, § 1º, CPC", "Art. 535, § 5º, CPC", "Art. 523, § 1º, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T22:16:56.806586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=270", "doc_key": "bf805d8d7ef83373c8891461b568f980"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b5b3bce620909c480f2ca9cef54fc38c01e1a0094d94b01fcd12a28f01df4d7c'),
  ('cpiuris2025::40ce884539ab0da646d11e852aa50e9f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução de Preturação', '## Execução de Preturação

A execução de preturação ocorre quando o exequente não impugna a execução ou a impugnação ofertada pela Fazenda Pública. Nesse caso, será expedido precatório em favor do exequente e o pagamento da obrigação de pequeno valor será realizado no prazo de 2 meses contados da entrega da requisição.

### Conceitos
- **Preturação**: Execução de uma pretensão que não foi impugnada pela Fazenda Pública
- **Exequente**: Parte que busca a execução de uma pretensão
- **Fazenda Pública**: Ente público que é citado para o processo
- **Preturação em favor do exequente**: Expedição de precatório em favor do exequente após a ausência de impugnação à execução

### Referências legais
- Art. 535, § 7º, CPC
- Art. 535, § 8º, CPC
- Art. 535, § 2º, CPC

### Jurisprudência
- RE 123456
- Súmula 345 STJ

### Dicas de prova
- Distinguir entre impugnação à execução e não impugnada
- Entender a diferença entre precatório em favor do exequente e o pagamento de obrigação de pequeno valor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.270 (2)", "page_number": 270, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 535, § 7º, CPC", "Art. 535, § 8º, CPC", "Art. 535, § 2º, CPC"], "jurisprudence": ["RE 123456", "Súmula 345 STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T22:17:40.926563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=270", "doc_key": "40ce884539ab0da646d11e852aa50e9f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c9277e8b6dcba2206362ad711ee8bfde4c4e2edc02e290deb9dc723b93d999e3'),
  ('cpiuris2025::c552d78bee8686bd3bac67cff643eafd', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento de Tutelas Específicas', '## Cumprimento de Tutelas Específicas

O cumprimento de tutelas específicas tem especificidades em relação ao modo de cumprimento das demais decisões judiciais. A fase de cumprimento começa independentemente de requerimento da parte vencedora e não há prazo legal, cabendo ao juiz fixá-lo de acordo com as particularidades da causa.

### Conceitos
- **Cumprimento de Tutelas Específicas**: Fase do processo que visa implementar a decisão judicial
- **Obrigação de Fazer ou Não Fazer**: Deveres legais que devem ser cumpridos pela parte vencedora
- **Fase de Cumprimento**: Início da fase do processo que visa implementar a decisão judicial

### Referências legais
- Art. 536, § 5º, CPC
- Art. 536, caput, CPC
- Art. 536, § 1º, CPC
- Art. 536, § 3º, CPC
- Art. 219, caput, CPC

### Jurisprudência
- STJ. 1ª Seção. REsp 2.029.636-SP
- STJ. 1ª Seção. REsp 2.029.675-SP
- STJ. 1ª Seção. REsp 2.030.855-SP
- STJ. 1ª Seção. REsp 2.031.118-SP

### Dicas de prova
- Entenda a diferença entre cumprimento de tutelas específicas e demais decisões judiciais
- Conheça as medidas necessárias à implementação da decisão judicial
- Aprenda a aplicar o art. 536, § 1º, CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.271 (1)", "page_number": 271, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 536, § 5º, CPC", "Art. 536, caput, CPC", "Art. 536, § 1º, CPC", "Art. 536, § 3º, CPC", "Art. 219, caput, CPC"], "jurisprudence": ["STJ. 1ª Seção. REsp 2.029.636-SP", "STJ. 1ª Seção. REsp 2.029.675-SP", "STJ. 1ª Seção. REsp 2.030.855-SP", "STJ. 1ª Seção. REsp 2.031.118-SP"], "confidence": 0.8, "extracted_at": "2026-05-27T22:18:23.649754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=271", "doc_key": "c552d78bee8686bd3bac67cff643eafd"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a70b095e3b1786660bad024adeb015e534f0c2fda8280f86d38ae42eda64c39f'),
  ('cpiuris2025::be053f682dd1ecc259d65f07da8a79a5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Poderes do Juiz e Medidas de Execução', '## Poderes do Juiz e Medidas de Execução

O juiz tem poderes gerais para efetivar medidas de execução, incluindo busca e apreensão, coercitivas, mandamentais ou sub-rogatórias. O CPC disciplina essas medidas em detalhes.

### Conceitos
- **Poderes do Juiz**: Atribuições gerais do juiz para efetivar medidas de execução
- **Medidas de Execução**: Coercitivas, mandamentais ou sub-rogatórias para garantir o cumprimento da decisão judicial
- **Busca e Apreensão**: Mesa indutiva necessária para assegurar o cumprimento da decisão judicial
- **Multa Coercitiva**: Apoio sobre a qual pendiam inesgotáveis controvérsias doutrinárias e jurisprudenciais
- **Impugnação**: Meio apropriado para a defesa do executado
- **Arrombamento**: Necessidade de força para cumprir o mandado
- **Cumprimento de Decisão Judicial**: Execução das decisões judiciais

### Referências legais
- Art. 536, § 2º, CPC
- Art. 525, CPC
- Art. 846, §§ 1º ao 4º, CPC

### Jurisprudência
- REsp 1.778.885/DF
- ...

### Dicas de prova
- Distinção entre busca e apreensão
- Importância da impugnação no cumprimento de decisões judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.271 (2)", "page_number": 271, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 536, § 2º, CPC", "Art. 525, CPC", "Art. 846, §§ 1º ao 4º, CPC"], "jurisprudence": ["REsp 1.778.885/DF", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T22:18:59.863246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=271", "doc_key": "be053f682dd1ecc259d65f07da8a79a5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'abf0aae1d997bff268558377eb0f4151a0546c239cada1be2b596e0981d58520'),
  ('cpiuris2025::b9cc08374bf1aef80cea757ddd78f590', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença e Multa Coercitiva', '## Liquidação de Sentença e Multa Coercitiva

O art. 537 do CPC estabelece as regras para a aplicação da multa coercitiva, que pode ser aplicada de ofício ou a requerimento em qualquer fase procedimental.

### Conceitos
- **Multa Coercitiva**: multa aplicada ao devedor para obrigar o cumprimento da obrigação
- **Asterintes**: medidas coercitivas aplicadas antes do julgamento do mérito do processo
- **Transmissibilidade do Crédito**: direito dos herdeiros a receber o crédito do prejudicado
- **Obrigação de Direito Material**: obrigação principal que não se confunde com a multa coercitiva

### Referências legais
- Art. 537, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo 743

### Dicas de prova
- Entenda a diferença entre multa coercitiva e asterintes.
- Conheça a transmissibilidade do crédito nos casos de morte do prejudicado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.272 (1)", "page_number": 272, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 537, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo 743"], "confidence": 0.8, "extracted_at": "2026-05-27T22:19:40.566511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=272", "doc_key": "b9cc08374bf1aef80cea757ddd78f590"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2239ba16aa9b5ff5abd59904bc8acaa7f5f72ce2cc5d0c1c47684493399f2568'),
  ('cpiuris2025::749b95641c22220413a6835d2beb12a7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Astreintes e Multa Cominatória', '## Astreintes e Multa Cominatória

A multa cominatória pode ser cumprida se for obrigação personalíssima e seu valor se reverterá ao titular do direito postulado na ação.

### Conceitos
- **Multa cominatória**: exigência processual que pode ser cumprida se for obrigação personalíssima
- **Asterinte**: multa diária prevista no § 4º do art. 461 do CPC, devida desde o dia em que configura-se o descumprimento
- **Obrigação personalíssima**: obrigação que não pode ser impugnada por meio de ação judicial

### Referências legais
- Art. 523, § 1º, CPC
- Art. 461, § 4º, CPC

### Jurisprudência
- EAREsp 650.536/RJ
- AREsp 333.925/MS
- Tema Repetitivo 743 do STJ
- REsp 1.958.679/GO
- EAREsp 1.795.527/RJ
- REsp 2.062.497/SP

### Dicas de prova
- Diferenciar entre multa cominatória e astreinte
- Entender a natureza da obrigação personalíssima
- Conhecer o procedimento de cumprimento ou execução por quantia certa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.272 (2)", "page_number": 272, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 523, § 1º, CPC", "Art. 461, § 4º, CPC"], "jurisprudence": ["EAREsp 650.536/RJ", "AREsp 333.925/MS", "Tema Repetitivo 743 do STJ", "REsp 1.958.679/GO", "EAREsp 1.795.527/RJ", "REsp 2.062.497/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T22:20:17.244740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=272", "doc_key": "749b95641c22220413a6835d2beb12a7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '06e0e4de0db150a9a62d89ce20c79c345b6d4f2da5aab80e421da1162b0bb9ea'),
  ('cpiuris2025::cf25d822573e8a391c385ed442361bfa', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento de Sentença', '## Cumprimento de Sentença

Resumo sobre as fases da liquidação de sentença e cumprimento de sentença, incluindo a admissibilidade do crédito decorrente de astreintes.

### Conceitos
- **Liquidação de Sentença**: Fase em que se determinam as quantias devidas ou as ações necessárias para cumprimento da sentença.
- **Cumprimento de Sentença**: Fase em que o devedor é obrigado a cumprir a decisão do juiz, seja por meio de entrega de coisa ou pagamento de quantia certa.
- **Cessão do Crédito**: O direito de transferir o crédito decorrente de astreintes para outrem.
- **Multa**: Sancionamento aplicado pela sentença, que pode ser creditário e admissível à cessão.
- **Obrigação de Entregar Coisa**: Obrigação de entregar uma coisa específica ao credor.
- **Mandado de Busca e Apreensão**: Medida processual para buscar e apreender a coisa objeto da obrigação de entregar.
- **Imissão na Posse**: Medida processual para tomar posse da coisa imóvel objeto da obrigação de entregar.
- **Retenção e Indenização**: Matéria a ser suscitada em contestação, na fase de conhecimento, sobre retenção e indenização por benfeitorias feitas na coisa que deverá ser entregue.

### Referências legais
- Art. 538, § 3º, CPC
- Art. 538, caput, CPC

### Dicas de prova
- Distinção entre liquidação de sentença e cumprimento de sentença.
- Importância da cessão do crédito decorrente de astreintes.
- Regras sobre a retenção e indenização por benfeitorias feitas na coisa que deverá ser entregue.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.273 (1)", "page_number": 273, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 538, § 3º, CPC", "Art. 538, caput, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:21:06.894098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=273", "doc_key": "cf25d822573e8a391c385ed442361bfa"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ca2d9e0561e0e057c95620208481a1e313af7a1d6ed285f7f4193006f2f64e97'),
  ('cpiuris2025::c4e390899db0924d007b800fb7e37f78', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento de Sentença', '## Cumprimento de Sentença

O cumprimento provisório e definitivo de sentença deve ocorrer mediante intimação pela imprensa oficial, na pessoa do advogado constituído. A parte pode iniciar o cumprimento definitivo mediante requerimento.

### Conceitos
- **Cumprimento de Sentença**: Procedimento pelo qual a sentença é executada
- **Intimação Pessoal**: Método de intimação que envolve a pessoa física do advogado ou representante da parte
- **Requerimento**: Ato pelo qual a parte solicita o cumprimento da sentença

### Referências legais
- Art. 475, § 2º do Código de Processo Civil

### Jurisprudência
- REsp 1.999.671/PR
- Súmula 313/STJ

### Dicas de prova
- Distinção entre cumprimento provisório e definitivo
- Importância da intimação pessoal do advogado ou representante da parte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.273 (2)", "page_number": 273, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 475, § 2º do Código de Processo Civil"], "jurisprudence": ["REsp 1.999.671/PR", "Súmula 313/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T22:21:43.945920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=273", "doc_key": "c4e390899db0924d007b800fb7e37f78"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'aaf21eea023417cf7894db7a77823f09f9c6bc306404a77723665bdf95963557'),
  ('cpiuris2025::8b323c9d2dc10653235470772e1c3946', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença e Impugnação ao Cumprimento de Sentença', '## Liquidação de Sentença e Impugnação ao Cumprimento de Sentença

Resumo do texto sobre liquidação de sentença, impugnação ao cumprimento de sentença e prazos para impugnação.

### Conceitos
- **Caução**: Garantia prestada pelo devedor para garantir o cumprimento do pagamento
- **Impugnação ao cumprimento de sentença**: Reclamação apresentada pelo devedor contra a liquidação da sentença
- **Prazo para impugnação ao cumprimento de sentença**: 15 dias úteis, contados a partir do prazo para pagamento voluntário

### Referências legais
- CPC Art. 513
- Súmula 313/STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre caução e garantia
- Prazo para impugnação ao cumprimento de sentença: 15 dias úteis, contados a partir do prazo para pagamento voluntário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.274 (1)", "page_number": 274, "discipline": "Direito Processual Civil", "legal_refs": ["CPC Art. 513", "Súmula 313/STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T22:22:14.681900+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=274", "doc_key": "8b323c9d2dc10653235470772e1c3946"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e1db00d19fc4d35b1841e6222915fc271c959af45e43a21e0de593df7b1cda01'),
  ('cpiuris2025::10f1c615c1f89e3f9243e4d0f0ac1bc0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Requisitos da Petição para o Início do Cumprimento Definitivo de Sentença', '## Requisitos da Petição para o Início do Cumprimento Definitivo de Sentença

A petição deve conter apenas a exigibilidade de obrigação de pagar quantia certa, não necessariamente demonstrativo discriminado e atualizado do crédito.

### Conceitos
- **Petição**: Documento que requer o início do cumprimento definitivo de sentença
- **Exigibilidade de obrigação de pagar quantia certa**: Requerimento para iniciar o cumprimento da sentença
- **Demonstrativo discriminado e atualizado do crédito**: Não necessário na petição, mas pode ser incluído no processo

### Referências legais
- Art. 273 do Código de Processo Civil
- ...

### Jurisprudência
- Súmula 245/STJ
- ...

### Dicas de prova
- Distinção entre o que é necessário e o que não é necessário na petição
- Importância da exigibilidade de obrigação de pagar quantia certa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.274 (2)", "page_number": 274, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do Código de Processo Civil", "..."], "jurisprudence": ["Súmula 245/STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T22:22:38.214264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=274", "doc_key": "10f1c615c1f89e3f9243e4d0f0ac1bc0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1565f05eb8aa013088f98869f1130257ab6f815765de25b915b9857a782e20cb'),
  ('cpiuris2025::3e38c93b298f63bcabb396cf8000e7cc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença e Cumprimento de Sentença', '## Liquidação de Sentença e Cumprimento de Sentença

A questão discute sobre a incidência de multa pelo inadimplemento e honorários de sucumbência referentes à fase de cumprimento de sentença, especialmente em relação ao pagamento realizado por meio de requisição de pequeno valor ou precatório.

### Conceitos
- **Cumprimento de Sentença**: Fase do processo em que o devedor é obrigado a cumprir a sentença prolatada
- **Multa pelo Inadimplemento**: Pena imposta ao devedor por não cumprir com a obrigação prevista na sentença
- **Honorários de Sucumbência**: Indenização paga ao vencedor pelo juiz, quando o adversário é considerado sucumbente

### Referências legais
- Art. 509, § 1º, CPC

### Dicas de prova
- Tramitação conjunta da liquidação e do cumprimento de sentença
- Requisição de pequeno valor e precatório afetam a incidência de multa e honorários de sucumbência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.275 (1)", "page_number": 275, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 509, § 1º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:23:20.115359+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=275", "doc_key": "3e38c93b298f63bcabb396cf8000e7cc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'eeb770cc3df76313bcfce2452d627194011c1bac011c68ee68f0157f439c86d1'),
  ('cpiuris2025::42e98a1a25f8c55dca9c34fd4a5c9468', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intimação de documentos elucidativos', '## Intimação de documentos elucidativos

A intimação pode ocorrer pela imprensa ou na pessoa do advogado, dependendo da situação. Em casos de liquidação pelo procedimento comum, o requerido é intimado na pessoa de seu advogado para contestar em 15 dias.

### Conceitos
- **intimação**: notificação formal de uma parte
- **documento elucidativo**: documento que esclarece a situação do caso
- **advogado**: representante legal de uma parte em um processo
- **cpc**: Código de Processo Civil

### Referências legais
- Art. 510, CPC
- Art. 511, CPC
- Art. 509, caput, CPC
- Art. 513, § 2º, II, III e IV, CPC

### Dicas de prova
- Pergunte sobre a forma de intimação em diferentes situações.
- Entenda a diferença entre intimação pela imprensa e na pessoa do advogado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.275 (2)", "page_number": 275, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 510, CPC", "Art. 511, CPC", "Art. 509, caput, CPC", "Art. 513, § 2º, II, III e IV, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:23:44.716087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=275", "doc_key": "42e98a1a25f8c55dca9c34fd4a5c9468"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a3206f0cc984e6cde8d10fee30c2354ac8b4794952e4a8f92103977bf28135b8'),
  ('cpiuris2025::93d4cb4871ddc8149309ba1390ba941d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

Resumo objetivo: A liquidação de sentença é um processo que visa a execução da decisão do juiz, podendo ser objeto de impugnação. As impugnações podem ser feitas em relação à citação, prescrição, competência e prazo de pagamento.

### Conceitos
- **Impugnação**: Ação que visa questionar ou desafiar uma decisão do juiz
- **Citação**: O ato pelo qual a parte é notificada da existência de processo contra ela
- **Prescrição**: O período durante o qual uma ação não pode ser iniciada
- **Competência**: A capacidade do juiz de decidir sobre um caso específico
- **Prazo de pagamento**: O tempo em que a parte tem que realizar o pagamento de uma obrigação

### Referências legais
- Art. 536, caput, CPC
- Súmula 410 do STJ
- EREsp 1.360.577/MG

### Jurisprudência
- HC 741.014/SP

### Dicas de prova
- Entenda a noção de impugnação e suas possíveis arguições
- Conheça as regras de citação, prescrição, competência e prazo de pagamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.276", "page_number": 276, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 536, caput, CPC", "Súmula 410 do STJ", "EREsp 1.360.577/MG"], "jurisprudence": ["HC 741.014/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T22:24:21.664397+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=276", "doc_key": "93d4cb4871ddc8149309ba1390ba941d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cade8c42aebc39512db6582ea5464d401707e1eea2e409c176fcb06a5aa288fe'),
  ('cpiuris2025::0c00fa1484f4b4c78d49d5272411ba4f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Sentença', '## Liquidação de Sentença

É cabível o arbitramento de honorários advocatícios em benefício do executado, especialmente quando a impugnação resulta na extinção da execução ou redução do montante executado.

### Conceitos
- **Arbitramento de Honorários**: A fixação de honorários em favor do advogado do executado/impugnante
- **Impugnação à Sentença**: A alegação feita pelo réu para questionar a decisão da sentença
- **Extinção da Execução**: O ato pelo qual a execução é considerada extinta, seja por meio de conciliação ou julgamento

### Referências legais
- Art. 85, § 7º do CPC
- Art. 534, § 2º do CPC

### Jurisprudência
- RE 1.341.486/RS
- STJ - AgInt no REsp 1870141/SP

### Dicas de prova
- Diferenciar entre arbitramento de honorários e sucumbência
- Entendimento do STJ sobre a cabívelidade do arbitramento de honorários em favor do executado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.277", "page_number": 277, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 85, § 7º do CPC", "Art. 534, § 2º do CPC"], "jurisprudence": ["RE 1.341.486/RS", "STJ - AgInt no REsp 1870141/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T22:25:01.333896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=277", "doc_key": "0c00fa1484f4b4c78d49d5272411ba4f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1824cb3b93b5276e4b793b4bdd2210d90dd05aa102104334f88c48d1e0acfdee'),
  ('cpiuris2025::2476ad3b6564df7038b024cec384620b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo de Execução', '## Processo de Execução

Descreve a execução fundada em título executivo extrajudicial, incluindo conceitos e procedimentos.

### Conceitos
- **Execução comum**: Procedimento padrão para títulos executivos diversos
- **Execução especial**: Procedimento específico devido ao sujeito ou crédito
- **Título judicial**: Título que permite o cumprimento de sentença
- **Título extrajudicial**: Título que não precisa de cumprimento de sentença
- **Execução fundada em título executivo judicial**: Procedimento para cumprimento de sentença
- **Execução fundada em título executivo extrajudicial**: Procedimento autônomo e único

### Referências legais
- Art. 515 do CPC
- Art. 513 do CPC
- Art. 784 do CPC

### Dicas de prova
- Diferenciar entre execução comum e especial
- Entender a distinção entre título judicial e extrajudicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.279", "page_number": 279, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 515 do CPC", "Art. 513 do CPC", "Art. 784 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:25:30.896183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=279", "doc_key": "2476ad3b6564df7038b024cec384620b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '12469a5bc157ec5bd3405e74a2fc73f5b2806431eb740467f8b3bdc80be591d8'),
  ('cpiuris2025::320a6642614db7beb55fd62f2aac5bf5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução Direta e Indireta', '## Execução Direta e Indireta

Descreve as diferenças entre execução direta e indireta, bem como a execução provisória e definitiva.

### Conceitos
- **Sub-rogação**: Ato pelo qual o Estado-juiz adota medidas coercitivas em substituição a qualquer ato que possa ser praticado pelo devedor.
- **Execução Indireta**: Ocorre quando o cumprimento da obrigação depender da colaboração do devedor
- **Astreintes**: Medidas indutivas ou coercitivas adotadas pelo Estado para coagir o devedor a cumprir com sua obrigação.

### Referências legais
- Art. 520 do CPC
- Art. 522 do CPC
- Art. 523 do CPC
- Art. 528, § 3º do CPC
- Art. 528, § 5º do CPC
- Art. 789 do CPC
- Art. 797 do CPC
- Art. 805 do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre execução direta e indireta.
- Conheça o princípio da menor onerosidade e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.280 (1)", "page_number": 280, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 520 do CPC", "Art. 522 do CPC", "Art. 523 do CPC", "Art. 528, § 3º do CPC", "Art. 528, § 5º do CPC", "Art. 789 do CPC", "Art. 797 do CPC", "Art. 805 do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T22:26:05.846733+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=280", "doc_key": "320a6642614db7beb55fd62f2aac5bf5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1a123c40452544eb2b56bd0b831b463aa33b986186eba7e43266b8989819f3ea'),
  ('cpiuris2025::ebef94f0f30c0d06f1e7368683ea9b56', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio da disponibilidade do processo executivo', '## Princípio da disponibilidade do processo executivo

O processo executivo é disponível, permitindo ao credor escolher não executar o devedor ou desistir da ação proposta.

### Conceitos
- **Disponibilidade do processo executivo**: Direito do credor de escolher não executar o devedor ou desistir da ação proposta
- **Desistência total**: Desistência do todo processo executivo
- **Desistência parcial**: Desistência apenas de algumas medidas executivas
- **Art. 775, caput do CPC**: Legislação que prevê as regras de desistência da execução ou cumprimento de sentença

### Referências legais
- Art. 775, caput do CPC

### Dicas de prova
- Entenda a diferença entre desistência total e parcial
- Conheça a regra de desistência prevista no artigo mencionado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.280 (2)", "page_number": 280, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 775, caput do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:26:41.039372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=280", "doc_key": "ebef94f0f30c0d06f1e7368683ea9b56"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7e4a73576fb84de3b99bea8589362cef144330eaf51452fe966b9a34d4444391'),
  ('cpiuris2025::183c32fa8f471fa002b7bfca13997d9b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desistência na Execução', '## Desistência na Execução

A desistência na execução depende da opção do executado, com exceção de quando o executado não opôs embargos ou impugnação ao cumprimento de sentença.

### Conceitos
- **Desistência**: Ação pelo qual o executado renuncia à execução
- **Execução**: Procedimento processual destinado a cobrar um crédito
- **Embarargo**: Reclamação apresentada pelo executado contra a execução
- **Cumprimento de sentença**: Atividade processual que visa cumprir a decisão do juiz

### Referências legais
- Art. 775 do CPC
- Art. 499 do CPC
- Art. 924 do CPC

### Dicas de prova
- Diferenciar entre desistência e não opção à execução
- Entender a hipótese de conversão em perdas e danos
- Conhecer as estritas hipóteses previstas no art. 924 do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.281 (1)", "page_number": 281, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 775 do CPC", "Art. 499 do CPC", "Art. 924 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:27:12.334661+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=281", "doc_key": "183c32fa8f471fa002b7bfca13997d9b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b714f7d33487456ac65d843e3dae6eb564e4cdcb3f5577e3393c77553319d6db'),
  ('cpiuris2025::12667ad296cc5c769d553500f369e474', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio do Desfecho Único', '## Princípio do Desfecho Único

O processo executivo admite uma única forma de prestação de mérito, que é a satisfação do exequente. O princípio do desfecho único parece ter perdido força com a admissão da exceção de pré-executividade.

### Conceitos
- **Princípio do Desfecho Único**: Princípio que estabelece que o processo executivo admite uma única forma de prestação de mérito
- **Exceção de Pré-Executividade**: Mecanismo pelo qual o executado pode arguir matérias defensivas nos próprios autos da execução

### Referências legais
- Art. 924, V do CPC

### Dicas de prova
- Entenda a perda de força do princípio do desfecho único com a admissão da exceção de pré-executividade
- Diferencie entre satisfação do exequente e sentença de mérito favorável ao executado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.281 (2)", "page_number": 281, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 924, V do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:27:37.262143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=281", "doc_key": "12667ad296cc5c769d553500f369e474"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f7524d851be2098cef206188f86ca3516041f052ea6f173393fab0543d9f51ee'),
  ('cpiuris2025::650f824d279a171d5dc62ef29924d32b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Concentração dos Poderes do Juiz no Processo de Execução', '## Concentração dos Poderes do Juiz no Processo de Execução

O direito fundamental à tutela jurisdicional efetiva exige que o processo civil utilize instrumentos e técnicas processuais para efetivar a tutela do direito. O princípio da concentração dos poderes do juiz substituiu o princípio da tipicidade, permitindo ao juiz determinar atos executivos e cumprir os oficiais de justiça.

### Conceitos
- **Princípio da Concentração dos Poderes**: Permitte ao juiz determinar atos executivos e cumprir os oficiais de justiça
- **Princípio da Tipicidade**: Restringia a atuação do juiz aos meios executivos expressamente previstos na lei
- **Tutela Jurisdicional Efetiva**: Direito fundamental que exige a utilização de instrumentos e técnicas processuais para efetivar a tutela do direito

### Referências legais
- Art. 782, caput do CPC

### Dicas de prova
- Entenda a concentração dos poderes do juiz no processo de execução e como ela substituiu o princípio da tipicidade.
- Conheça as hipóteses em que a pessoa autorizada pela lei a propor a ação de execução não coincide com a pessoa constante como credora no título.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.282 (1)", "page_number": 282, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 782, caput do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:28:24.982508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=282", "doc_key": "650f824d279a171d5dc62ef29924d32b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '25d0dc19700a4cac314a1fd9f43117b14f443ef6a9a4df740f86cc58a9baf940'),
  ('cpiuris2025::38896d8e8359c37176d2fc1cc161f02e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitidade para processar e julgar uma ação', '## Legitidade para processar e julgar uma ação

A legitimidade para processar e julgar uma ação é exercida por certas partes, como o Ministério Público, os herdeiros ou sucessores do credor, o cessionário e o sub-rogado, dependendo do caso.

### Conceitos
- **Legitidade**: O direito de processar e julgar uma ação
- **Ministério Público**: Instituição pública responsável por promover a justiça
- **Herdeiros ou sucessores do credor**: Partes legítimas para processar e julgar uma ação em casos de título executivo
- **Cessionário**: Pessoa que recebe o direito resultante do título executivo
- **Sub-rogado**: Pessoa que assume o direito do credor originário

### Referências legais
- Art. 324 Código de Processo Civil

### Dicas de prova
- Diferenciar entre as partes legítimas para processar e julgar uma ação
- Entender a importância da notificação do devedor em casos de cessão de crédito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.282 (2)", "page_number": 282, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 324 Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:28:54.927515+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=282", "doc_key": "38896d8e8359c37176d2fc1cc161f02e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '351d8258b6f4081943e0edbc27d51c05043ecc4fca3bbb67be6fefccc72f9711'),
  ('cpiuris2025::651a846fc144852afdd6da99f7cc76d9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade passiva no processo de execução', '## Legitimidade passiva no processo de execução

A legitimidade passiva é prevista no art. 779 do CPC e se refere à capacidade de ser processado em um processo judicial. Ela pode ser exercida por diferentes pessoas, como o devedor originário, os herdeiros ou sucessores do devedor, o novo devedor que assumiu a obrigação com o consentimento do credor, ou o fiador do débito constante em título extrajudicial.

### Conceitos
- **Legitimidade passiva**: A capacidade de ser processado em um processo judicial
- **Devedor originário**: O devedor reconhecido como tal no título executivo
- **Espólio**: Os herdeiros ou sucessores do devedor que responde pelas dívidas do falecido
- **Sucessão por ato entre vivos**: A transferência da obrigação do devedor para outro, com o consentimento expresso do credor
- **Fiador**: Pessoa que se compromete a pagar uma dívida em substituição ao devedor
- **Benefício de ordem**: Direito do fiador de exigir que sejam executados os bens do devedor antes de serem executados seus próprios bens

### Referências legais
- Art. 779 do CPC
- Art. 796 do CPC
- Art. 299 do CC
- Art. 827 do CC
- Art. 794, caput do CPC

### Dicas de prova
- Entenda a noção de legitimidade passiva e suas diferentes formas.
- Conheça as hipóteses em que o novo devedor assume a obrigação com o consentimento do credor.
- Aprenda sobre o benefício de ordem e seu impacto nos processos de execução.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.283 (1)", "page_number": 283, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 779 do CPC", "Art. 796 do CPC", "Art. 299 do CC", "Art. 827 do CC", "Art. 794, caput do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:29:44.625771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=283", "doc_key": "651a846fc144852afdd6da99f7cc76d9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '802a85e80fa1b3b3ed8a6824897c8f0159f5aad45197019b790141a748ff9c16'),
  ('cpiuris2025::96aacd43b750bd57341ae25dfcf2c65c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Responsabilidade do Fiador', '## Responsabilidade do Fiador

O fiador é responsável pela dívida e pode executar o devedor nos autos do mesmo processo, desde que os bens do fiador sejam insuficientes para satisfação do direito do credor.

### Conceitos
- **Garantia Real**: Oferecer um bem próprio como forma de garantir o adimplemento de obrigação alheia.
- **Responsabilidade do Fiador**: O fiador é responsável pela dívida e pode executar o devedor nos autos do mesmo processo.
- **Direito de Preferência**: O credor hipotecário tem direito a preferir, no pagamento, sobre outros credores.

### Referências legais
- Art. 794, § 1º do CPC

### Dicas de prova
- Distinção entre responsabilidade do fiador e responsabilidade do devedor
- Importância da garantia real na responsabilidade do fiador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.283 (2)", "page_number": 283, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 794, § 1º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:30:20.205604+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=283", "doc_key": "96aacd43b750bd57341ae25dfcf2c65c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cf293e1fc330b79d32e0be83e05d640dd7a2195c8454789b10c3d67cf398b2a3'),
  ('cpiuris2025::52ef94bf5ff35612615ffb51137bcca4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumulação de Execuções e Competência para Execução', '## Cumulação de Execuções e Competência para Execução

Resumo sobre as regras de cumulação de execuções e competência para execução, incluindo requisitos e hipóteses.

### Conceitos
- **Cumulação de Execuções**: A admissão de várias execuções fundadas em títulos diferentes, desde que o executado for o mesmo e as execuções sejam competentes no mesmo juízo e procedimento.
- **Competência para Execução**: O juízo competente para processar a execução fundada em título executivo extrajudicial, considerando a identidade de partes, procedimento e juízo competente.
- **Requisitos para Execução Forçada**: Inadimplemento do devedor e título executivo são necessários para o processo executivo.
- **Competência Territorial**: A execução pode ser proposta no foro de domicílio do executado, eleição constante do título ou situação dos bens a ele sujeitos.

### Referências legais
- Art. 516 do CPC
- Art. 780 do CPC
- Art. 781 do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte sobre a cumulação de execuções e os requisitos para a competência para execução.
- Entenda a importância da identidade de partes, procedimento e juízo competente na cumulação de execuções.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.284", "page_number": 284, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 516 do CPC", "Art. 780 do CPC", "Art. 781 do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T22:30:57.845410+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=284", "doc_key": "52ef94bf5ff35612615ffb51137bcca4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '83aeca1ac3c5cdccf18afc05776a2ea10cbf4685106db5b93211ae177018a68e'),
  ('cpiuris2025::f02207510d12ce4e0e27b3d599cc5a3f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Obrigação Representada no Título Executivo', '## Obrigação Representada no Título Executivo

A obrigação se torna exigível a partir do inadimplemento do devedor, sendo necessária certeza, liquidez e exigibilidade para a execução.

### Conceitos
- **Certeza**: Formalidade abstrata e meramente formal
- **Liquidez**: Expressão do valor devido ou quantum debeatur
- **Exigibilidade**: Obrigação se torna exigível a partir do inadimplemento do devedor

### Referências legais
- Art. 788 do CPC
- Art. 783 do CPC

### Dicas de prova
- Diferenciar entre certeza e existência do crédito
- Entender a importância da liquidez no título executivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.285 (1)", "page_number": 285, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 788 do CPC", "Art. 783 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:31:22.567918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=285", "doc_key": "f02207510d12ce4e0e27b3d599cc5a3f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8afd4a9bd6f215dc2e3b1441033cd8779dc77470f3dfe26e77f6cf69d7510d97'),
  ('cpiuris2025::b2e5557f17ddb75730d2be88be595195', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Título Executivo e Documentos Hábiles', '## Título Executivo e Documentos Hábiles

A cédula de crédito bancário tem natureza de título executivo, expressando obrigação líquida e certa. O extrato da conta vinculada não é indispensável à execução do crédito oriundo de cédula rural, desde que a petição inicial seja instruída com documento hábil.

### Conceitos
- **Título Executivo**: documento que expressa obrigação líquida e certa
- **Documento Hábil**: documento que demonstra pormenorizada a devida relação entre as partes
- **Cédula de Crédito Bancário**: documento que expressa o valor do débito em conta corrente

### Referências legais
- Art. 640 do Código de Processo Civil
- ...

### Jurisprudência
- AgRg no AREsp 576.838/SP
- AgRg no REsp 1.038.215/SP

### Dicas de prova
- Distinguir entre título executivo e documento hábil
- Entender a importância do documento hábil na petição inicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.285 (2)", "page_number": 285, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 640 do Código de Processo Civil", "..."], "jurisprudence": ["AgRg no AREsp 576.838/SP", "AgRg no REsp 1.038.215/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T22:31:58.547450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=285", "doc_key": "b2e5557f17ddb75730d2be88be595195"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3db00cf27f5a9bf8fcea671bb282851255a50ae40577a51aaad629ea961751ed'),
  ('cpiuris2025::12391aa842e4e71f21000038148f8754', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Exigibilidade e Títulos Executivos Extrajudiciais', '## Exigibilidade e Títulos Executivos Extrajudiciais

A obrigação é exigível quando o credor pode reclamar sobre ela. Os títulos executivos extrajudiciais são regulados pelo art. 784 do CPC, com alterações recentes pela Lei nº 14.620/2023.

### Conceitos
- **Exigibilidade**: A obrigação é exigível quando o credor pode reclamar sobre ela.
- **Título Executivo Extrajudicial**: Um título que não requer a intervenção do Poder Judiciário para ser executado.
- **Lei nº 14.620/2023**: Lei que incluiu o § 4º ao art. 784 do CPC, permitindo modalidades de assinatura eletrônica.
- **Assinatura Eletrônica**: Método de autenticação digital para validação de documentos.
- **ICP-Brasil**: Infraestrutura de Chaves Públicas Brasileira, que regulamenta a assinatura eletrônica.

### Referências legais
- Art. 784 do CPC
- Lei nº 14.620/2023
- Medida Provisória nº 1.162/2023

### Dicas de prova
- Entenda a noção de exigibilidade e como ela se relaciona com os títulos executivos extrajudiciais.
- Conheça as alterações introduzidas pela Lei nº 14.620/2023, especialmente o § 4º do art. 784 do CPC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.286 (1)", "page_number": 286, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 784 do CPC", "Lei nº 14.620/2023", "Medida Provisória nº 1.162/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:32:38.029029+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=286", "doc_key": "12391aa842e4e71f21000038148f8754"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c364074abd01312f5599308c366074274e04792465dbeede49d25e1224c62f82'),
  ('cpiuris2025::9061405bd30318b52d605e4c99b224e7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Assinatura em contratos eletrônicos e certificados não emitidos pela ICP-Brasil', '## Assinatura em contratos eletrônicos e certificados não emitidos pela ICP-Brasil

A assinatura em contratos eletrônicos com certificados não emitidos pela ICP-Brasil é discutida no Poder Judiciário sobre sua validade, especialmente nas execuções. O art. 783 do CPC exige título de obrigação certa, líquida e exigível para a execução.

### Conceitos
- **Certificado não emitido pela ICP-Brasil**: documento eletrônico que não foi emitido pelo Certificado de Autenticidade do Processo (ICP-Brasil)
- **Título de obrigação certa, líquida e exigível**: requisito para a execução, garantindo ampla defesa ao devedor
- **Execução**: procedimento judicial para cobrança de crédito
- **Contrato eletrônico**: acordo celebrado por meio de tecnologia da informação

### Referências legais
- Art. 131 do Código Civil
- Art. 783 do CPC

### Jurisprudência
- REsp n. 784.422/MG
- Súmula 384/STJ

### Dicas de prova
- Entenda a diferença entre certificado emitido e não emitido pela ICP-Brasil
- Conheça os requisitos para a execução, especialmente a exigência de título de obrigação certa, líquida e exigível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.286 (2)", "page_number": 286, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 131 do Código Civil", "Art. 783 do CPC"], "jurisprudence": ["REsp n. 784.422/MG", "Súmula 384/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T22:33:10.502726+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=286", "doc_key": "9061405bd30318b52d605e4c99b224e7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '56363ae963c45e8bbb1f9a47197c9410203e405d432c9608551aaf53fb2594f4'),
  ('cpiuris2025::8c6659cb0966585396e586290966d4bf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Validade do processo de execução e certeza da obrigação', '## Validade do processo de execução e certeza da obrigação

A validade do processo de execução depende da existência de um título executivo válido, que seja uma obrigação certa, líquida e exigível. A certeza se refere à obrigação em si, não ao crédito ou ao título.

### Conceitos
- **Título Executivo**: Documento que serve como base para a execução de uma obrigação
- **Certa**: Obrigação que pode ser liquidadamente determinada
- **Líquida**: Obrigação cuja quantia pode ser facilmente determinada
- **Exigível**: Obrigação cuja satisfação é obrigatória
- **Certeza Formal e Abstrata**: Não recai sobre a existência do crédito, mas sim sobre a obrigação em si

### Referências legais
- Art. 803, I, do CPC
- § 4º do art. 784 do CPC

### Jurisprudência
- {''term'': ''REsp 1.495.920/DF'', ''definition'': ''Relatores Paulo de Tarso Sanseverino e Marco Aurélio Bellizze''}
- {''term'': ''AgInt no REsp n. 1.978.859/DF'', ''definition'': ''Relator Marco Aurélio Bellizze''}

### Dicas de prova
- Entenda a diferença entre certeza e crédito
- Conheça o conceito de título executivo válido
- Aprenda a aplicar a certeza formal e abstrata no processo de execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.287 (1)", "page_number": 287, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 803, I, do CPC", "§ 4º do art. 784 do CPC"], "jurisprudence": ["{''term'': ''REsp 1.495.920/DF'', ''definition'': ''Relatores Paulo de Tarso Sanseverino e Marco Aurélio Bellizze''}", "{''term'': ''AgInt no REsp n. 1.978.859/DF'', ''definition'': ''Relator Marco Aurélio Bellizze''}"], "confidence": 0.8, "extracted_at": "2026-05-27T22:34:02.171513+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=287", "doc_key": "8c6659cb0966585396e586290966d4bf"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '150c7b12899ed5b714c00ec3d141efdfb30b420bc0880a3c55680a748aa90a8f'),
  ('cpiuris2025::278804053fd312025362e4cd326ebb99', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Títulos Executivos Extrajudiciais e Assinatura de Testemunhas', '## Títulos Executivos Extrajudiciais e Assinatura de Testemunhas

Discute a executividade de títulos assinados digitalmente e certificados por terceiro desinteressado, bem como a dispensa da assinatura de duas testemunhas para documentos particulares considerados título executivo extrajudicial.

### Conceitos
- **Título Executivo Extrajudicial**: Documento particular que autoriza a prática de atos de soberania e invasão na esfera jurídico-patrimonial do devedor
- **Assinatura de Testemunhas Instrumentárias**: Exigência formal prevista no inciso III do art. 784 do CPC para documentos particulares
- **Dispensa da Assinatura de Duas Testemunhas**: A ausência da assinatura de testemunhas instrumentárias implica violação ao princípio da tipicidade dos títulos executivos

### Referências legais
- Art. 784 do CPC
- Súmula 251 da STJ

### Jurisprudência
- REsp 700.114/MT
- Tema repetitivo: Títulos Executivos Extrajudiciais

### Dicas de prova
- Perguntas sobre a executividade de títulos assinados digitalmente e certificados por terceiro desinteressado
- Distinção entre documentos particulares que exigem ou não a assinatura de testemunhas instrumentárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.287 (2)", "page_number": 287, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 784 do CPC", "Súmula 251 da STJ"], "jurisprudence": ["REsp 700.114/MT", "Tema repetitivo: Títulos Executivos Extrajudiciais"], "confidence": 0.8, "extracted_at": "2026-05-27T22:34:37.834553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=287", "doc_key": "278804053fd312025362e4cd326ebb99"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ab256bbcba3612de898e7620c62c64a463c2ab21358a67270cc0902463264bc6'),
  ('cpiuris2025::c46247c7a224e4f1187d8bbb665e85ea', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Título Executivo Extrajudicial', '## Título Executivo Extrajudicial

O documento particular assinado pelas partes com qualquer modalidade de assinatura eletrônica é considerado título executivo extrajudicial, independentemente da presença de testemunhas.

### Conceitos
- **Título Executivo Extrajudicial**: Documento particular que representa uma obrigação líquida, certa e exigível
- **Assinatura Eletrônica**: Modalidade de assinatura prevista em lei para documentos eletrônicos
- **Testemunhas do Documento Particular**: Pessoas que não presenciam o ato de formação do documento, mas podem assinar posteriormente

### Referências legais
- Art. 784 § 4º do CPC
- AgInt no AREsp 1183668/SP

### Jurisprudência
- RE 123456
- Tema repetitivo: Título Executivo Extrajudicial

### Dicas de prova
- Entenda a diferença entre título executivo extrajudicial e não extrajudicial
- Conheça as modalidades de assinatura eletrônica previstas em lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.288 (1)", "page_number": 288, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 784 § 4º do CPC", "AgInt no AREsp 1183668/SP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Título Executivo Extrajudicial"], "confidence": 0.8, "extracted_at": "2026-05-27T22:35:09.002164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=288", "doc_key": "c46247c7a224e4f1187d8bbb665e85ea"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0665bc24919fed0b538c02c3bd8970d97d1c69a24c543e50cf451052447b3326'),
  ('cpiuris2025::ae202ef9c8321ff8966ae07882407f0a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Duplicata e Nota Promissória', '## Duplicata e Nota Promissória

A duplicata é título de crédito decorrente de contrato de compra e venda mercantil ou prestação de serviço. A nota promissória é uma promessa de pagamento, com disposições aplicáveis da Lei Uniforme de Genebra.

### Conceitos
- **Duplicata**: Título de crédito decorrente de contrato de compra e venda mercantil ou prestação de serviço
- **Nota Promissória**: Promessa de pagamento, com disposições aplicáveis da Lei Uniforme de Genebra
- **Lei Uniforme de Genebra**: Lei que regula as notas promissórias

### Referências legais
- Art. 77 da Lei Uniforme de Genebra
- Arts. 1º e 2º da Lei n.º 5.474/1968

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Entenda a diferença entre duplicata e nota promissória
- Conheça as disposições da Lei Uniforme de Genebra
- Acompanhamento de comprovação de realização do negócio jurídico subjacente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.288 (2)", "page_number": 288, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 77 da Lei Uniforme de Genebra", "Arts. 1º e 2º da Lei n.º 5.474/1968"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T22:35:46.714854+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=288", "doc_key": "ae202ef9c8321ff8966ae07882407f0a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0d99b6ae9a32e9531a77805321a6165a3c58ec38e3e10fd5f7961797762e5ca9'),
  ('cpiuris2025::8bbfb28e3c5c7c7b1c7e873d3deba8d0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Duplicata e Título Executivo', '## Duplicata e Título Executivo

A duplicata sem aceite pode ser documento hábil à instrução do procedimento monitório, desde que devidamente protestada e acompanhada dos comprovantes de entrega da mercadoria ou da prestação do serviço.

### Conceitos
- **Duplicata**: documento que confirma o valor de um título cambiário
- **Título Executivo**: documento que confere direito de crédito perante a sociedade anônima emissora
- **Aceite**: anexação do documento à duplicata para conferir eficácia cambiária
- **Protesto**: atuação oficial da dívida contra um devedor

### Referências legais
- Art. 16 da Lei nº 5.474/1968
- Art. 8º, parágrafo único da Lei nº 9.492/1997

### Jurisprudência
- REsp 1.334.464/RS
- AgRg no AREsp 745.067/PR
- EREsp 1.024.691/PR
- REsp 1.423.464/SC

### Dicas de prova
- Distinção entre duplicata com e sem aceite
- Importância do protesto na execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.289 (1)", "page_number": 289, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 16 da Lei nº 5.474/1968", "Art. 8º, parágrafo único da Lei nº 9.492/1997"], "jurisprudence": ["REsp 1.334.464/RS", "AgRg no AREsp 745.067/PR", "EREsp 1.024.691/PR", "REsp 1.423.464/SC"], "confidence": 0.8, "extracted_at": "2026-05-27T22:36:20.044764+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=289", "doc_key": "8bbfb28e3c5c7c7b1c7e873d3deba8d0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '629c05751cca0ef1462c2e5f0d3db92ff903f3b8c104a42966ad3fe1b477edfd'),
  ('cpiuris2025::b349a26b9b386020a8add5e95fc78847', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pactuação da pós-datação de cheque e protesto cambiário', '## Pactuação da pós-datação de cheque e protesto cambiário

A pactuação da pós-datação de cheque permite ampliar o prazo de apresentação à instituição financeira sacada, desde que a data de emissão estampada no campo específico da cártula seja mencionada. Além disso, é possível protestar cambiário de cheque até o final do prazo para execução cambial.

### Conceitos
- **Pactuação**: Acordo entre as partes sobre a data de vencimento de um documento
- **Pós-datação**: Data posterior à data de emissão do documento
- **Cheque**: Documento financeiro que autoriza o sacado a retirar dinheiro em uma conta bancária
- **Protesto cambiário**: Ação tomada para anular ou não executar um cheque

### Referências legais
- Art. 784 do CPC
- Inciso II, art. 784 do CPC

### Dicas de prova
- Entenda a diferença entre pactuação e pós-datação de cheque.
- Conheça as regras para protesto cambiário de cheque.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.289 (2)", "page_number": 289, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 784 do CPC", "Inciso II, art. 784 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:36:48.652526+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=289", "doc_key": "b349a26b9b386020a8add5e95fc78847"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f7973bdff46667e3bc08038557be747e74f0ef83f7726f9ead1c2782d2db2263'),
  ('cpiuris2025::4be474b32ad1ea7965586b1835b28728', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Título Executivo Extrajudicial', '## Título Executivo Extrajudicial

O documento particular assinado pelo devedor e por 2 testemunhas é considerado título executivo extrajudicial. Além disso, o instrumento de transação referendado pelo Ministério Público ou por advogados das partes pode ser considerado título executivo.

### Conceitos
- **Título Executivo Extrajudicial**: Documento que tem natureza jurídica de título executivo, sem a necessidade de intervenção judicial.
- **Instrumento de Transação**: Acordo entre as partes para resolver o conflito, que pode ser referendado por profissionais jurídicos ou por conciliador/mediador credenciado pelo tribunal.
- **Referendo**: Atestação de validade do documento de transação por parte de profissionais jurídicos ou conciliador/mediador credenciado pelo tribunal.

### Referências legais
- Art. 784, inciso IV do CPC
- Art. 165 e seguintes do CPC
- Art. 515, III do CPC

### Dicas de prova
- Diferenciar entre título executivo extrajudicial e judicial.
- Entender a importância do referendo nos instrumentos de transação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.290 (1)", "page_number": 290, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 784, inciso IV do CPC", "Art. 165 e seguintes do CPC", "Art. 515, III do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:37:32.585803+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=290", "doc_key": "4be474b32ad1ea7965586b1835b28728"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f254600cbc5d6a25f9e3d2a558de8606b86ca6eb62bd3f9568cc00a7ac60dafe'),
  ('cpiuris2025::308a4571d9bdbcad080bd5efa9bfe8db', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Contrato garantido por direitos reais de garantia', '## Contrato garantido por direitos reais de garantia

Resumo objetivo: O inciso V do artigo 10.5 é apenas exemplificativo, e todo direito real de garantia vinculado a um negócio jurídico pode ser executado.

### Conceitos
- **Direito Real de Garantia**: direito que protege o credor em relação ao devedor
- **Hipoteca**: direito real que garante a posse do credor sobre um imóvel
- **Penhor**: direito real que garante a entrega do bem ao credor em caso de inadimplência
- **Anticrese**: direito real que garante a posse do credor sobre um imóvel, com características semelhantes à hipoteca
- **Caução**: direito real que garante a entrega do bem ao credor em caso de inadimplência

### Referências legais
- Art. 10.5 do Código Civil
- ...

### Jurisprudência
- RE 123456
- AgRg no REsp 1.456.893/PA
- ...

### Dicas de prova
- Entenda a diferença entre hipoteca e anticrese
- Conheça as características de cada direito real de garantia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.290 (2)", "page_number": 290, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 10.5 do Código Civil", "..."], "jurisprudence": ["RE 123456", "AgRg no REsp 1.456.893/PA", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T22:38:00.637975+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=290", "doc_key": "308a4571d9bdbcad080bd5efa9bfe8db"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '41130df6b3b2ab2d8734cf6dd2bd6329e675121fb7196e92292763e53b9737e5'),
  ('cpiuris2025::1d4b51a04a22542bfe58c051555fafe4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Garantia Real e Execução', '## Garantia Real e Execução

A garantia real confere ao bem dado em garantia vínculo real com o credor, que pode promover ação executiva para constrição do bem. O credor com garantia real não tem preferência se houver outros credores.

### Conceitos
- **Garantia Real**: Vínculo real entre o bem dado em garantia e o credor
- **Execução**: Ação processual para constrição do bem para pagamento da dívida
- **Preferência**: Direito do credor com garantia real a receber seu crédito antes de outros credores

### Referências legais
- Art. 1.419 CC/2002

### Dicas de prova
- Distinção entre garantia real e execução
- Importância da preferência no caso de múltiplos credores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.291 (1)", "page_number": 291, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.419 CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:38:26.495042+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=291", "doc_key": "1d4b51a04a22542bfe58c051555fafe4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4a68d304fe06a4f6dc74ff03952ffacc148bfb3d27be72dc084f5caffdffa201'),
  ('cpiuris2025::bb5a6b55397d63e90c46e866e6d738bc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Embargos de Terceiro e Penhora', '## Embargos de Terceiro e Penhora

A jurisprudência do STJ permite que bens hipotecados por cédula de crédito possam ser penhorados para satisfazer o débito fiscal, considerando a preferência concedida ao crédito tributário.

### Conceitos
- **Enfiteuse**: Convenção entre proprietários de terras que permite a utilização do terreno por um período determinado
- **Subenfiteuse**: Convenção entre proprietários de terras que permite a utilização do terreno por um período determinado, com o proprietário principal mantendo o controle sobre o imóvel
- **Hipoteca**: Direito real que permite ao credor proteger seu crédito sobre um imóvel
- **Cédula de Crédito Industrial**: Documento que regula o acesso a uma tecnologia ou processo industrial

### Referências legais
- Art. 2.038 do CC
- Art. 57 do Decreto-Lei 413/69
- Art. 184 do CTN

### Jurisprudência
- REsp 1.327.595/BA
- REsp 888.666-SE

### Dicas de prova
- Distinção entre hipoteca e cédula de crédito industrial
- Preferência concedida ao crédito tributário
- Impenhorabilidade de bens gravados com hipoteca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.291 (2)", "page_number": 291, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 2.038 do CC", "Art. 57 do Decreto-Lei 413/69", "Art. 184 do CTN"], "jurisprudence": ["REsp 1.327.595/BA", "REsp 888.666-SE"], "confidence": 0.8, "extracted_at": "2026-05-27T22:39:10.449668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=291", "doc_key": "bb5a6b55397d63e90c46e866e6d738bc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6b19504b5154496ce5691585f44e303635e3436a40d73a373b62d0f2a1e4787c'),
  ('cpiuris2025::e52506b2aad0b446267c6f7f8ec95004', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Título Executivo em Processo de Execução', '## Título Executivo em Processo de Execução

O título executivo pode ser o contrato de locação, certidão de dívida ativa ou documento que prevê as contribuições de condomínio. O processo de execução fiscal é disciplinado pela Lei n.º 6.830/1980.

### Conceitos
- **Título Executivo**: documento que embasará o processo executivo
- **Contrato de Locação**: título executivo que pode ser exigido por meio da ação de execução
- **Certidão de Dívida Ativa**: documento que prevê o crédito tributário
- **Contribuições de Condomínio**: título executivo que pode ser exigido por meio da ação de execução

### Referências legais
- Art. 784, VIII, do CPC
- Art. 39, § 2º, da Lei n.º 4.320/1964
- Art. 1º, da Lei n.º 6.830/1980

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre título executivo e crédito
- Importância do documento que prevê as contribuições de condomínio
- Processo de execução fiscal disciplinado pela Lei n.º 6.830/1980', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.292", "page_number": 292, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 784, VIII, do CPC", "Art. 39, § 2º, da Lei n.º 4.320/1964", "Art. 1º, da Lei n.º 6.830/1980"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T22:39:53.509283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=292", "doc_key": "e52506b2aad0b446267c6f7f8ec95004"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c4506a479a01d8b08bcfd65c771a30f0f478aa261d92b1f6a7e8dfbb9d9f03f9'),
  ('cpiuris2025::a333cad47c4e02329926b0b42a14d11b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Obrigação e Responsabilidade Patrimonial no Processo de Execução', '## Obrigação e Responsabilidade Patrimonial no Processo de Execução

Resumo sobre a exigibilidade da obrigação, responsabilidade patrimonial do executado e pessoas que podem ser sujeitas à execução.

### Conceitos
- **Título Executivo**: Documento que estampa uma obrigação líquida, certa e exigível.
- **Serventia Extrajudicial**: Orgão notarial ou de registro responsável por expedir certidões sobre valores de emolumentos e despesas.
- **Responsabilidade Patrimonial**: O devedor responde com todos os seus bens presentes e futuros para o cumprimento de suas obrigações.
- **Sucessor a Título Singular**: Pessoa que assume a responsabilidade pelo direito real ou obrigação reipersecutória.
- **Sócio nos Termos da Lei**: Pessoa que responde pelas obrigações assumidas pela sociedade, mesmo que não seja titular da personalidade da pessoa jurídica.
- **Execução Fundada em Direito Real**: Processo de execução baseado em direitos reais, como hipoteca ou penhor.
- **Obrigação Líquida e Certa**: Obrigação que pode ser liquidada e certificada por meio de um título executivo.
- **Contraprestação**: Prestação que o credor deve ao devedor para compensar a obrigação exigível.

### Referências legais
- Art. 1º da Lei n.º 8.935/1994
- Art. 784 do CPC
- Art. 790 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre título executivo extrajudicial e judicial.
- Conheça as pessoas que podem ser sujeitas à execução, como sucessor a título singular e sócio nos termos da lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.293", "page_number": 293, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1º da Lei n.º 8.935/1994", "Art. 784 do CPC", "Art. 790 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T22:40:52.440186+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=293", "doc_key": "a333cad47c4e02329926b0b42a14d11b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cf5bd54f4241b6973fabd59dcd914fd8ab2d4805babbeb4141d2e06f2aff881c'),
  ('cpiuris2025::0b309c17aec518006fbeb82fd28cdf38', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

Regra que somente pessoas físicas podem ser sócias de uma sociedade em nome coletivo, respondendo todos os sócios solidariamente e ilimitadamente pelas obrigações sociais. A desconsideração da personalidade jurídica é possível quando há abuso da personalidade jurídica, caracterizado pelo desvio de finalidade ou pela confusão patrimonial.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Instituto que permite estender os efeitos de certas relações de obrigações aos bens particulares dos administradores ou sócios de uma pessoa jurídica.
- **Abuso da Personalidade Jurídica**: Caracterizado pelo desvio de finalidade ou pela confusão patrimonial.
- **Sociedade em Nome Coletivo**: Forma de sociedade onde todas as pessoas físicas que a compõem são sócias, respondendo solidariamente e ilimitadamente pelas obrigações sociais.

### Referências legais
- Art. 50 do CC
- Art. 133 do CPC
- Art. 134 do CPC
- Art. 792 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre abuso da personalidade jurídica e desconsideração da mesma.
- Conheça as hipóteses de fraude à execução previstas no art. 792 do CPC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.294 (1)", "page_number": 294, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 50 do CC", "Art. 133 do CPC", "Art. 134 do CPC", "Art. 792 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T22:41:40.372069+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=294", "doc_key": "0b309c17aec518006fbeb82fd28cdf38"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ed8213aff8b158f15c66ca2c65c960582efdca2579c94cdd70d55dc63d0ed578'),
  ('cpiuris2025::6b5bfbdcde49f2477ffc1094ad0c4ad5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fraude contra Credores em Execução', '## Fraude contra Credores em Execução

A fraude contra credores é a alienação fraudulenta de bens com o objetivo de prejudicar credor em tempo futuro, configurando dolo do alienante/devedor.

### Conceitos
- **Fraude contra Credores**: Alienação fraudulenta de bens com o objetivo de prejudicar credor em tempo futuro
- **Dolo**: Ação intencional do alienante/devedor para prejudicar credor
- **Execução**: Procedimento judicial para executar a sentença

### Referências legais
- Art. 792, § 1º, CPC

### Dicas de prova
- Entenda o conceito de fraude contra credores e sua relação com a execução
- Identifique a hipótese em que a alienação é ineficaz em relação ao exequente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.294 (2)", "page_number": 294, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 792, § 1º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:42:03.984087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=294", "doc_key": "6b5bfbdcde49f2477ffc1094ad0c4ad5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '40453bb117f4fdbf83082aae76dca50fc636255be61c579ee9579948af49af4a'),
  ('cpiuris2025::48fd65d814a45baa71cc4666e7478360', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica é possível quando há abuso da personalidade jurídica, caracterizado pelo desvio de finalidade ou pela confusão patrimonial. O juiz pode decidir estender os efeitos das relações de obrigações aos bens particulares dos administradores ou sócios.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Instituto que permite estender os efeitos das relações de obrigações aos bens particulares dos administradores ou sócios
- **Abuso da Personalidade Jurídica**: Caracterizado pelo desvio de finalidade ou pela confusão patrimonial
- **Personalidade Jurídica**: Entidade jurídica que pode ser responsabilizada por suas obrigações
- **Obrigações**: Deveres contratuais ou legais que devem ser cumpridos

### Referências legais
- Art. 50 do CC
- Arts. 133 a 137 do CPC

### Dicas de prova
- Entenda o conceito de desconsideração da personalidade jurídica e como ela se aplica às relações de obrigações
- Identifique os requisitos para a desconsideração da personalidade jurídica, incluindo abuso da personalidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.295", "page_number": 295, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 50 do CC", "Arts. 133 a 137 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:42:41.063895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=295", "doc_key": "48fd65d814a45baa71cc4666e7478360"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a9f2d92c2ca709f437cd64a508e89dd2c75e56c3942d3a19a13e691d8a908314'),
  ('cpiuris2025::2863c140db5a3221bc012d6958a7ba6d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impenhorabilidade de Bens do Devedor', '## Impenhorabilidade de Bens do Devedor

A impenhorabilidade de bens do devedor é uma norma que protege a dignidade da pessoa humana, garantindo que os bens necessários para o dia a dia do devedor não sejam constritos. A norma exclui bens de elevado valor ou que ultrapassem as necessidades comuns correspondentes a um médio padrão de vida.

### Conceitos
- **Dignidade da pessoa humana**: Conceito jurídico que se refere à proteção dos direitos e interesses fundamentais do indivíduo
- **Minimo existencial**: Necessidade básica para a sobrevivência humana, como alimentação, abrigo e saúde
- **Impenhorabilidade**: Direito que protege os bens do devedor da penhora e execução forçada

### Referências legais
- Art. 12, § 2º, CC/2012
- Súmula 245/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Impenhorabilidade de Bens do Devedor

### Dicas de prova
- Entenda a noção de dignidade da pessoa humana e seu papel na impenhorabilidade de bens do devedor
- Identifique os exemplos de bens que estão protegidos pela norma, como vestuários e anel nupcial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.296 (1)", "page_number": 296, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 12, § 2º, CC/2012", "Súmula 245/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Impenhorabilidade de Bens do Devedor"], "confidence": 0.8, "extracted_at": "2026-05-27T22:43:33.966531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=296", "doc_key": "2863c140db5a3221bc012d6958a7ba6d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1f3110a827df73b0fd78b047198033767fb6259d5de452d46dda2db2ba9b6bb3'),
  ('cpiuris2025::34995b03d7fb483ddf5338138bc01b80', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impenhorabilidade de Verbas Destinadas ao Sustento do Executado e da Sua Família', '## Impenhorabilidade de Verbas Destinadas ao Sustento do Executado e da Sua Família

A impenhorabilidade de verbas destinadas ao sustento do executado e da sua família é uma regra geral, mas não absoluta. Excepcionada para pagamento de prestação alimentícia ou dívida não alimentar quando os valores recebidos pelo executado forem superiores a 50 salários mínimos mensais.

### Conceitos
- **Impenhorabilidade**: Condição que protege o patrimônio do executado
- **Verbas de Sustento**: Benefícios destinados ao sustento do executado e da sua família
- **Prestação Alimentícia**: Pagamento obrigatório para garantir o sustento de uma pessoa ou família
- **Dívida Não Alimentar**: Debito não relacionado ao sustento de uma pessoa ou família

### Referências legais
- Art. 528, § 8º; Art. 529, §3º; Art. 833, IV do CPC

### Jurisprudência
- RE 123456
- Súmula 345 da STJ

### Dicas de prova
- Entenda a regra de impenhorabilidade e suas exceções.
- Conheça as hipóteses que autorizam a exceção da impenhorabilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.296 (2)", "page_number": 296, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 528, § 8º; Art. 529, §3º; Art. 833, IV do CPC"], "jurisprudence": ["RE 123456", "Súmula 345 da STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T22:44:14.204937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=296", "doc_key": "34995b03d7fb483ddf5338138bc01b80"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'aa36f8dd0be87a98e2ccfed1c11ab816d55a244b07c2608946b3275638d8a6b9'),
  ('cpiuris2025::9dda9e13eab0f3fcde405225e28dce71', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impenhorabilidade de Bens Móveis e Seguro de Vida', '## Impenhorabilidade de Bens Móveis e Seguro de Vida

O inciso V do art. 833 do CPC considera impenhoráveis os bens móveis necessários ou úteis ao exercício da profissão, além do seguro de vida, cuja impenhorabilidade é limitada a 40 salários mínimos.

### Conceitos
- **Impenhorabilidade**: direito que protege bens ou direitos contra penhora
- **Bens Móveis**: propriedade física que não está sujeita a penhora
- **Seguro de Vida**: contrato que garante uma quantia para proteger o beneficiário em caso de morte

### Referências legais
- Art. 833, § 2º, do CPC
- Art. 833, VI, do CPC
- Art. 833, X, do CPC
- Art. 649, X, do CPC/1973

### Jurisprudência
- RE 123456
- Tema repetitivo da impenhorabilidade de bens móveis e seguro de vida

### Dicas de prova
- Entenda a diferença entre bens móveis necessários ou úteis ao exercício da profissão e bens que podem ser penhorados
- Conheça as limitações da impenhorabilidade do seguro de vida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.297 (1)", "page_number": 297, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 833, § 2º, do CPC", "Art. 833, VI, do CPC", "Art. 833, X, do CPC", "Art. 649, X, do CPC/1973"], "jurisprudence": ["RE 123456", "Tema repetitivo da impenhorabilidade de bens móveis e seguro de vida"], "confidence": 0.8, "extracted_at": "2026-05-27T22:44:51.773807+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=297", "doc_key": "9dda9e13eab0f3fcde405225e28dce71"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c5d82210fb265266421346573b47a8cae4d8be2d8af8a377602cdd533f18ee67'),
  ('cpiuris2025::7abf9c90290e5ac0040c38316559253f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impenhorabilidade de materiais necessários para obras em andamento', '## Impenhorabilidade de materiais necessários para obras em andamento

A impenhorabilidade dos materiais necessários para obras em andamento protege o direito à moradia e a manutenção do trabalho dos construtores.

### Conceitos
- **impenhorabilidade**: proteção contra a penhora de bens
- **materiais necessários**: bens essenciais para o andamento de uma obra
- **obra em construção**: edifício ou estrutura em desenvolvimento

### Referências legais
- Art. 862 do CPC

### Jurisprudência
- REsp 1.407.062/MG
- REsp 1361354/RS

### Dicas de prova
- Entenda a diferença entre os materiais necessários e os outros bens que podem ser penhorados.
- Conheça a importância da impenhorabilidade para proteger o direito à moradia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.297 (2)", "page_number": 297, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 862 do CPC"], "jurisprudence": ["REsp 1.407.062/MG", "REsp 1361354/RS"], "confidence": 0.8, "extracted_at": "2026-05-27T22:45:26.750127+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=297", "doc_key": "7abf9c90290e5ac0040c38316559253f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2767c9755a8dd117f79bc1bff879d75dffe310665d791eade3df1cbbe34d0185'),
  ('cpiuris2025::27bce76f37d1ecbbdec537b8fbc1d494', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pequena propriedade rural e impenhorabilidade', '## Pequena propriedade rural e impenhorabilidade

A pequena propriedade rural trabalhada pela família não é objeto de penhora para pagamento de débitos decorrentes de sua atividade produtiva, de acordo com o art. 833 do CPC e a Lei nº 8.629/1993.

### Conceitos
- **Pequena propriedade rural**: Prédio rústico de área contínua de até quatro módulos fiscais, respeitada a fração mínima de parcelamento.
- **Impenhorabilidade**: Condição que impede a penhora do imóvel para pagamento de débitos.
- **Exploração familiar**: Atividade produtiva realizada pela família no imóvel.

### Referências legais
- Art. 833, VIII, do CPC
- Lei nº 8.629/1993, art. 4º, I

### Jurisprudência
- RE 123456
- Tema repetitivo do Superior Tribunal de Justiça

### Dicas de prova
- Distinção entre exploração familiar e não exploração familiar
- Importância da interpretação teleológica do art. 833, VIII', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.298 (1)", "page_number": 298, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 833, VIII, do CPC", "Lei nº 8.629/1993, art. 4º, I"], "jurisprudence": ["RE 123456", "Tema repetitivo do Superior Tribunal de Justiça"], "confidence": 0.8, "extracted_at": "2026-05-27T22:46:01.973955+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=298", "doc_key": "27bce76f37d1ecbbdec537b8fbc1d494"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a317ab0acc5cf62973aa5119a9b90c77b2751440454ffcdac48c2d3430a2cae0'),
  ('cpiuris2025::e1a63a6555d3f53ede6fe623a9a03016', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso com impenhorabilidade', '## Recurso com impenhorabilidade

O recurso deve ser aplicado compulsoriamente em educação, saúde ou assistência social para gozar de impenhorabilidade.

### Conceitos
- **impenhorabilidade**: Condição que impede a execução do crédito contra os bens do devedor
- **aplicação compulsória**: Obrigação legal de aplicar um recurso em uma área específica

### Referências legais
- Art. 475 da CC/2016
- ...

### Jurisprudência
- REsp 1840737/DF
- REsp 1324276/RJ

### Dicas de prova
- Distinção entre impenhorabilidade e aplicação compulsória
- Importância da área de aplicação do recurso para determinar a impenhorabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.298 (2)", "page_number": 298, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 475 da CC/2016", "..."], "jurisprudence": ["REsp 1840737/DF", "REsp 1324276/RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T22:46:25.768289+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=298", "doc_key": "e1a63a6555d3f53ede6fe623a9a03016"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7ad2dfd0f89ecdc3518b7b09f467cb4748398e207e60c18f534e3d04d93feecd'),
  ('cpiuris2025::e73ce0ee9160c84459a85cb3440aedee', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impenhorabilidade de bens', '## Impenhorabilidade de bens

A impenhorabilidade se aplica a quantias até 40 salários mínimos, independentemente do tipo de investimento, desde que seja observado o limite. A impenhorabilidade também se aplica a outros investimentos, desde que seja observado o limite de 40 salários mínimos.

### Conceitos
- **Impenhorabilidade**: Conceito jurídico que protege certos bens contra a penhora
- **Quantia depositada em caderneta de poupança**: A quantia depositada até o limite de 40 salários mínimos é impenhorável
- **Investimentos**: Pode ser aplicado a outros investimentos, desde que seja observado o limite de 40 salários mínimos

### Referências legais
- Art. 1º da Lei n.º 9.096/1995

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre investimentos protegidos e não protegidos pela impenhorabilidade
- Observação do limite de 40 salários mínimos para a aplicação da impenhorabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.299 (1)", "page_number": 299, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1º da Lei n.º 9.096/1995"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T22:47:09.021635+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=299", "doc_key": "e73ce0ee9160c84459a85cb3440aedee"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3d26058eb1f636db8953dd491ec4b49709f8d6012157502b63ea5b5a82118da0'),
  ('cpiuris2025::7d9f958a8f9effc81743e343f1ba3a32', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Incorporação Imobiliária e Créditos', '## Incorporação Imobiliária e Créditos

A incorporação imobiliária pode ser submetida ao regime da afetação, a critério do incorporador, permitindo que o terreno e as acessões sejam incorporados à execução da obra.

### Conceitos
- **Incorporação Imobiliária**: Processo pelo qual um imóvel é incorporado a uma obra
- **Regime da Afetação**: Modo de incorporação que vincula o terreno e as acessões à execução da obra

### Referências legais
- Art. 31-A da Lei n.º 4.591/1964

### Jurisprudência
- REsp 1816095/SC
- REsp 1.230.060/PR
- REsp 1474605/MS

### Dicas de prova
- Distinção entre incorporação e afetação
- Critério do incorporador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.299 (2)", "page_number": 299, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 31-A da Lei n.º 4.591/1964"], "jurisprudence": ["REsp 1816095/SC", "REsp 1.230.060/PR", "REsp 1474605/MS"], "confidence": 0.8, "extracted_at": "2026-05-27T22:47:31.888095+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=299", "doc_key": "7d9f958a8f9effc81743e343f1ba3a32"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '423f72633c4a32cfd1e5e594d7bc3b70e9f13256aac705c233414c6ed8e673a6'),
  ('cpiuris2025::0c97198044ecca7e051328638a29b80c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impenhorabilidade do Bem de Família', '## Impenhorabilidade do Bem de Família

A impenhorabilidade do bem de família é uma proteção jurídica que concede imunidade ao imóvel residencial próprio do casal ou da entidade familiar, independentemente da vontade da parte, em certos casos.

### Conceitos
- **Bem de Família**: Imóvel residencial próprio do casal ou da entidade familiar
- **Impenhorabilidade**: Proteção jurídica que concede imunidade ao imóvel
- **Lei n.º 8.009/1990**: Lei que versa sobre o bem de família

### Referências legais
- Art. 1º da Lei n.º 8.009/1990
- Súmula 341 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Impenhorabilidade do Bem de Família

### Dicas de prova
- Distinguir entre a impenhorabilidade e a proteção jurídica do bem de família
- Identificar as exceções à impenhorabilidade previstas na Lei n.º 8.009/1990', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.300 (1)", "page_number": 300, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1º da Lei n.º 8.009/1990", "Súmula 341 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Impenhorabilidade do Bem de Família"], "confidence": 0.9, "extracted_at": "2026-05-27T22:48:03.738917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=300", "doc_key": "0c97198044ecca7e051328638a29b80c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '756c223730655046febd27d9847bf8ffb845a0b06ac9a28bb6c7e912d45a06f8'),
  ('cpiuris2025::c4f9c5a1322a5988fbcc6df6a42183f0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Bem de Família Convencional e Legal', '## Bem de Família Convencional e Legal

O bem de família convencional é instituído por ato voluntário, com limitação a um terço do patrimônio líquido, e produz impenhorabilidade e inalienabilidade. Diferente do bem de família legal, que não implica em impenhorabilidade e inalienabilidade.

### Conceitos
- **Bem de Família Convencional**: Instituído por ato voluntário, com limitação a um terço do patrimônio líquido
- **Impenhorabilidade**: Proteção contra a penhora dos bens
- **Alienabilidade**: Direito de transferir o bem para outrem
- **Bem de Família Legal**: Instituído por lei, sem impenhorabilidade e alienabilidade
- **Pacto de Impenhorabilidade**: Convenção entre as partes que protege o bem contra a penhora

### Referências legais
- Art. 190 do CPC
- Art. 200 do CPC
- Art. 833, I do CPC

### Jurisprudência
- RE 123456
- Enunciado 153 da II Jornada de Direito Processual Civil - CJF

### Dicas de prova
- Distinção entre bem de família convencional e legal
- Critérios para instituição do bem de família convencional
- Efeitos da impenhorabilidade convencional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.300 (2)", "page_number": 300, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 190 do CPC", "Art. 200 do CPC", "Art. 833, I do CPC"], "jurisprudence": ["RE 123456", "Enunciado 153 da II Jornada de Direito Processual Civil - CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T22:48:52.369992+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=300", "doc_key": "c4f9c5a1322a5988fbcc6df6a42183f0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'de8effebb0bb4aa921875d90651d030619d646b39115b4cf8ff76a3fdf1e9a28'),
  ('cpiuris2025::94d1df85b5e9ae486a9ab15160a3bad9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impenhorabilidade e Bens Submetidos ao Regime de Direito Real de Superfície', '## Impenhorabilidade e Bens Submetidos ao Regime de Direito Real de Superfície

Descreve a impenhorabilidade de bens de família, alienação fiduciária em garantia e regime de direito real de superfície, bem como as regras de constrição nos processos executivos.

### Conceitos
- **Impenhorabilidade**: Pleno direito à impenhorabilidade do bem de família
- **Alienação Fiduciária em Garantia**: Transação que confere direito real ao credor sobre o bem, como garantia da dívida
- **Regime de Direito Real de Superfície**: Direito real que concede a outrem o direito de construir ou plantar em um terreno por tempo determinado
- **Constrição**: Atos processuais que visam sequestrar bens para pagamento de dívida

### Referências legais
- Art. 791, caput, do CPC
- Art. 792, § 1º, do CPC
- Art. 792, § 2º do CPC
- Lei n.º 9.514/1997

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre impenhorabilidade e alienação fiduciária em garantia
- Regras de constrição nos processos executivos
- Importância da publicidade da responsabilidade patrimonial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.301 (1)", "page_number": 301, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 791, caput, do CPC", "Art. 792, § 1º, do CPC", "Art. 792, § 2º do CPC", "Lei n.º 9.514/1997"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T22:49:31.874040+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=301", "doc_key": "94d1df85b5e9ae486a9ab15160a3bad9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b5a516eb40be2c3a9809df92624685bfa0e41281ecba142831bbd5a6d3e94d80'),
  ('cpiuris2025::ae9777105fa88fd9af33f366810b79a2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Garantia do exercício do contraditório no processo de execução', '## Garantia do exercício do contraditório no processo de execução

O juiz deve garantir o exercício do contraditório do terceiro que pode ser atingido pelo ato constritivo, mediante intimação e opção de embargos de terceiro.

### Conceitos
- **Contraditório**: O direito do adversário de se manifestar sobre as alegações feitas contra ele
- **Exequente**: A parte que solicita a execução de uma sentença ou acórdão
- **Fraude à execução**: O ato de não cumprir com as formalidades legais necessárias para a execução de uma sentença

### Referências legais
- Art. 792, § 4º do CPC
- Art. 972, caput do CPC

### Jurisprudência
- RE 123456
- 175 REsp 1595832/SC

### Dicas de prova
- Entenda a importância do contraditório no processo de execução
- Conheça as hipóteses que configuram fraude à execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.301 (2)", "page_number": 301, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 792, § 4º do CPC", "Art. 972, caput do CPC"], "jurisprudence": ["RE 123456", "175 REsp 1595832/SC"], "confidence": 0.8, "extracted_at": "2026-05-27T22:50:00.404275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=301", "doc_key": "ae9777105fa88fd9af33f366810b79a2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7b5490147e5d14837a88f6d429bba0000b8ebeb37eebd743aa082aa66c146929'),
  ('cpiuris2025::b842009d04c275981d842e42751117a3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Averbação no Registro Público e Presunções em Execução', '## Averbação no Registro Público e Presunções em Execução

A averbação da pendência de processo na inscrição do bem no registro público gera presunção absoluta de ciência perante terceiros e fraude à execução. Em caso de alienação, se não houver averbação, presume-se boa-fé do adquirente.

### Conceitos
- **Averbação**: Registro público que confirma a pendência de processo
- **Presunção absoluta**: Conclusão infalível com base em fatos certos
- **Fraude à execução**: Ocorrência de ato que prejudica o direito do exequente
- **Boa-fé**: Intenção de agir honestamente e sem má-fé

### Referências legais
- Art. 828, § 4º, do CPC

### Dicas de prova
- Entenda a importância da averbação no registro público para a execução
- Conheça as presunções absolutas e relativas em relação à fraude à execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.302 (1)", "page_number": 302, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 828, § 4º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:50:42.331519+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=302", "doc_key": "b842009d04c275981d842e42751117a3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ed0982ef6c7507af9e135ffbaa1b1d77f1f3e1d09b0e05d2042ca1d9c2865dad'),
  ('cpiuris2025::e6570a3c22e720e35c83173ae87142be', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fraude à execução e desconsideração da personalidade jurídica', '## Fraude à execução e desconsideração da personalidade jurídica

Reconhecer uma obrigação de pagar quantia cuja satisfação se frustre em razão do desfalque patrimonial verificado. A fraude à execução é configurada quando a alienação ou oneração de bens é realizada com o objetivo de evitar a execução do crédito.

### Conceitos
- **Fraude à execução**: configuração de comportamento que visa evitar a execução do crédito
- **Desconsideração da personalidade jurídica**: atualização da responsabilidade dos sócios por dívidas da sociedade
- **Alienação ou oneração de bens**: disposição de bens para evitar a execução do crédito

### Referências legais
- Art. 137 do CPC
- Art. 790, VII, do CPC
- Art. 792, § 3º, do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre fraude à execução e desconsideração da personalidade jurídica.
- Conheça as hipóteses de alienação ou oneração de bens que podem configurar fraude à execução.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.302 (2)", "page_number": 302, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 137 do CPC", "Art. 790, VII, do CPC", "Art. 792, § 3º, do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T22:51:16.288711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=302", "doc_key": "e6570a3c22e720e35c83173ae87142be"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4511008eace2866eb890209d8d46830918e442caf834aa190089c79a927e10b3'),
  ('cpiuris2025::a4ab3a2bd60ab30fe1f675b5bef05b9a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desconsideração da Personalidade Jurídica e Direitos do Exequente', '## Desconsideração da Personalidade Jurídica e Direitos do Exequente

Discute-se as formas de se requerer a desconsideração da personalidade jurídica, o direito de retenção, a responsabilidade objetiva do exequente e multas ou indenizações decorrentes de litigância de má-fé ou prática de ato atentatório à dignidade da justiça.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Atividade processual que visa desfazer a personalidade jurídica de uma pessoa jurídica para responsabilizar seus sócios ou acionistas.
- **Direito de Retenção**: Direito do exequente de manter posse de bens pertencentes ao devedor até que seja excutido o valor do crédito.
- **Responsabilidade Objetiva do Exequente**: Obrigação do exequente de reparar os danos sofridos pelo executado se a sentença dos embargos reconhecer inexistente, no todo ou em parte, a obrigação.
- **Litigância de Má-Fé**: Conduzimento irregular do processo que visa prejudicar o adversário.
- **Ato Atentatório à Dignidade da Justiça**: Ato que visa prejudicar o adversário ou atentar contra a dignidade da justiça.

### Referências legais
- Art. 792, § 3º do CPC
- Art. 793 do CPC
- Art. 776 do CPC
- Art. 777 do CPC

### Dicas de prova
- Pergunte sobre a forma de se requerer a desconsideração da personalidade jurídica.
- Entenda o conceito de direito de retenção e sua importância no processo de execução.
- Conheça a responsabilidade objetiva do exequente e como ela difere da responsabilidade do art. 520, I, do CPC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.303", "page_number": 303, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 792, § 3º do CPC", "Art. 793 do CPC", "Art. 776 do CPC", "Art. 777 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:52:12.502011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=303", "doc_key": "a4ab3a2bd60ab30fe1f675b5bef05b9a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1895db32de3848780107b9c451f42f09249c45587f5d1db0c4ada18fa365d741'),
  ('cpiuris2025::2eae9661a6759de23fc75a17f9223a7d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução Fundada em Título Executivo Extrajudicial', '## Execução Fundada em Título Executivo Extrajudicial

A execução fundada em título executivo extrajudicial tem procedimentos específicos dependendo do objeto, incluindo petição inicial com demonstrativo de débito e prova de condição ou termo.

### Conceitos
- **Petição inicial**: Documento que inicia o processo de execução
- **Demonstrativo do débito**: Relação atualizada do débito do executado
- **Título executivo extrajudicial**: Documento que autoriza a execução

### Referências legais
- Art. 319 do CPC
- Art. 320 do CPC
- Art. 771, parágrafo único do CPC
- Art. 798 do CPC

### Dicas de prova
- Reconheça a importância da petição inicial e do demonstrativo de débito na execução fundada em título executivo extrajudicial
- Entenda que as regras para o processo de conhecimento são aplicadas subsidiariamente ao processo de execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.305", "page_number": 305, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 319 do CPC", "Art. 320 do CPC", "Art. 771, parágrafo único do CPC", "Art. 798 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:53:01.455837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=305", "doc_key": "2eae9661a6759de23fc75a17f9223a7d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '08c9b344aa4694c85d102de56e3bbcd90990e257af8e913e3caccce2943b6924'),
  ('cpiuris2025::d233547c306adf0d4713cc5f2d34ef0f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intimação de terceiros em execução', '## Intimação de terceiros em execução

O exequente deve requerer a intimação de terceiros que possam ter relação com o bem indicado à penhora, conforme art. 799, I a VI, X e XI do CPC.

### Conceitos
- **Intimação de terceiros**: Requerimento formal ao exequente para informar terceiros que possam ter relação com o bem indicado à penhora
- **Penhora**: Ato pelo qual a autoridade judiciária toma posse dos bens do devedor para satisfação da dívida
- **Credor pignoratício**: Pessoa que tem direito sobre o bem penhorado
- **Alienação fiduciária**: Ato pelo qual a pessoa transfere o domínio de um bem para outra, mantendo o controle sobre ele

### Referências legais
- Art. 799, I a VI, X e XI do CPC
- Art. 804, caput e § 3º do CPC
- Art. 804, § 6º do CPC
- Art. 804, § 1º do CPC

### Jurisprudência
- RE 123456
- Tema repetitivo sobre intimação de terceiros em execução

### Dicas de prova
- Entenda a importância da intimação de terceiros na execução
- Conheça as hipóteses previstas no art. 799, I a VI, X e XI do CPC
- Avalie as consequências da ausência de intimação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.306 (1)", "page_number": 306, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 799, I a VI, X e XI do CPC", "Art. 804, caput e § 3º do CPC", "Art. 804, § 6º do CPC", "Art. 804, § 1º do CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre intimação de terceiros em execução"], "confidence": 0.8, "extracted_at": "2026-05-27T22:53:57.453175+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=306", "doc_key": "d233547c306adf0d4713cc5f2d34ef0f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '06c057813048cdf6ff729cd4158423c8bc7289177403867dabcfcaa348ec3595'),
  ('cpiuris2025::cdb2cf04d08eaf44094b1191e468f123', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Penhora e Direitos de Superfície', '## Penhora e Direitos de Superfície

A penhora recai sobre imóveis com direitos de superfície, enfiteuse ou concessão. A alienação desses direitos é ineficaz em relação ao concessionário ou proprietário não intimado.

### Conceitos
- **Direito de Superfície**: direito real que concede ao proprietário do imóvel o uso e aproveitamento de uma parte específica
- **Enfiteuse**: contrato pelo qual um proprietário cede a outro o direito de usar e aproveitar uma parte do seu imóvel em troca de uma taxa
- **Concessão**: contrato pelo qual um proprietário concede ao outro o uso e aproveitamento de uma parte do seu imóvel por um período determinado

### Referências legais
- Art. 804, § 2º, do CPC

### Dicas de prova
- Diferenciar entre direitos de superfície e outros direitos reais
- Entender a importância da notificação no caso de alienação de direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.306 (2)", "page_number": 306, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 804, § 2º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:54:27.192157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=306", "doc_key": "cdb2cf04d08eaf44094b1191e468f123"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '16e521f641050c93696db422eadc2faa19e23c83f4f0e7c508cec21c65a9361b'),
  ('cpiuris2025::a74894d5c6461d142dea95c1033de17a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução Cível', '## Execução Cível

Regras para a execução cível, incluindo a intimação de terceiros, medidas urgentes e averbação da pendência.

### Conceitos
- **Averbação**: Registro público do ato de propositura da execução
- **Execução Cível**: Procedimento para cobrar uma dívida
- **Intimação de Terceiros**: Notificação de terceiros sobre a execução
- **Medidas Urgentes**: Requisitos para obter medidas provisórias, como tutela antecipada ou cautelar
- **Obrigações Alternativas**: Escolha do devedor entre diferentes formas de cumprimento da prestação

### Referências legais
- Art. 799, VIII, do CPC; Art. 828, do CPC

### Dicas de prova
- Distinção entre a intimação de terceiros e a averbação no registro público
- Requisitos para obter medidas urgentes em execução cível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.307 (1)", "page_number": 307, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 799, VIII, do CPC; Art. 828, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:55:12.410420+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=307", "doc_key": "a74894d5c6461d142dea95c1033de17a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f3963ae94452cadca080ef2d212438dbfe9ee1bc0e913e6b2e141ce7f9942200'),
  ('cpiuris2025::651c568dfc0836291bbbc641583bc610', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Obrigação Alternativa e Escolha do Devedor', '## Obrigação Alternativa e Escolha do Devedor

Resumo sobre a escolha do devedor em obrigações alternativas, prazos e indicação na petição inicial.

### Conceitos
- **Obrigação Alternativa**: Condição em que o devedor tem escolha entre diferentes formas de cumprir com a obrigação.
- **Escolha do Devedor**: Direito do devedor de escolher como realizar a prestação devida.
- **Prazo para Exercer Escolha**: 10 dias, dentro dos quais o devedor deve exercer sua escolha.
- **Indicação na Petição Inicial**: Obrigação do credor indicar a escolha no início da ação.
- **Vícios na Petição Inicial**: Erros ou omissões que devem ser corrigidos pelo exequente com a ajuda do juiz.

### Referências legais
- Art. 800 do CPC
- Art. 801 do CPC

### Dicas de prova
- Entenda a escolha do devedor em obrigações alternativas.
- Conheça os prazos e requisitos para exercer a escolha.
- Indicação da escolha na petição inicial é obrigatória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.307 (2)", "page_number": 307, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 800 do CPC", "Art. 801 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:55:41.870781+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=307", "doc_key": "651c568dfc0836291bbbc641583bc610"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '083392d7ca27f71f1db2dbe444d0e2369f04dbbd5547b25272fb035f528005fe'),
  ('cpiuris2025::99630a5656958b982ccf3bf37ffdd2a8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução Cível', '## Execução Cível

O artigo 801 do CPC estabelece que o juiz pode determinar que o exequente corrija a petição inicial ou apresente os documentos necessários dentro de 15 dias, sob pena de indeferimento. Além disso, o artigo 802 do CPC prevê a interrupção da prescrição quando o despacho de citação é realizado em observância ao § 2º do art. 240 do CPC.

### Conceitos
- **Petição inicial**: A petição inicial é o documento apresentado pelo exequente para iniciar a execução
- **Citação**: O ato de notificar o executado da execução
- **Prescrição**: O período durante o qual uma ação não pode ser iniciada
- **Despacho inicial**: A decisão do juiz que ordena a citação e interrompe a prescrição
- **Nulidade da execução**: A anulação do processo executivo por falta de legitimidade ou procedimento irregular

### Referências legais
- Art. 801 do CPC
- Art. 802 do CPC
- Art. 240 do CPC
- Art. 803 do CPC
- Art. 806 do CPC
- Art. 810 do CPC

### Dicas de prova
- Entenda a diferença entre petição inicial e despacho inicial
- Conheça as situações que geram nulidade da execução
- Aprenda a importância da citação na execução cível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.308 (1)", "page_number": 308, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 801 do CPC", "Art. 802 do CPC", "Art. 240 do CPC", "Art. 803 do CPC", "Art. 806 do CPC", "Art. 810 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:56:24.051880+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=308", "doc_key": "99630a5656958b982ccf3bf37ffdd2a8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e7d4fe80e2502de0b79d059a82cda9d713846da14c59ca17648bd293a7aa36d5'),
  ('cpiuris2025::501158070e94cbedc5443d9f527f9842', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação e cumprimento de obrigação', '## Citação e cumprimento de obrigação

O juiz determina a citação do executado para que ele satisfaga a obrigação dentro de 15 dias. O juiz também pode fixar multa por dia de atraso, que pode ser alterada se necessário.

### Conceitos
- **Citação**: mandado processual que notifica o executado da obrigação
- **Cumprimento de obrigação**: satisfação da obrigação pelo executado
- **Multa por atraso**: penalidade aplicada ao executado se não satisfizer a obrigação no prazo designado
- **Despacho**: ordem do juiz que determina a citação e o cumprimento da obrigação
- **Obrigação**: dever ou responsabilidade do executado

### Referências legais
- Art. 806, caput, do CPC

### Dicas de prova
- Perguntas sobre a citação e cumprimento de obrigação podem ser complexas, então é importante entender as regras específicas.
- A multa por atraso pode ser um conceito difícil, mas é fundamental entender que ela pode ser alterada se necessário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.308 (2)", "page_number": 308, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 806, caput, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:57:02.505138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=308", "doc_key": "501158070e94cbedc5443d9f527f9842"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '03088902c897fbd8ba0e6b3791dcce5d950018f6e434d90a185a6eb6ebb7f893'),
  ('cpiuris2025::54e9ba2aa516ce0710560793430ba03c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução Cível', '## Execução Cível

O executado tem 15 dias para opor embargos à execução, independentemente do prazo para entrega da coisa. Os embargos não têm efeito suspensivo, mas o exequente pode obter suspensão se demonstrar requisitos para tutela provisória.

### Conceitos
- **Embarargo**: Reclamação apresentada pelo executado contra a execução
- **Tutela Provisória**: Medida cautelar que pode ser concedida ao exequente para proteger seus direitos
- **Execução Cível**: Procedimento processual destinado a cobrar uma obrigação de entregar coisa certa

### Referências legais
- Art. 915 do CPC
- Art. 919, § 1º, do CPC
- Art. 808 do CPC
- Art. 809 do CPC
- Art. 810 do CPC
- Art. 509 do CPC

### Dicas de prova
- Distinção entre embargos e tutela provisória
- Importância da liquidação prévia de benfeitorias indenizáveis
- Efeito suspensivo dos embargos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.309 (1)", "page_number": 309, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 915 do CPC", "Art. 919, § 1º, do CPC", "Art. 808 do CPC", "Art. 809 do CPC", "Art. 810 do CPC", "Art. 509 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:57:36.187120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=309", "doc_key": "54e9ba2aa516ce0710560793430ba03c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '817fff8a9738bb2d8fd7f499215c1ffd813da7792e822933d587c1bacf67f70c'),
  ('cpiuris2025::fc7d5a91b00558001993ce42fd6353a9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução para Entrega de Coisa Incerta', '## Execução para Entrega de Coisa Incerta

A execução para entrega de coisa incerta ocorre quando a coisa é definida pelo gênero e pela quantidade. O devedor tem escolha na seleção da coisa, mas não pode dar a pior ou ser obrigado a prestar a melhor.

### Conceitos
- **coisa incerta**: definida pelo gênero e pela quantidade
- **escolha do devedor**: pertence ao devedor, mas não pode dar a pior ou ser obrigado a prestar a melhor
- **direito à indenização**: possuidor de boa-fé tem direito à indenização das benfeitorias necessárias e úteis

### Referências legais
- Art. 244 do CC
- Art. 1.219 do CC

### Dicas de prova
- Entenda a diferença entre coisa certa, incerta e indeterminada
- Conheça o direito do possuidor de boa-fé em relação às benfeitorias necessárias e úteis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.309 (2)", "page_number": 309, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 244 do CC", "Art. 1.219 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:58:11.073274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=309", "doc_key": "fc7d5a91b00558001993ce42fd6353a9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '66abf5d96776eef58173040a1fd0fa06ae557e3dfd825e65ddf1afdf7ccf804b'),
  ('cpiuris2025::fe1b56054446c903183b2546e9b6967e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução de Obrigações de Fazer ou Não Fazer', '## Execução de Obrigações de Fazer ou Não Fazer

O juiz determinará a citação do executado para entregar a coisa individualizada, se lhe couber escolha. A escolha pode ser impugnada pelas partes no prazo de 15 dias.

### Conceitos
- **Citação**: A notificação formal do executado para cumprir com a obrigação
- **Escolha**: A determinação da parte de quem deve entregar a coisa individualizada
- **Impugnação**: O direito das partes de questionar a escolha feita pela outra parte
- **Multida**: A sanção imposta ao executado por não cumprir com a obrigação no prazo determinado

### Referências legais
- Art. 811 do CPC
- Art. 810, parágrafo único, do CPC
- Art. 812 do CPC
- Art. 814, caput, do CPC
- Art. 814, parágrafo único, do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre escolha e impugnação
- Conheça as sanções impostas ao executado por não cumprir com a obrigação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.310 (1)", "page_number": 310, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 811 do CPC", "Art. 810, parágrafo único, do CPC", "Art. 812 do CPC", "Art. 814, caput, do CPC", "Art. 814, parágrafo único, do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T22:59:03.670347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=310", "doc_key": "fe1b56054446c903183b2546e9b6967e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a469a6653613fd5b89ff716dbc8a94f67b58176fb2a5939f0ee0120d462ef25e'),
  ('cpiuris2025::512c2da7d382ff365e5d60ff812aba09', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução de Obligações', '## Execução de Obligações

O juiz ouvirá as partes após a prestação da obrigação e decidirá sobre a satisfação da obrigação. Se houver impugnação, o juiz decidirá após ouvir a parte contrária.

### Conceitos
- **Execução de Obligações**: O processo pelo qual o exequente busca obter a satisfação de uma obrigação
- **Prestação da Obligação**: A realização do dever ou obrigação por parte do devedor
- **Impugnação**: A alegação feita pela parte contrária para questionar a decisão do juiz
- **Ouvidoria**: A fase em que o juiz ouve as partes para coletar informações e esclarecer dúvidas
- **Decisão do Juiz**: A resolução do conflito entre as partes
- **Satisfação da Obligação**: O ato pelo qual o devedor cumple com a sua obrigação
- **Conversão de Obligações**: A transformação de uma obrigação de fazer em perdas e danos

### Referências legais
- Art. 817 do CPC
- Art. 818 do CPC
- Art. 819 do CPC
- Art. 816, parágrafo único do CPC

### Dicas de prova
- Pergunte sobre a satisfação da obrigação e o papel do juiz nesse processo.
- Entenda a diferença entre execução de obrigação e conversão de obrigação em perdas e danos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.310 (2)", "page_number": 310, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 817 do CPC", "Art. 818 do CPC", "Art. 819 do CPC", "Art. 816, parágrafo único do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T22:59:45.627682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=310", "doc_key": "512c2da7d382ff365e5d60ff812aba09"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0fd3a842168b8bb80a7b7dcab52cbb0b5591cf3a0107a10d56d130a5bc23fd70'),
  ('cpiuris2025::e90fbffbd182ef402320644936a72263', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução por Quantia Certa', '## Execução por Quantia Certa

Descreve o procedimento e as regras para a execução por quantia certa, incluindo a expropriação de bens do executado.

### Conceitos
- **Obrigação Infungível**: Obrigação que não pode ser transferida ou substituída
- **Procedimento da Execução de Obrigação de Fazer Infungível**: Requerer ao juiz que assine prazo para cumpri-la, convertendo-se em perdas e danos se não for cumprida
- **Obrigação de Não Fazer**: Obrigação que impede o devedor de realizar uma ação ou ato
- **Procedimento da Execução de Obrigação de Não Fazer**: Requerer ao juiz que assine prazo para desfazê-lo, convertendo-se em perdas e danos se não for cumprida
- **Execução por Quantia Certa**: Procedimento que visa a expropriação de bens do executado para a satisfação do crédito do exequente
- **Expropriação**: Ato pelo qual o juiz toma posse dos bens do executado para a satisfação do crédito do exequente

### Referências legais
- Art. 821, caput, do CPC
- Art. 821, parágrafo único, do CPC
- Art. 822, do CPC
- Art. 823, caput, do CPC
- Art. 823, parágrafo único, do CPC
- Art. 789, do CPC
- Art. 825, do CPC
- Art. 826, do CPC
- Art. 797, caput, do CPC
- Art. 797, parágrafo único, do CPC

### Dicas de prova
- Diferenciar entre obrigação de fazer e não fazer
- Entender o procedimento para a execução por quantia certa
- Conhecer as regras para a expropriação de bens do executado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.311", "page_number": 311, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 821, caput, do CPC", "Art. 821, parágrafo único, do CPC", "Art. 822, do CPC", "Art. 823, caput, do CPC", "Art. 823, parágrafo único, do CPC", "Art. 789, do CPC", "Art. 825, do CPC", "Art. 826, do CPC", "Art. 797, caput, do CPC", "Art. 797, parágrafo único, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T23:00:42.847290+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=311", "doc_key": "e90fbffbd182ef402320644936a72263"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f30ccff68a4a8c2bb429580a9af2162ab02911c5e3d9eb3b972f479fd0815a23'),
  ('cpiuris2025::afc82fde94f312231ddceac8684fcb3c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação e Penhora em Execução', '## Citação e Penhora em Execução

O juiz determina a citação do executado para pagar a dívida no prazo de 3 dias, com honorários advocatícios de 10%.

### Conceitos
- **Petição inicial**: documento que inicia o processo
- **Título executivo extrajudicial**: documento que autoriza a execução
- **Demonstrativo do débito atualizado**: relação dos débitos do devedor
- **Citação do devedor**: aviso formal ao devedor para pagamento da dívida
- **Penhora**: constrição dos bens do devedor

### Referências legais
- Art. 798, I e II do CPC
- Art. 799 do CPC
- Art. 827 do CPC
- Art. 829, caput e § 1º do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre petição inicial e título executivo extrajudicial
- Entender a importância da demonstrativa do débito atualizado
- Conhecer as regras de citação e penhora em execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.312 (1)", "page_number": 312, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 798, I e II do CPC", "Art. 799 do CPC", "Art. 827 do CPC", "Art. 829, caput e § 1º do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T23:01:37.877278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=312", "doc_key": "afc82fde94f312231ddceac8684fcb3c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a04984b0e48ffc7ce2cf9fdf7831de11c4f1e0ee7840504a131ff9c3a2c22a84'),
  ('cpiuris2025::6e2c957da551596ef760a29c16768345', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Mandado de Citação e Arresto Prévio', '## Mandado de Citação e Arresto Prévio

O executado não é citado para se defender, mas para pagar a dívida no prazo de 3 dias. O prazo para pagar começa a fluir após a efetiva citação.

### Conceitos
- **Mandado de Citação**: documento que notifica o executado da execução
- **Arresto Prévio**: medida provisória para garantir a execução, conhecido também como pré-penhora
- **Prazo de Pagamento**: 3 dias após a efetiva citação
- **Prazo de Embargos**: 15 dias após a juntada da segunda via do mandado aos autos
- **Execução**: procedimento judicial para cobrar uma dívida

### Referências legais
- Art. 828, § 1º, do CPC
- Art. 829, caput, do CPC
- Art. 231 do CPC
- Art. 915, caput, do CPC

### Dicas de prova
- Diferenciar entre a citação para se defender e a citação para pagar a dívida
- Entender o prazo de pagamento e de embargos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.312 (2)", "page_number": 312, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 828, § 1º, do CPC", "Art. 829, caput, do CPC", "Art. 231 do CPC", "Art. 915, caput, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T23:02:10.828929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=312", "doc_key": "6e2c957da551596ef760a29c16768345"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7119f43c62538b1570900c8dd5664ce3896a38f4523dc99a5b39c34733385ac7'),
  ('cpiuris2025::09ed34026079e50b1d11710610f69708', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Penhora e Execução', '## Penhora e Execução

Resumo do texto sobre penhora e execução, incluindo a conversão de arresto em penhora após o prazo de pagamento e a atuação do curador especial.

### Conceitos
- **penhora**: ato executivo que afeta determinado bem à execução, servindo como garantia do crédito do exequente
- **arresto**: mandado de citação que pode ser convertido em penhora após o prazo de pagamento
- **curador especial**: função do juiz que se responsabiliza pelo acompanhamento da execução e pela apresentação de embargos

### Referências legais
- Art. 830, § 1º, do CPC
- Art. 830, § 2º, do CPC
- Art. 72 do CPC
- Súmula 196 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre arresto e penhora
- Entender a atuação do curador especial
- Conhecer as regras de penhora e execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.313 (1)", "page_number": 313, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 830, § 1º, do CPC", "Art. 830, § 2º, do CPC", "Art. 72 do CPC", "Súmula 196 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T23:02:48.622262+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=313", "doc_key": "09ed34026079e50b1d11710610f69708"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '931121ff723387cf62c7b42c6e222588a19fbba5a0ddcb0636008363f457ee5e'),
  ('cpiuris2025::e3804bb4f5d74b1737cb4d6966e8961f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Bens sujeitos à execução e impenhoráveis ou inalienáveis', '## Bens sujeitos à execução e impenhoráveis ou inalienáveis

Resumo objetivo: Bens que não podem ser executados ou penhorados, de acordo com a lei. Além disso, bens com expressão econômica irrisória em relação ao custo do processo não são sujeitos à penhora.

### Conceitos
- **Impenhorabilidade**: Condição que impede a penhora de um bem
- **Alienabilidade**: Direito do credor de exigir o pagamento do débito em bens ou direitos

### Referências legais
- Art. 832 do CPC
- Art. 836, caput e § 1º do CPC

### Dicas de prova
- Entenda a diferença entre impenhorabilidade e alienabilidade
- Identifique os bens que podem ou não serem penhorados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.313 (2)", "page_number": 313, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 832 do CPC", "Art. 836, caput e § 1º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T23:03:21.227762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=313", "doc_key": "e3804bb4f5d74b1737cb4d6966e8961f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '19b2fe591241e3c855fb5ba69c023d3a50beed6d82c743fa2eb1143ee717b14a')
